import React, { lazy, Suspense } from 'react';
import { Routes, Route, Navigate, useLocation } from 'react-router-dom';
import Navbar from './components/Navbar';
import { AuthProvider } from './context/AuthContext';
import { ThemeProvider } from './context/ThemeContext';
import { ToastProvider } from './context/ToastContext';
import { NetworkStatusProvider } from './context/NetworkStatusContext';
import { OfflineBanner } from './components/OfflineBanner';
import ImpersonationBanner from './components/ImpersonationBanner';
import AnnouncementBanner from './components/AnnouncementBanner';
import { useAuth } from './context/AuthContext';

const Landing = lazy(() => import('./pages/Landing'));
const Home = lazy(() => import('./pages/Home'));
const CreateCampaign = lazy(() => import('./pages/CreateCampaign'));
const Campaign = lazy(() => import('./pages/Campaign'));
const CampaignEmbed = lazy(() => import('./pages/CampaignEmbed'));
const Widget = lazy(() => import('./pages/Widget'));
const Login = lazy(() => import('./pages/Login'));
const Register = lazy(() => import('./pages/Register'));
const ForgotPassword = lazy(() => import('./pages/ForgotPassword'));
const ResetPassword = lazy(() => import('./pages/ResetPassword'));
const AdminDashboard = lazy(() => import('./pages/AdminDashboard'));
const AcceptInvite = lazy(() => import('./pages/AcceptInvite'));
const Developer = lazy(() => import('./pages/Developer'));
const CampaignCompare = lazy(() => import('./components/CampaignCompare'));
const Dashboard = lazy(() => import('./pages/Dashboard'));
const Profile = lazy(() => import('./pages/Profile'));
const NotificationSettings = lazy(() => import('./pages/NotificationSettings'));
const TaxReceipts = lazy(() => import('./pages/TaxReceipts'));
const HowItWorks = lazy(() => import('./pages/HowItWorks'));
const Pricing = lazy(() => import('./pages/Pricing'));
const About = lazy(() => import('./pages/About'));
const Resources = lazy(() => import('./pages/Resources'));
const Leaderboard = lazy(() => import('./pages/Leaderboard'));
const NotFound = lazy(() => import('./pages/NotFound'));
const CreatorProfile = lazy(() => import('./pages/CreatorProfile'));
const CreatorAnalytics = lazy(() => import('./pages/CreatorAnalytics'));
const CreatorCampaignAnalytics = lazy(() => import('./pages/CreatorCampaignAnalytics'));
const Governance = lazy(() => import('./pages/Governance'));
const CampaignShare = lazy(() => import('./pages/CampaignShare'));
const ReferralDashboard = lazy(() => import('./pages/ReferralDashboard'));
const OpsCenter = lazy(() => import('./pages/OpsCenter'));
const ContributorIdentityPage = lazy(() => import('./pages/ContributorIdentityPage'));

function PrivateRoute({ children }) {
  const { user, ready } = useAuth();
  if (!ready) return null;
  return user ? children : <Navigate to="/login" replace />;
}

export default function App() {
  const location = useLocation();
  const hideNavbar =
    location.pathname.startsWith('/widget/') || location.pathname.startsWith('/embed/');

  return (
    <ThemeProvider>
      <AuthProvider>
        <ToastProvider>
          <NetworkStatusProvider>
            <OfflineBanner />
            {!hideNavbar && <ImpersonationBanner />}
            {!hideNavbar && <AnnouncementBanner />}
            {!hideNavbar && <Navbar />}
            <Suspense fallback={<div>Loading...</div>}>
              <Routes>
                <Route path="/" element={<Landing />} />
                <Route path="/discover" element={<Home />} />
                <Route path="/compare" element={<CampaignCompare />} />
                <Route path="/how-it-works" element={<HowItWorks />} />
                <Route path="/pricing" element={<Pricing />} />
                <Route path="/about" element={<About />} />
                <Route path="/resources" element={<Resources />} />
                <Route path="/leaderboard" element={<Leaderboard />} />
                <Route path="/creators/:id" element={<CreatorProfile />} />
                <Route
                  path="/campaigns/new"
                  element={
                    <PrivateRoute>
                      <CreateCampaign />
                    </PrivateRoute>
                  }
                />
                <Route path="/campaigns/:id" element={<Campaign />} />
                <Route path="/campaigns/:id/share" element={<CampaignShare />} />
                {/* Short share link handed out by the referral system (#675) */}
                <Route path="/c/:id" element={<Campaign />} />
                <Route path="/campaigns/:id/invite/:token" element={<AcceptInvite />} />
                <Route path="/embed/campaigns/:id" element={<CampaignEmbed />} />
                <Route path="/widget/campaigns/:id" element={<Widget />} />
                <Route path="/login" element={<Login />} />
                <Route path="/register" element={<Register />} />
                <Route path="/forgot-password" element={<ForgotPassword />} />
                <Route path="/reset-password" element={<ResetPassword />} />
                <Route
                  path="/admin"
                  element={
                    <PrivateRoute>
                      <AdminDashboard />
                    </PrivateRoute>
                  }
                />
                <Route
                  path="/developer"
                  element={
                    <PrivateRoute>
                      <Developer />
                    </PrivateRoute>
                  }
                />
                <Route
                  path="/dashboard"
                  element={
                    <PrivateRoute>
                      <Dashboard />
                    </PrivateRoute>
                  }
                />
                <Route
                  path="/dashboard/referrals"
                  element={
                    <PrivateRoute>
                      <ReferralDashboard />
                    </PrivateRoute>
                  }
                />
                <Route
                  path="/dashboard/analytics"
                  element={
                    <PrivateRoute>
                      <CreatorAnalytics />
                    </PrivateRoute>
                  }
                />
                <Route
                  path="/dashboard/analytics/:campaignId"
                  element={
                    <PrivateRoute>
                      <CreatorCampaignAnalytics />
                    </PrivateRoute>
                  }
                />
                <Route
                  path="/profile"
                  element={
                    <PrivateRoute>
                      <Profile />
                    </PrivateRoute>
                  }
                />
                <Route
                  path="/profile/identity"
                  element={
                    <PrivateRoute>
                      <ContributorIdentityPage />
                    </PrivateRoute>
                  }
                />
                <Route
                  path="/settings/notifications"
                  element={
                    <PrivateRoute>
                      <NotificationSettings />
                    </PrivateRoute>
                  }
                />
                <Route
                  path="/tax-receipts"
                  element={
                    <PrivateRoute>
                      <TaxReceipts />
                    </PrivateRoute>
                  }
                />
                <Route
                  path="/governance"
                  element={<Governance />}
                />
                <Route
                  path="/ops"
                  element={<OpsCenter />}
                />
                <Route
                  path="/my-contributions"
                  element={<Navigate to="/dashboard?tab=contributions" replace />}
                />
                <Route path="*" element={<NotFound />} />
              </Routes>
            </Suspense>
          </NetworkStatusProvider>
        </ToastProvider>
      </AuthProvider>
    </ThemeProvider>
  );
}

import React, { useEffect, useState } from 'react';
import { api } from '../services/api';

export default function ApiKeysPanel() {
  const [keys, setKeys] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [name, setName] = useState('');
  const [revealedKey, setRevealedKey] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [creating, setCreating] = useState(false);

  async function loadKeys() {
    setError('');
    try {
      const rows = await api.listApiKeys();
      setKeys(rows);
    } catch (err) {
      setError(err.message || 'Could not load API keys');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadKeys();
  }, []);

  async function handleCreate(e) {
    e.preventDefault();
    if (!name.trim()) return;
    setCreating(true);
    setError('');
    setRevealedKey('');
    try {
      const res = await api.createApiKey({ name: name.trim() });
      setRevealedKey(res.api_key);
      setName('');
      await loadKeys();
    } catch (err) {
      setError(err.message || 'Could not create API key');
    } finally {
      setCreating(false);
    }
  }

  async function revokeKey(id) {
    if (!window.confirm('Revoke this API key? Integrations using it will stop working immediately.')) return;
    setError('');
    try {
      await api.deleteApiKey(id);
      await loadKeys();
    } catch (err) {
      setError(err.message || 'Could not revoke API key');
    }
  }

  function copyKey() {
    if (!revealedKey) return;
    navigator.clipboard.writeText(revealedKey);
  }

  return (
    <section role="tabpanel" aria-labelledby="tab-api-keys">
      <p style={{ color: 'var(--color-text-hint)', marginBottom: '1rem', fontSize: '0.9rem' }}>
        Generate long-lived API keys for server-side integrations. Use{' '}
        <code>Authorization: Bearer cpk_…</code> on authenticated endpoints.
      </p>

      {error && <p style={{ color: 'var(--color-status-error)', marginBottom: '1rem' }}>{error}</p>}
      {loading && <p style={{ color: 'var(--color-text-hint)' }}>Loading API keys…</p>}

      <button
        type="button"
        className="btn-primary"
        style={{ marginBottom: '1rem' }}
        onClick={() => {
          setShowModal(true);
          setRevealedKey('');
          setName('');
        }}
      >
        Create key
      </button>

      <div style={{ overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.9rem' }}>
          <thead>
            <tr style={{ textAlign: 'left', borderBottom: '1px solid var(--color-border-light)' }}>
              <th style={{ padding: '0.4rem' }}>Name</th>
              <th>Prefix</th>
              <th>Created</th>
              <th>Last used</th>
              <th />
            </tr>
          </thead>
          <tbody>
            {keys.filter((k) => !k.revoked_at).map((k) => (
              <tr key={k.id} style={{ borderBottom: '1px solid var(--color-border-lighter)' }}>
                <td style={{ padding: '0.45rem' }}>{k.name || k.label}</td>
                <td><code>{k.key_prefix}</code></td>
                <td style={{ color: 'var(--color-text-hint)' }}>
                  {k.created_at ? new Date(k.created_at).toLocaleDateString() : '—'}
                </td>
                <td style={{ color: 'var(--color-text-hint)' }}>
                  {k.last_used_at ? new Date(k.last_used_at).toLocaleString() : '—'}
                </td>
                <td>
                  <button
                    type="button"
                    className="btn-secondary"
                    style={{ padding: '0.25rem 0.5rem', fontSize: '0.8rem' }}
                    onClick={() => revokeKey(k.id)}
                  >
                    Revoke
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div
          style={{
            position: 'fixed',
            inset: 0,
            background: 'rgba(0,0,0,0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000,
          }}
          onClick={() => setShowModal(false)}
        >
          <div
            className="campaign-card"
            style={{ width: 'min(480px, 92vw)', padding: '1.5rem' }}
            onClick={(e) => e.stopPropagation()}
          >
            <h2 style={{ marginTop: 0, fontSize: '1.2rem' }}>Create API key</h2>

            {revealedKey ? (
              <>
                <div
                  style={{
                    background: 'var(--color-warning-bg)',
                    border: '1px solid var(--color-warning-border)',
                    padding: '0.85rem',
                    borderRadius: 8,
                    marginBottom: '1rem',
                  }}
                >
                  <strong>Store this key — it will not be shown again.</strong>
                  <pre style={{ margin: '0.5rem 0 0', wordBreak: 'break-all', fontSize: '0.8rem' }}>
                    {revealedKey}
                  </pre>
                </div>
                <div style={{ display: 'flex', gap: '0.5rem', justifyContent: 'flex-end' }}>
                  <button type="button" className="btn-secondary" onClick={copyKey}>Copy key</button>
                  <button type="button" className="btn-primary" onClick={() => setShowModal(false)}>Done</button>
                </div>
              </>
            ) : (
              <form onSubmit={handleCreate}>
                <label style={{ display: 'block', fontWeight: 600, marginBottom: '0.5rem' }}>
                  Key name
                </label>
                <input
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="My bot integration"
                  required
                  style={{ width: '100%', marginBottom: '1rem' }}
                />
                <div style={{ display: 'flex', gap: '0.5rem', justifyContent: 'flex-end' }}>
                  <button type="button" className="btn-secondary" onClick={() => setShowModal(false)}>
                    Cancel
                  </button>
                  <button type="submit" className="btn-primary" disabled={creating}>
                    {creating ? 'Creating…' : 'Generate key'}
                  </button>
                </div>
              </form>
            )}
          </div>
        </div>
      )}
    </section>
  );
}

/**
 * AttestationsPanel
 *
 * Lists the contributor's KYC attestations and surfaces "Get Verified" CTAs
 * for missing tiers.  No personal data is displayed — only attestation type,
 * issuer label, dates, and revocation status.
 */

import { useTranslation } from 'react-i18next';

const ALL_TYPES = [
  {
    type: 'kyc_basic',
    label: 'KYC Basic',
    description: 'Government ID check',
  },
  {
    type: 'kyc_standard',
    label: 'KYC Standard',
    description: 'Government ID + address verification',
  },
  {
    type: 'kyc_enhanced',
    label: 'KYC Enhanced',
    description: 'Government ID + address + liveness check',
  },
];

function formatDate(isoString) {
  if (!isoString) return '—';
  return new Date(isoString).toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

function StatusBadge({ attestation }) {
  if (!attestation) {
    return (
      <span
        style={{
          background: 'var(--color-surface-alt, #f7fafc)',
          color: 'var(--color-text-hint, #a0aec0)',
          border: '1px solid var(--color-border, #e2e8f0)',
          borderRadius: '9999px',
          padding: '0.15rem 0.6rem',
          fontSize: '0.75rem',
          fontWeight: 600,
        }}
      >
        Not verified
      </span>
    );
  }
  if (attestation.revoked) {
    return (
      <span
        style={{
          background: '#fff5f5',
          color: '#e53e3e',
          border: '1px solid #fed7d7',
          borderRadius: '9999px',
          padding: '0.15rem 0.6rem',
          fontSize: '0.75rem',
          fontWeight: 600,
        }}
      >
        Revoked
      </span>
    );
  }
  if (attestation.expiresAt && new Date(attestation.expiresAt) < new Date()) {
    return (
      <span
        style={{
          background: '#fffbeb',
          color: '#d97706',
          border: '1px solid #fde68a',
          borderRadius: '9999px',
          padding: '0.15rem 0.6rem',
          fontSize: '0.75rem',
          fontWeight: 600,
        }}
      >
        Expired
      </span>
    );
  }
  return (
    <span
      style={{
        background: '#f0fff4',
        color: '#276749',
        border: '1px solid #9ae6b4',
        borderRadius: '9999px',
        padding: '0.15rem 0.6rem',
        fontSize: '0.75rem',
        fontWeight: 600,
      }}
    >
      Verified
    </span>
  );
}

export default function AttestationsPanel({ attestations = [], onStartKyc }) {
  const { t } = useTranslation();

  // Build a lookup of type → active (non-revoked, non-expired) attestation
  const byType = {};
  for (const att of attestations) {
    const existing = byType[att.type];
    const isActive = !att.revoked && (!att.expiresAt || new Date(att.expiresAt) > new Date());
    // Prefer the most-recent active one; fall back to any
    if (!existing || (isActive && !byType[att.type]._isActive)) {
      byType[att.type] = { ...att, _isActive: isActive };
    }
  }

  return (
    <div>
      <h3 style={{ margin: '0 0 0.75rem', fontSize: '1rem', fontWeight: 600 }}>
        Identity Attestations
      </h3>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
        {ALL_TYPES.map(({ type, label, description }) => {
          const att = byType[type] || null;
          const isActive = att?._isActive ?? false;

          return (
            <div
              key={type}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '0.75rem',
                padding: '0.75rem 1rem',
                borderRadius: '0.5rem',
                background: 'var(--color-surface, #fff)',
                border: '1px solid var(--color-border, #e2e8f0)',
              }}
            >
              {/* Icon */}
              <span style={{ fontSize: '1.4rem', flexShrink: 0 }}>
                {isActive ? '✅' : '🔲'}
              </span>

              {/* Info */}
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontWeight: 600, fontSize: '0.9rem' }}>{label}</div>
                <div
                  style={{
                    fontSize: '0.78rem',
                    color: 'var(--color-text-secondary, #718096)',
                  }}
                >
                  {description}
                </div>
                {att && (
                  <div
                    style={{
                      fontSize: '0.75rem',
                      color: 'var(--color-text-hint, #a0aec0)',
                      marginTop: '0.2rem',
                    }}
                  >
                    Issued {formatDate(att.issuedAt)}
                    {att.expiresAt ? ` · Expires ${formatDate(att.expiresAt)}` : ''}
                    {att.issuer ? ` · Issuer: ${att.issuer}` : ''}
                  </div>
                )}
              </div>

              {/* Status + CTA */}
              <div
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'flex-end',
                  gap: '0.4rem',
                  flexShrink: 0,
                }}
              >
                <StatusBadge attestation={att} />
                {!isActive && onStartKyc && (
                  <button
                    type="button"
                    className="btn-primary"
                    style={{ fontSize: '0.75rem', padding: '0.2rem 0.65rem' }}
                    onClick={() => onStartKyc(type)}
                  >
                    Get Verified
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import React, { memo } from 'react';
import { ResponsiveContainer, LineChart, Line, XAxis, YAxis, Tooltip, CartesianGrid } from 'recharts';

function shortenKey(key) {
  if (!key) return 'Unknown';
  return `${key.slice(0, 8)}…${key.slice(-4)}`;
}

const BackerInsightsCard = memo(function BackerInsightsCard({ data, assetType = 'XLM' }) {
  if (!data) {
    return null;
  }

  const { total_backers = 0, repeat_rate = 0, new_backers_by_day = [], top_backers = [] } = data;

  return (
    <div className="campaign-card" style={{ minHeight: 'auto', marginTop: '0.75rem' }}>
      <strong style={{ display: 'block', marginBottom: '0.6rem' }}>Backer insights</strong>
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))',
          gap: '0.75rem',
          marginBottom: '0.75rem',
        }}
      >
        <div className="campaign-card" style={{ minHeight: 'auto', padding: '0.6rem 0.75rem' }}>
          <strong style={{ fontSize: '1rem' }}>{total_backers}</strong>
          <div style={{ fontSize: '0.78rem', color: 'var(--color-text-hint)' }}>Total backers</div>
        </div>
        <div className="campaign-card" style={{ minHeight: 'auto', padding: '0.6rem 0.75rem' }}>
          <strong style={{ fontSize: '1rem' }}>{repeat_rate.toFixed(0)}%</strong>
          <div style={{ fontSize: '0.78rem', color: 'var(--color-text-hint)' }}>Repeat rate</div>
        </div>
      </div>

      <div style={{ marginBottom: '0.75rem' }}>
        <strong style={{ display: 'block', marginBottom: '0.4rem', fontSize: '0.9rem' }}>
          Backer growth
        </strong>
        {new_backers_by_day.length > 0 ? (
          <ResponsiveContainer width="100%" height={180}>
            <LineChart
              data={new_backers_by_day.map((r) => ({
                ...r,
                new_backers: Number(r.new_backers) || 0,
              }))}
              margin={{ top: 4, right: 8, bottom: 4, left: 0 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke="var(--color-border)" />
              <XAxis dataKey="day" tick={{ fontSize: 11 }} tickFormatter={(d) => d?.slice(5)} />
              <YAxis tick={{ fontSize: 11 }} width={48} />
              <Tooltip formatter={(value) => [Number(value) || 0, 'New backers']} />
              <Line
                type="monotone"
                dataKey="new_backers"
                stroke="var(--color-accent)"
                dot={false}
                strokeWidth={2}
                isAnimationActive={false}
              />
            </LineChart>
          </ResponsiveContainer>
        ) : (
          <p style={{ color: 'var(--color-text-hint)', fontSize: '0.9rem' }}>No backer growth data yet.</p>
        )}
      </div>

      <div>
        <strong style={{ display: 'block', marginBottom: '0.4rem', fontSize: '0.9rem' }}>
          Top backers
        </strong>
        {top_backers.length > 0 ? (
          <div style={{ display: 'grid', gap: '0.5rem' }}>
            {top_backers.map((row) => (
              <div key={row.sender_public_key} className="campaign-card" style={{ minHeight: 'auto', padding: '0.6rem 0.75rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', gap: '0.5rem', flexWrap: 'wrap' }}>
                  <span style={{ fontSize: '0.85rem', wordBreak: 'break-all' }}>
                    {shortenKey(row.sender_public_key)}
                  </span>
                  <span style={{ color: 'var(--color-text-hint)', fontSize: '0.8rem' }}>
                    {row.contribution_count} contributions · {Number(row.total_amount).toLocaleString()} {assetType}
                  </span>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p style={{ color: 'var(--color-text-hint)', fontSize: '0.9rem' }}>No backer activity yet.</p>
        )}
      </div>
    </div>
  );
});

export default BackerInsightsCard;

import React from 'react';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import VerificationBadge from './VerificationBadge';
import CampaignStatusBadge from './CampaignStatusBadge';

function progressColor(pct, status) {
  if (status === 'funded' || pct >= 100) return 'var(--color-teal)';
  if (status === 'closed' || status === 'withdrawn' || status === 'refunded' || status === 'failed')
    return 'var(--color-text-hint)';
  if (pct >= 75) return 'var(--color-accent-light)';
  return 'var(--color-accent)';
}

function daysLeft(deadline) {
  if (!deadline) return null;
  const diff = Math.ceil((new Date(deadline) - Date.now()) / (1000 * 60 * 60 * 24));
  if (diff < 0) return { kind: 'ended' };
  if (diff === 0) return { kind: 'lastDay' };
  return { kind: 'count', value: diff };
}

const CATEGORY_STYLES = {
  education: { bg: '#eff6ff', color: '#1d4ed8', border: '#bfdbfe' },
  community: { bg: '#f0fdf4', color: '#15803d', border: '#bbf7d0' },
  technology: { bg: '#f5f3ff', color: '#6d28d9', border: '#ddd6fe' },
  arts: { bg: '#fdf2f8', color: '#be185d', border: '#fbcfe8' },
  environment: { bg: '#ecfdf5', color: '#047857', border: '#a7f3d0' },
  health: { bg: '#fef2f2', color: '#dc2626', border: '#fecaca' },
  business: { bg: '#fffbeb', color: '#b45309', border: '#fde68a' },
  open_source: { bg: '#f0fdfa', color: '#0d9488', border: '#99f6e4' },
  startup: { bg: '#fef3c7', color: '#d97706', border: '#fde68a' },
  emergency: { bg: '#fef2f2', color: '#dc2626', border: '#fecaca' },
  other: { bg: '#f9fafb', color: '#4b5563', border: '#e5e7eb' },
};

const CATEGORY_LABELS = {
  technology: 'Technology',
  community: 'Community',
  arts: 'Arts & Culture',
  education: 'Education',
  environment: 'Environment',
  health: 'Health',
  business: 'Business',
  open_source: 'Open Source',
  startup: 'Startup',
  emergency: 'Emergency',
  other: 'Other',
};

function CampaignCard({ campaign, featured }) {
  const { t } = useTranslation();
  const pct = Math.min(100, (campaign.raised_amount / campaign.target_amount) * 100).toFixed(1);
  const fillColor = progressColor(parseFloat(pct), campaign.status);
  const deadline = daysLeft(campaign.deadline);
  const category = campaign.category || 'other';
  const catStyle = CATEGORY_STYLES[category] || CATEGORY_STYLES.other;

  return (
    <Link
      to={`/campaigns/${campaign.id}`}
      style={{ display: 'block' }}
      className="campaign-card-link"
    >
      <div className="campaign-card" style={styles.card}>
        {campaign.cover_image_url ? (
          <div style={styles.imageWrapper}>
            <img alt={campaign.title} src={campaign.cover_image_url} style={styles.image} />
            {campaign.category && (
              <span
                style={{
                  ...styles.categoryBadge,
                  background: catStyle.bg,
                  color: catStyle.color,
                  borderColor: catStyle.border,
                }}
              >
                {CATEGORY_LABELS[campaign.category] || campaign.category}
              </span>
            )}
          </div>
        ) : (
          <div
            style={{
              ...styles.imageWrapper,
              ...styles.placeholder,
            }}
            aria-hidden="true"
          >
            <span style={styles.placeholderText}>{t('campaignCard.noImage')}</span>
            {campaign.category && (
              <span
                style={{
                  ...styles.categoryBadge,
                  ...styles.categoryBadgeOnImage,
                  background: catStyle.bg,
                  color: catStyle.color,
                  borderColor: catStyle.border,
                }}
              >
                {CATEGORY_LABELS[campaign.category] || campaign.category}
              </span>
            )}
          </div>
        )}

        <div style={styles.content}>
          <div style={styles.header}>
            <div style={styles.headerLeft}>
              {campaign.asset_type && (
                <span style={styles.assetBadge}>{campaign.asset_type}</span>
              )}
              <CampaignStatusBadge status={campaign.status} />
            </div>
            <VerificationBadge status={campaign.creator_kyc_status || campaign.creator_verification_status} tier={campaign.creator_verification_tier} compact showTier />
          </div>

          <h3 style={styles.title}>{campaign.title}</h3>

          {campaign.creator_name && (
            <p style={styles.creator}>{t('campaignCard.by', { name: campaign.creator_name })}</p>
          )}

          <div style={styles.progressSection}>
            <div style={styles.amountRow}>
              <span style={styles.raisedAmount}>
                <strong>${Number(campaign.raised_amount).toLocaleString()}</strong> raised
              </span>
              <span style={styles.targetAmount}>
                of ${Number(campaign.target_amount).toLocaleString()}
              </span>
            </div>
            <div className="progress-bar" style={styles.progressBar}>
              <div
                className="progress-bar-fill"
                style={{ ...styles.progressFill, width: `${pct}%`, background: fillColor }}
              />
            </div>
          </div>

          <div style={styles.footer}>
            <span style={styles.footerStat}>
              {campaign.contributor_count || 0} donors
            </span>
            {deadline && (
              <span style={styles.footerStat}>
                {deadline.kind === 'ended'
                  ? t('campaignCard.ended')
                  : deadline.kind === 'lastDay'
                    ? t('campaignCard.lastDay')
                    : t('campaignCard.daysLeft', { count: deadline.value })}
              </span>
            )}
          </div>
        </div>
      </div>
    </Link>
  );
}

