};

export default function CampaignStatusBadge({ status }) {
  const { t } = useTranslation();
  if (!status || status === 'active') return null;
  const style = LABELS[status];
  if (!style) return null;

  return (
    <span
      style={{
        background: style.bg,
        color: style.color,
        fontSize: '0.72rem',
        fontWeight: 700,
        padding: '2px 8px',
        borderRadius: '99px',
        whiteSpace: 'nowrap',
      }}
    >
      {t(style.key)}
    </span>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { api } from '../services/api';

export function BadgeChip({ badge }) {
  const title = badge.earned_at
    ? `${badge.description} Earned ${new Date(badge.earned_at).toLocaleDateString()}.`
