export default function ContributorDashboard() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [exporting, setExporting] = useState(false);
  const toast = useToast();

  function load() {
    setLoading(true);
    setError('');
    api
      .getContributorDashboard()
      .then(setData)
      .catch((err) => setError(err.message || 'Could not load contributions'))
      .finally(() => setLoading(false));
  }

  async function exportCsv() {
    setExporting(true);
    try {
      const { blob, filename } = await api.exportContributionsCsv();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    } catch (err) {
      toast?.(err.message || 'Could not export contributions', 'error');
    } finally {
      setExporting(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  if (loading) {
    return <p style={{ color: 'var(--color-text-hint)' }}>Loading your contributions…</p>;
  }

  if (error) {
    return <p className="alert alert--error">{error}</p>;
  }

  if (!data?.campaigns?.length) {
    return (
      <div>
        <FavoritesSection />
        <p className="alert alert--info">
          You have not backed any campaigns yet.{' '}
          <Link to="/discover" style={{ color: 'var(--color-accent)', fontWeight: 600 }}>
            Browse campaigns
          </Link>
          .
        </p>
      </div>
    );
  }

  const { stats, campaigns } = data;

  return (
    <div>
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: '0.5rem',
          marginBottom: '0.75rem',
        }}
      >
        <div style={{ fontSize: '0.85rem', color: 'var(--color-text-hint)' }}>Your portfolio</div>
        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', alignItems: 'center' }}>
          <Link to="/tax-receipts" style={{ fontSize: '0.8rem', color: 'var(--color-accent)', fontWeight: 700 }}>
            Tax receipts
          </Link>
          <button type="button" onClick={exportCsv} disabled={exporting} style={{ fontSize: '0.8rem' }}>
            {exporting ? 'Exporting…' : 'Export CSV'}
          </button>
        </div>
      </div>

      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))',
          gap: '0.65rem',
          marginBottom: '1.25rem',
        }}
      >
        {[
          ['Total contributed', stats.total_contributed.toLocaleString()],
          ['Campaigns backed', stats.campaigns_backed],
          ['Active campaigns', stats.active_campaigns_backed],
          ['Campaigns completed', stats.campaigns_completed],
          ['Avg. contribution', stats.avg_contribution.toLocaleString(undefined, { maximumFractionDigits: 2 })],
          ['Total refunded', stats.total_refunded.toLocaleString()],
        ].map(([label, value]) => (
          <div key={label} className="campaign-card" style={{ minHeight: 'auto', padding: '0.75rem' }}>
            <strong style={{ fontSize: '1.1rem' }}>{value}</strong>
            <div style={{ fontSize: '0.78rem', color: 'var(--color-text-hint)', marginTop: '0.15rem' }}>
              {label}
            </div>
          </div>
        ))}
      </div>

      <BadgesRow badges={stats.badges} />
      <FavoritesSection />

      <div style={{ display: 'grid', gap: '0.85rem' }}>
        {campaigns.map((campaign) => (
          <BackedCampaignCard key={campaign.campaign_id} campaign={campaign} onRefundClaimed={load} />
        ))}
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { api } from '../services/api';

const POLL_INTERVAL_MS = 4000;
// Consecutive-failure backoff. A 5th failure gives up instead of polling forever.
const POLL_BACKOFF_MS = [5000, 10000, 20000, 40000];
const MAX_POLL_FAILURES = POLL_BACKOFF_MS.length + 1;

export default function DepositModal({ onClose, onSuccess }) {
  const [amount, setAmount] = useState('');
  const [anchorInfo, setAnchorInfo] = useState({ anchors: [] });
  const [selectedAnchorId, setSelectedAnchorId] = useState('');
  const [session, setSession] = useState(null);
  const [loading, setLoading] = useState(false);
  const [loadingLabel, setLoadingLabel] = useState('Submitting…');
  const [error, setError] = useState('');
  const [pollRetryNotice, setPollRetryNotice] = useState('');
  const [kycRequired, setKycRequired] = useState(false);
  const [phase, setPhase] = useState('form');
  const [balance, setBalance] = useState(null);
  const popupRef = useRef(null);
  const modalRef = useRef(null);

  const selectedAnchor = anchorInfo.anchors.find((a) => a.id === selectedAnchorId) || null;

  useEffect(() => {
    api
      .getMyBalance()
      .then((d) => setBalance(d.balance))
      .catch(() => {});
    api
      .getSep24Assets()
      .then((info) => {
        setAnchorInfo(info || { anchors: [] });
        const first = (info?.anchors || []).find((a) => a.available);
        if (first) setSelectedAnchorId(first.id);
      })
      .catch(() => {});
  }, []);

  useEffect(() => {
    const onKey = (e) => {
      if (e.key === 'Escape') handleClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  useEffect(() => {
    if (phase !== 'anchor' || !session?.id) return;
    let stopped = false;
    let timerId;
    let failures = 0;

    const schedule = (delayMs) => {
      timerId = window.setTimeout(poll, delayMs);
    };

    const poll = async () => {
      try {
        const next = await api.getAnchorDepositStatus(session.id);
        if (stopped) return;
        failures = 0;
        setPollRetryNotice('');
        setSession(next);
        if (next.status === 'completed') {
          setPhase('success');
          if (popupRef.current && !popupRef.current.closed) popupRef.current.close();
          onSuccess();
          return;
        }
        if (next.status === 'failed') {
          let customError = next.last_error || 'The deposit could not be completed.';
          if (next.last_anchor_status === 'too_large')
            customError = 'Deposit amount exceeds the maximum limit allowed by the partner.';
          if (next.last_anchor_status === 'too_small')
            customError = 'Deposit amount is below the minimum limit allowed by the partner.';
          if (next.last_anchor_status === 'no_market')
            customError = 'The deposit partner does not support this region or currency.';

          setError(customError);
          setPhase('form');
          if (popupRef.current && !popupRef.current.closed) popupRef.current.close();
          return;
        }
        setKycRequired(
          next.last_anchor_status === 'pending_user_info_update' ||
            next.last_anchor_status === 'pending_customer_info_update'
        );
        schedule(POLL_INTERVAL_MS);
      } catch (err) {
        if (stopped) return;
        failures += 1;
        if (failures >= MAX_POLL_FAILURES) {
          setPollRetryNotice('');
          setError(
            `We stopped checking your deposit status after ${MAX_POLL_FAILURES} failed attempts (${err.message || 'network error'}). Your deposit is unaffected — reopen the deposit window or check your balance again shortly.`
          );
          return;
        }
        const delayMs = POLL_BACKOFF_MS[failures - 1];
        setPollRetryNotice(
          `Could not refresh the deposit status (${err.message || 'network error'}). Retrying in ${delayMs / 1000}s — attempt ${failures + 1} of ${MAX_POLL_FAILURES}.`
        );
        schedule(delayMs);
      }
    };

    poll();
    return () => {
      stopped = true;
      window.clearTimeout(timerId);
    };
  }, [session?.id, onSuccess, phase]);

  useEffect(() => {
    const modal = modalRef.current;
    if (!modal) return;
    const focusable = modal.querySelectorAll(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    first?.focus();
    function trapTab(e) {
      if (e.key !== 'Tab') return;
      if (e.shiftKey) {
        if (document.activeElement === first) {
          e.preventDefault();
          last?.focus();
        }
      } else {
        if (document.activeElement === last) {
          e.preventDefault();
          first?.focus();
        }
      }
    }
    modal.addEventListener('keydown', trapTab);
    return () => modal.removeEventListener('keydown', trapTab);
  }, [phase]);

  async function handleSubmit(e) {
    e.preventDefault();
    if (!amount || Number(amount) <= 0) {
      setError('Enter an amount greater than zero.');
      return;
    }
    if (!selectedAnchorId) {
      setError('No deposit anchor is available.');
      return;
    }

    setLoading(true);
    setLoadingLabel('Preparing deposit…');
    setError('');
    setPollRetryNotice('');
    try {
      const popup = window.open('', 'crowdpay-wallet-deposit', 'popup,width=520,height=780');
      popupRef.current = popup;

      const result = await api.startWalletDeposit({
        amount: String(amount),
        anchor_id: selectedAnchorId,
      });

      if (popup && !popup.closed) {
        popup.location.href = result.interactive_url;
      } else {
        window.open(result.interactive_url, '_blank', 'noopener,noreferrer');
      }

      setSession(result);
      setPhase('anchor');
    } catch (err) {
      if (popupRef.current && !popupRef.current.closed) popupRef.current.close();
      setError(err.message || 'Could not start the deposit flow.');
    } finally {
      setLoading(false);
      setLoadingLabel('Submitting…');
    }
  }

  function handleClose() {
    if (popupRef.current && !popupRef.current.closed) popupRef.current.close();
    onClose();
  }

  return (
    <div className="modal-overlay" style={styles.overlay} onClick={handleClose} role="presentation">
      <div
        className="modal-shell"
        ref={modalRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="deposit-title"
        onClick={(e) => e.stopPropagation()}
      >
        {phase === 'form' ? (
          <>
            <h2 id="deposit-title" style={styles.title}>
              Add Funds
            </h2>
            <p style={styles.subtitle}>
              Deposit fiat currency into your CrowdPay wallet via a supported anchor.
            </p>

            {balance && (
              <div
                className="alert alert--info"
                style={{ marginBottom: '1rem', fontSize: '0.85rem' }}
                role="status"
              >
                <strong>Current wallet balance:</strong>{' '}
                {Object.entries(balance)
                  .filter(([, v]) => Number(v) > 0)
                  .map(([code, val]) => `${Number(val).toLocaleString()} ${code}`)
                  .join(' · ') || 'Empty'}
              </div>
            )}

            <form noValidate onSubmit={handleSubmit}>
              <fieldset style={{ border: 'none', margin: '0 0 1rem', padding: 0 }}>
                <legend className="label-strong" style={{ marginBottom: '0.45rem' }}>
                  Deposit partner
                </legend>
                <div className="asset-picker" role="radiogroup" aria-label="Anchor selection">
                  {anchorInfo.anchors
                    .filter((a) => a.available)
                    .map((a) => (
                      <label
                        key={a.id}
                        className={`asset-picker__option${selectedAnchorId === a.id ? ' asset-picker__option--selected' : ''}`}
                      >
                        <input
                          type="radio"
                          name="anchor_id"
                          value={a.id}
                          checked={selectedAnchorId === a.id}
                          onChange={() => setSelectedAnchorId(a.id)}
                        />
                        <div className="asset-picker__code">{a.name}</div>
                        <div className="asset-picker__hint">
                          {a.asset.code} · {a.rails?.join(', ') || 'deposit'} · {a.environment}
                        </div>
                      </label>
                    ))}
                </div>
              </fieldset>

              {selectedAnchor && (
                <div className="alert alert--info" style={{ marginBottom: '1rem' }} role="status">
                  <strong>{selectedAnchor.name}.</strong> CrowdPay will open the anchor’s hosted
                  flow. Once the deposit completes, the funds will appear in your custodial wallet.
                </div>
              )}

              <div className="form-stack" style={{ marginBottom: '1rem' }}>
                <label className="label-strong" htmlFor="deposit-amount">
                  Amount ({selectedAnchor?.asset?.code || 'USDC'})
                </label>
                <input
                  id="deposit-amount"
                  type="number"
                  inputMode="decimal"
                  min="0.0000001"
                  step="any"
                  placeholder="0.00"
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                />
              </div>

              {error && (
                <p className="alert alert--error" style={{ marginTop: '0.85rem' }} role="alert">
                  {error}
                </p>
              )}

              <div style={styles.actions}>
                <button type="button" className="btn-secondary" onClick={handleClose}>
                  Cancel
                </button>
                <button type="submit" className="btn-primary" disabled={loading}>
                  {loading ? loadingLabel : 'Continue'}
                </button>
              </div>
            </form>
          </>
        ) : phase === 'anchor' ? (
          <div>
            <h2 id="deposit-title" style={styles.title}>
              Complete your deposit
            </h2>
            <p className="alert alert--info" style={{ marginBottom: '1rem' }} role="status">
              Finish the hosted deposit flow in the popup window. CrowdPay is polling the anchor and
              will update your wallet balance automatically when the funds arrive.
            </p>
            {kycRequired && (
              <p className="alert alert--warning" style={{ marginBottom: '1rem' }} role="status">
                <strong>Action Required:</strong> The partner needs additional KYC information.
                Please complete the form in the deposit window.
              </p>
            )}
            {pollRetryNotice && (
              <p className="alert alert--warning" style={{ marginBottom: '1rem' }} role="status">
                {pollRetryNotice}
              </p>
            )}
            {error && (
              <p className="alert alert--error" style={{ marginBottom: '1rem' }} role="alert">
                {error}
              </p>
            )}
            {session?.anchor_transaction_id && (
              <p style={{ fontSize: '0.875rem', marginBottom: '0.75rem' }}>
                <strong>Anchor transaction:</strong> {session.anchor_transaction_id}
              </p>
            )}
            {session?.interactive_url && (
              <button
                type="button"
                className="btn-secondary"
                style={{ width: '100%', marginBottom: '0.75rem' }}
                onClick={() =>
                  window.open(session.interactive_url, '_blank', 'noopener,noreferrer')
                }
              >
                Reopen deposit window
              </button>
            )}
            <button
              type="button"
              className="btn-primary"
              style={{ width: '100%' }}
              onClick={handleClose}
            >
              Close
            </button>
          </div>
        ) : (
          <div>
            <h2 id="deposit-title" style={styles.title}>
              Deposit submitted
            </h2>
            <p className="alert alert--success" style={{ marginBottom: '1rem' }} role="status">
              Your deposit has been completed. The funds should now be available in your wallet.
            </p>
            {session?.anchor_transaction_id && (
              <p style={{ fontSize: '0.875rem', marginBottom: '0.75rem' }}>
                <strong>Anchor reference:</strong> {session.anchor_transaction_id}
              </p>
            )}
            {error && (
              <p className="alert alert--error" style={{ marginBottom: '1rem' }} role="alert">
                {error}
              </p>
            )}
            <button
              type="button"
              className="btn-primary"
              style={{ width: '100%', marginTop: '0.5rem' }}
              onClick={handleClose}
            >
              Done
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

const styles = {
  overlay: {
    position: 'fixed',
    inset: 0,
    background: 'rgba(15, 23, 42, 0.55)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    zIndex: 100,
    padding: '0.75rem',
  },
  title: {
    fontSize: '1.2rem',
    fontWeight: 800,
    marginBottom: '0.5rem',
    color: 'var(--color-text-primary)',
  },
  subtitle: {
    color: 'var(--color-text-secondary)',
    fontSize: '0.875rem',
    lineHeight: 1.55,
    marginBottom: '1.1rem',
  },
  actions: {
    display: 'flex',
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: '0.65rem',
    justifyContent: 'stretch',
    marginTop: '1.1rem',
  },
};

import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { api } from '../services/api';
import { useAuth } from '../context/AuthContext';

const REASONS = [
  { value: 'non_delivery', key: 'dispute.nonDelivery' },
  { value: 'misrepresentation', key: 'dispute.misrepresentation' },
  { value: 'abandoned', key: 'dispute.abandoned' },
  { value: 'other', key: 'dispute.other' },
];

export default function DisputeModal({ campaign, onClose, onSubmitted }) {
  const { t } = useTranslation();
  const { token } = useAuth();
  const [form, setForm] = useState({ reason: 'non_delivery', description: '', evidence_url: '' });
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  async function handleSubmit(e) {
    e.preventDefault();
    setError('');
    setBusy(true);
    try {
      await api.raiseDispute(
        campaign.id,
        {
          reason: form.reason,
          description: form.description.trim(),
          evidence_url: form.evidence_url.trim() || undefined,
        },
        token
      );
      onSubmitted?.();
      onClose();
    } catch (err) {
      if (err.code === 'NOT_A_CONTRIBUTOR') {
        setError(t('dispute.notAContributor'));
      } else {
        setError(err.message || t('dispute.error'));
      }
    } finally {
      setBusy(false);
    }
  }

  return (
    <div style={overlay} role="dialog" aria-modal="true" aria-labelledby="dispute-title">
      <div style={modal}>
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            marginBottom: '1rem',
          }}
        >
          <h2 id="dispute-title" style={{ fontSize: '1.2rem', fontWeight: 700, margin: 0 }}>
            {t('dispute.title')}
          </h2>
          <button type="button" onClick={onClose} aria-label={t('dispute.close')} style={closeBtn}>
            ✖
          </button>
        </div>
        <p
          style={{
            color: 'var(--color-text-secondary)',
            fontSize: '0.9rem',
            marginBottom: '1.25rem',
          }}
        >
          {t('dispute.description', { title: campaign.title })}
        </p>
        <form onSubmit={handleSubmit}>
          <label style={labelStyle} htmlFor="dispute-reason">
            {t('dispute.reason')}
          </label>
          <select
            id="dispute-reason"
            value={form.reason}
            onChange={(e) => setForm((s) => ({ ...s, reason: e.target.value }))}
            style={{ marginBottom: '1rem', width: '100%' }}
            required
          >
            {REASONS.map((r) => (
              <option key={r.value} value={r.value}>
                {t(r.key)}
              </option>
            ))}
          </select>

          <label style={labelStyle} htmlFor="dispute-description">
            {t('dispute.details')}
          </label>
          <textarea
            id="dispute-description"
            value={form.description}
            onChange={(e) => setForm((s) => ({ ...s, description: e.target.value }))}
            rows={4}
            placeholder={t('dispute.detailsPlaceholder')}
            required
            style={{ marginBottom: '1rem', width: '100%' }}
          />

          <label style={labelStyle} htmlFor="dispute-evidence">
            {t('dispute.evidence')}
          </label>
          <input
            id="dispute-evidence"
            type="url"
            value={form.evidence_url}
            onChange={(e) => setForm((s) => ({ ...s, evidence_url: e.target.value }))}
            placeholder="https://..."
            style={{ marginBottom: '1.25rem', width: '100%' }}
          />

          {error && (
            <p className="alert alert--error" style={{ marginBottom: '1rem' }}>
              {error}
            </p>
          )}

          <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'flex-end' }}>
            <button type="button" className="btn-secondary" onClick={onClose} disabled={busy}>
              {t('common.cancel')}
            </button>
            <button type="submit" className="btn-primary" disabled={busy}>
              {busy ? t('dispute.submitting') : t('dispute.submit')}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

