// Milestone progress for embeds (#596). Inline styles only — this renders
// inside the standalone embed bundle, which does not load the app stylesheet.

export const MILESTONE_STATUS_META = {
  released: { label: 'Released', color: '#10b981' },
  approved: { label: 'Approved', color: '#3b82f6' },
  submitted: { label: 'Submitted', color: '#f59e0b' },
  pending: { label: 'Pending', color: '#9ca3af' },
};

export const WIDGET_SIZES = ['small', 'medium', 'large'];

export function normalizeWidgetSize(size) {
  return WIDGET_SIZES.includes(size) ? size : 'medium';
}

function statusMeta(status) {
  return MILESTONE_STATUS_META[status] || MILESTONE_STATUS_META.pending;
}

export default function MilestoneProgressBar({ milestones, summary, size = 'medium' }) {
  const resolvedSize = normalizeWidgetSize(size);
  if (resolvedSize === 'small' || !milestones?.length) return null;

  const totalPercentage = milestones.reduce(
    (total, milestone) => total + (Number(milestone.release_percentage) || 0),
    0
  );

  return (
    <div style={{ marginBottom: '0.85rem' }}>
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'baseline',
          gap: '0.5rem',
          marginBottom: '0.35rem',
          fontSize: '0.75rem',
          color: 'var(--color-text-hint, #6b7280)',
        }}
      >
        <span style={{ fontWeight: 700 }}>Milestones</span>
        <span>
          {summary?.released ?? 0} of {summary?.total ?? milestones.length} released
        </span>
      </div>

      <div
        style={{ display: 'flex', gap: '2px', height: '8px' }}
        role="img"
        aria-label={`${summary?.released ?? 0} of ${summary?.total ?? milestones.length} milestones released`}
      >
        {milestones.map((milestone) => {
          const share = totalPercentage
            ? (Number(milestone.release_percentage) || 0) / totalPercentage
            : 1 / milestones.length;
          return (
            <div
              key={milestone.id}
              title={`${milestone.title} — ${statusMeta(milestone.status).label}`}
              style={{
                flexGrow: Math.max(share, 0.05),
                flexBasis: 0,
                borderRadius: '99px',
                background: statusMeta(milestone.status).color,
                opacity: milestone.status === 'pending' ? 0.45 : 1,
              }}
            />
          );
        })}
      </div>

      {resolvedSize === 'large' && (
        <ul
          style={{
            listStyle: 'none',
            margin: '0.55rem 0 0',
            padding: 0,
            display: 'grid',
            gap: '0.3rem',
          }}
        >
          {milestones.map((milestone) => (
            <li
              key={milestone.id}
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                gap: '0.5rem',
                fontSize: '0.78rem',
              }}
            >
              <span style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis' }}>
                {milestone.title}
                <span style={{ color: 'var(--color-text-hint, #6b7280)' }}>
                  {' '}
                  · {Number(milestone.release_percentage)}%
                </span>
              </span>
              <span
                style={{
                  flexShrink: 0,
                  fontWeight: 600,
                  color: statusMeta(milestone.status).color,
                }}
              >
                {statusMeta(milestone.status).label}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function statusTone(status) {
  if (status === 'released')
    return { bg: 'var(--color-success-bg)', fg: 'var(--color-success-text)', label: 'Released' };
  if (status === 'approved')
    return { bg: 'var(--color-info-bg)', fg: 'var(--color-info-text)', label: 'Approved' };
  if (status === 'pending_review')
    return {
      bg: 'var(--color-warning-bg)',
      fg: 'var(--color-warning-text)',
      label: 'Awaiting review',
    };
  if (status === 'rejected')
    return { bg: 'var(--color-error-bg)', fg: 'var(--color-error-text)', label: 'Rejected' };
  return { bg: 'var(--color-surface)', fg: 'var(--color-text-secondary)', label: 'Pending' };
}

export default function MilestoneTracker({ milestones, assetType, contractMilestones }) {
  if (!milestones?.length) return null;

  function onChainStatusFor(milestone, index) {
    const fromContract = contractMilestones?.find(
      (item) => item.index === milestone.sort_order || item.index === index,
    );
    return fromContract?.on_chain_status || null;
  }

  function onChainStatusLabel(status) {
    if (!status) return null;
    if (status === 'released') return 'Released on-chain';
    if (status === 'submitted') return 'Submitted on-chain';
    if (status === 'rejected') return 'Rejected on-chain';
    return 'Pending on-chain';
  }

  return (
    <section style={{ marginTop: '1.5rem' }} aria-label="Milestone progress">
      <h2
        style={{
          fontSize: '1.15rem',
          fontWeight: 800,
          marginBottom: '0.75rem',
          color: 'var(--color-text-primary)',
        }}
      >
        Milestone releases
      </h2>
      <div style={{ display: 'grid', gap: '0.75rem' }}>
        {milestones.map((milestone, index) => {
          const tone = statusTone(milestone.status);
          const chainStatus = onChainStatusFor(milestone, index);
          const chainLabel = onChainStatusLabel(chainStatus);
          return (
            <article key={milestone.id} className="campaign-card">
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: '0.75rem',
                  flexWrap: 'wrap',
                }}
              >
                <div>
                  <div
                    style={{
                      fontSize: '0.78rem',
                      color: 'var(--color-text-hint)',
                      marginBottom: '0.2rem',
                    }}
                  >
                    Milestone {index + 1}
                  </div>
                  <strong>{milestone.title}</strong>
                </div>
                <div style={{ display: 'flex', gap: '0.5rem', alignSelf: 'flex-start' }}>
                  {milestone.on_chain && (
                    <div
                      title="This milestone is managed by a Soroban smart contract"
                      style={{
                        background: 'var(--color-warning-bg)',
                        color: 'var(--color-warning-text)',
                        borderRadius: '999px',
                        fontSize: '0.72rem',
                        fontWeight: 700,
                        padding: '0.25rem 0.6rem',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '0.25rem',
                      }}
                    >
                      <span aria-hidden="true">⛓️</span> On-chain
                    </div>
                  )}
                  {chainLabel && (
                    <div
                      title="On-chain release status from Soroban contract"
                      style={{
                        background: chainStatus === 'released' ? 'var(--color-success-bg)' : 'var(--color-info-bg)',
                        color: chainStatus === 'released' ? 'var(--color-success-text)' : 'var(--color-info-text)',
                        borderRadius: '999px',
                        fontSize: '0.72rem',
                        fontWeight: 700,
                        padding: '0.25rem 0.6rem',
                      }}
                    >
                      {chainLabel}
                    </div>
                  )}
                  <div
                    style={{
                      background: tone.bg,
                      color: tone.fg,
                      borderRadius: '999px',
                      fontSize: '0.78rem',
                      fontWeight: 700,
                      padding: '0.25rem 0.6rem',
                    }}
                  >
                    {tone.label}
                  </div>
                </div>
              </div>
              <div
                style={{
                  marginTop: '0.45rem',
                  color: 'var(--color-text-primary)',
                  lineHeight: 1.55,
                  fontSize: '0.92rem',
                }}
              >
                {milestone.description || 'No description provided yet.'}
              </div>
              <div
                style={{
                  marginTop: '0.55rem',
                  fontSize: '0.85rem',
                  color: 'var(--color-text-secondary)',
                }}
              >
                Releases {Number(milestone.release_percentage).toLocaleString()}% of campaign funds
                in {assetType}.
              </div>
              {milestone.evidence_url && (
                <div style={{ marginTop: '0.45rem', fontSize: '0.84rem' }}>
                  Evidence:{' '}
                  <a
                    href={milestone.evidence_url}
                    target="_blank"
                    rel="noopener noreferrer"
                    style={{ color: 'var(--color-accent)', fontWeight: 600 }}
                  >
                    View proof
                  </a>
                </div>
              )}
              {milestone.evidence_description && (
                <div
                  style={{
                    marginTop: '0.45rem',
                    fontSize: '0.84rem',
                    color: 'var(--color-text-secondary)',
                  }}
                >
                  {milestone.evidence_description}
                </div>
              )}
              {milestone.review_note && milestone.status === 'rejected' && (
                <div
                  className="alert alert--error"
                  style={{ marginTop: '0.55rem', fontSize: '0.82rem' }}
                >
                  Rejection reason: {milestone.review_note}
                </div>
              )}
              {milestone.review_note && milestone.status !== 'rejected' && (
                <div
                  className="alert alert--info"
                  style={{ marginTop: '0.55rem', fontSize: '0.82rem' }}
                >
                  {milestone.review_note}
                </div>
              )}
            </article>
          );
        })}
      </div>
    </section>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { api } from '../services/api';

const buttonBase = {
  border: 0,
  borderRadius: '8px',
  color: '#fff',
  cursor: 'pointer',
  fontWeight: 700,
  padding: '0.55rem 0.85rem',
};

export default function MilestoneVotePanel({ milestones }) {
  const votableMilestones = useMemo(
    () => (milestones || []).filter((milestone) => milestone.status === 'pending_review'),
    [milestones]
  );
  const [votesByMilestone, setVotesByMilestone] = useState({});
  const [notesByMilestone, setNotesByMilestone] = useState({});
  const [busyByMilestone, setBusyByMilestone] = useState({});
  const [errorByMilestone, setErrorByMilestone] = useState({});

  useEffect(() => {
    let active = true;
    if (!votableMilestones.length) {
      setVotesByMilestone({});
      return () => {
        active = false;
      };
    }

    Promise.all(
      votableMilestones.map((milestone) =>
        api
          .getMilestoneVotes(milestone.id)
          .then((result) => [milestone.id, result])
          .catch((err) => [milestone.id, { error: err.message || 'Could not load votes' }])
      )
    ).then((results) => {
      if (!active) return;
      const nextVotes = {};
      const nextErrors = {};
      results.forEach(([milestoneId, result]) => {
        if (result.error) nextErrors[milestoneId] = result.error;
        else nextVotes[milestoneId] = result;
      });
      setVotesByMilestone(nextVotes);
      setErrorByMilestone(nextErrors);
    });

    return () => {
      active = false;
    };
  }, [votableMilestones]);

  if (!votableMilestones.length) return null;

  async function submitVote(milestoneId, vote) {
    setBusyByMilestone((current) => ({ ...current, [milestoneId]: true }));
    setErrorByMilestone((current) => ({ ...current, [milestoneId]: '' }));
    try {
      const result = await api.voteMilestone(milestoneId, {
        vote,
        note: notesByMilestone[milestoneId] || '',
      });
      setVotesByMilestone((current) => ({ ...current, [milestoneId]: result }));
    } catch (err) {
      setErrorByMilestone((current) => ({
        ...current,
        [milestoneId]: err.message || 'Could not submit vote',
      }));
    } finally {
      setBusyByMilestone((current) => ({ ...current, [milestoneId]: false }));
    }
  }

  return (
    <section style={{ marginTop: '1rem', marginBottom: '1.5rem' }} aria-label="Milestone voting">
      <h2
        style={{
          color: 'var(--color-text-primary)',
          fontSize: '1.05rem',
          fontWeight: 800,
          marginBottom: '0.75rem',
        }}
      >
        Contributor milestone votes
      </h2>
      <div style={{ display: 'grid', gap: '0.75rem' }}>
        {votableMilestones.map((milestone) => {
          const tally = votesByMilestone[milestone.id];
          const busy = !!busyByMilestone[milestone.id];
          const error = errorByMilestone[milestone.id];
          const currentVote = tally?.user_vote?.vote;

          return (
            <article key={milestone.id} className="campaign-card">
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: '0.75rem',
                  flexWrap: 'wrap',
                }}
              >
                <div>
                  <strong>{milestone.title}</strong>
                  <div style={{ color: 'var(--color-text-secondary)', fontSize: '0.86rem' }}>
                    {tally
                      ? `${tally.approve_count} approve / ${tally.reject_count} reject`
                      : 'Vote tally loading'}
                  </div>
                </div>
                {currentVote && (
                  <span
                    style={{
                      alignSelf: 'flex-start',
                      background:
                        currentVote === 'approve'
                          ? 'var(--color-success-bg)'
                          : 'var(--color-error-bg)',
                      borderRadius: '999px',
                      color:
                        currentVote === 'approve'
                          ? 'var(--color-success-text)'
                          : 'var(--color-error-text)',
                      fontSize: '0.78rem',
                      fontWeight: 700,
                      padding: '0.25rem 0.6rem',
                    }}
                  >
                    Your vote: {currentVote}
                  </span>
                )}
              </div>

              <textarea
                value={notesByMilestone[milestone.id] || ''}
                onChange={(event) =>
                  setNotesByMilestone((current) => ({
                    ...current,
                    [milestone.id]: event.target.value,
                  }))
                }
                placeholder="Add an optional note"
                rows={2}
                style={{
                  background: 'var(--color-surface)',
                  border: '1px solid var(--color-border)',
                  borderRadius: '8px',
                  color: 'var(--color-text-primary)',
                  marginTop: '0.75rem',
                  padding: '0.65rem',
                  resize: 'vertical',
                  width: '100%',
                }}
              />

              {error && (
                <div className="alert alert--error" style={{ marginTop: '0.65rem', fontSize: '0.82rem' }}>
                  {error}
                </div>
              )}

              <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.75rem', flexWrap: 'wrap' }}>
                <button
                  type="button"
                  disabled={busy}
                  onClick={() => submitVote(milestone.id, 'approve')}
                  style={{ ...buttonBase, background: 'var(--color-success, #15803d)' }}
                >
                  Approve
                </button>
                <button
                  type="button"
                  disabled={busy}
                  onClick={() => submitVote(milestone.id, 'reject')}
                  style={{ ...buttonBase, background: 'var(--color-error, #b91c1c)' }}
                >
                  Reject
                </button>
              </div>
            </article>
          );
        })}
      </div>
    </section>
  );
}

import { useTranslation } from 'react-i18next';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
