}

import { useNavigate } from 'react-router-dom';
import { api } from '../services/api';
import RelativeTime from './RelativeTime';

export default function NotificationDropdown({
  notifications,
  onMarkRead,
  onMarkAllRead,
  onClose,
}) {
  const navigate = useNavigate();

  async function handleClick(notif) {
    onClose();
    if (!notif.read_at) {
      await api.markNotificationRead(notif.id).catch(() => {});
      onMarkRead(notif.id);
    }
    if (notif.link) navigate(notif.link);
  }

  return (
    <div style={styles.dropdown}>
      <div style={styles.header}>
        <span style={styles.headerTitle}>Notifications</span>
        <button style={styles.markAll} onClick={onMarkAllRead}>
          Mark all as read
        </button>
      </div>
      {notifications.length === 0 ? (
        <div style={styles.empty}>No notifications yet.</div>
      ) : (
        notifications.map((n) => (
          <button
            key={n.id}
            style={{
              ...styles.item,
              background: n.read_at
                ? 'transparent'
                : 'var(--color-accent-muted, rgba(99,102,241,0.08))',
            }}
            onClick={() => handleClick(n)}
          >
            <div style={styles.itemTitle}>{n.title}</div>
            {n.body && <div style={styles.itemBody}>{n.body}</div>}
            <div style={styles.itemTime}>
              <RelativeTime date={n.created_at} />
            </div>
          </button>
        ))
      )}
    </div>
  );
}

