import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import { api } from '../services/api';
import { useToast } from '../context/ToastContext';

/**
 * PoolManager — UI for creating, joining, and managing contribution pools.
 *
 * Can be embedded in the Campaign page or displayed as a standalone section.
 */
export default function PoolManager({ campaignId, campaignTitle }) {
  const { user } = useAuth();
  const { toast } = useToast();

  const [pools, setPools] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [creating, setCreating] = useState(false);
  const [joinPoolId, setJoinPoolId] = useState(null);
  const [joinAmount, setJoinAmount] = useState('');
  const [joinName, setJoinName] = useState('');
  const [joining, setJoining] = useState(false);

  // Create form
  const [poolTitle, setPoolTitle] = useState('');
  const [poolDesc, setPoolDesc] = useState('');
  const [poolTarget, setPoolTarget] = useState('');

  const loadPools = useCallback(async () => {
    try {
      const res = await api.listCampaignPools(campaignId);
      setPools(res.data || []);
    } catch {
      // Silently fail
    } finally {
      setLoading(false);
    }
  }, [campaignId]);

  useEffect(() => {
    loadPools();
  }, [loadPools]);

  const handleCreatePool = async (e) => {
    e.preventDefault();
    if (!poolTitle.trim() || !poolTarget) return;
    setCreating(true);
    try {
      await api.createPool({
        campaign_id: campaignId,
        title: poolTitle.trim(),
        description: poolDesc.trim() || undefined,
        target_amount: parseFloat(poolTarget),
      });
      toast('Pool created! Share the link with your group.', 'success');
      setShowCreateForm(false);
      setPoolTitle('');
      setPoolDesc('');
      setPoolTarget('');
      await loadPools();
    } catch (err) {
      toast(err.message || 'Failed to create pool', 'error');
    } finally {
      setCreating(false);
    }
  };

  const handleJoinPool = async (poolId) => {
    if (!joinAmount || parseFloat(joinAmount) <= 0) {
      toast('Enter a valid share amount', 'error');
      return;
    }
    setJoining(true);
    try {
      await api.joinPool(poolId, parseFloat(joinAmount), joinName.trim() || undefined);
      toast('You have joined the pool!', 'success');
      setJoinPoolId(null);
      setJoinAmount('');
      setJoinName('');
      await loadPools();
    } catch (err) {
      toast(err.message || 'Failed to join pool', 'error');
    } finally {
      setJoining(false);
    }
  };

  const handleLeavePool = async (poolId) => {
    try {
      await api.leavePool(poolId);
      toast('Left the pool', 'info');
      await loadPools();
    } catch (err) {
      toast(err.message || 'Failed to leave pool', 'error');
    }
  };

  const handleSubmitPool = async (pool) => {
    try {
      const res = await api.submitPool(pool.id);
      toast(res.message || 'Pool submitted!', 'success');
      await loadPools();
    } catch (err) {
      toast(err.message || 'Failed to submit pool', 'error');
    }
  };

  if (!user) {
    return (
      <div className="bg-white rounded-lg shadow p-6 text-center text-gray-500">
        Sign in to create or join a contribution pool.
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold text-gray-900">Contribution Pools</h3>
        <button
          onClick={() => setShowCreateForm(!showCreateForm)}
          className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium"
        >
          {showCreateForm ? 'Cancel' : '+ New Pool'}
        </button>
      </div>

      {/* Create Form */}
      {showCreateForm && (
        <form onSubmit={handleCreatePool} className="bg-gray-50 rounded-lg p-4 space-y-3">
          <input
            type="text"
            placeholder="Pool name (e.g. Team Alpha)"
            value={poolTitle}
            onChange={(e) => setPoolTitle(e.target.value)}
            className="w-full px-3 py-2 border rounded-lg text-sm"
            required
            maxLength={200}
          />
          <textarea
            placeholder="Optional description..."
            value={poolDesc}
            onChange={(e) => setPoolDesc(e.target.value)}
            className="w-full px-3 py-2 border rounded-lg text-sm"
            rows={2}
            maxLength={2000}
          />
          <div className="flex gap-3 items-end">
            <div className="flex-1">
              <label className="block text-xs text-gray-500 mb-1">Target amount</label>
              <input
                type="number"
                step="0.01"
                min="0.01"
                placeholder="100.00"
                value={poolTarget}
                onChange={(e) => setPoolTarget(e.target.value)}
                className="w-full px-3 py-2 border rounded-lg text-sm"
                required
              />
            </div>
            <button
              type="submit"
              disabled={creating}
              className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium disabled:opacity-50"
            >
              {creating ? 'Creating...' : 'Create Pool'}
            </button>
          </div>
        </form>
      )}

      {/* Pool List */}
      {loading ? (
        <div className="text-center text-gray-400 py-4 text-sm">Loading pools...</div>
      ) : pools.length === 0 ? (
        <div className="text-center text-gray-400 py-8 text-sm">
          No pools yet. Be the first to create one!
        </div>
      ) : (
        <div className="space-y-3">
          {pools.map((pool) => {
            const isLeader = pool.leader_id === user.id;
            const canSubmit = isLeader && pool.status === 'open';
            const isMember = pool.member_count > 0 && (isLeader || false); // simplified check

            return (
              <div key={pool.id} className="bg-white border rounded-lg p-4">
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <h4 className="font-semibold text-gray-900">{pool.title}</h4>
                    {pool.description && (
                      <p className="text-sm text-gray-500 mt-1">{pool.description}</p>
                    )}
                  </div>
                  <span className={`px-2 py-0.5 rounded text-xs font-medium ${
                    pool.status === 'open' ? 'bg-green-100 text-green-800' :
                    pool.status === 'submitted' ? 'bg-blue-100 text-blue-800' :
                    pool.status === 'cancelled' ? 'bg-red-100 text-red-800' :
                    'bg-gray-100 text-gray-800'
                  }`}>
                    {pool.status}
                  </span>
                </div>

                <div className="mt-3 flex items-center gap-4 text-sm text-gray-600">
                  <span>{pool.member_count} member{pool.member_count !== 1 ? 's' : ''}</span>
                  <span>Target: {parseFloat(pool.target_amount).toFixed(2)}</span>
                  {parseFloat(pool.raised_amount) > 0 && (
                    <span>Raised: {parseFloat(pool.raised_amount).toFixed(2)}</span>
                  )}
                </div>

                {/* Actions */}
                <div className="mt-3 flex gap-2">
                  {pool.status === 'open' && !isLeader && (
                    joinPoolId === pool.id ? (
                      <div className="flex gap-2 items-end flex-wrap">
                        <div>
                          <label className="block text-xs text-gray-500">Your share</label>
                          <input
                            type="number"
                            step="0.01"
                            min="0.01"
                            placeholder="10.00"
                            value={joinAmount}
                            onChange={(e) => setJoinAmount(e.target.value)}
                            className="w-28 px-2 py-1 border rounded text-sm"
                          />
                        </div>
                        <div>
                          <label className="block text-xs text-gray-500">Name (optional)</label>
                          <input
                            type="text"
                            placeholder="Display name"
                            value={joinName}
                            onChange={(e) => setJoinName(e.target.value)}
                            className="w-28 px-2 py-1 border rounded text-sm"
                            maxLength={50}
                          />
                        </div>
                        <button
                          onClick={() => handleJoinPool(pool.id)}
                          disabled={joining}
                          className="px-3 py-1.5 bg-indigo-600 text-white rounded text-sm hover:bg-indigo-700 disabled:opacity-50"
                        >
                          {joining ? 'Joining...' : 'Confirm'}
                        </button>
                        <button
                          onClick={() => { setJoinPoolId(null); setJoinAmount(''); }}
                          className="px-3 py-1.5 text-gray-500 text-sm"
                        >
                          Cancel
                        </button>
                      </div>
                    ) : (
                      <button
                        onClick={() => setJoinPoolId(pool.id)}
                        className="px-3 py-1.5 bg-indigo-100 text-indigo-700 rounded text-sm hover:bg-indigo-200"
                      >
                        Join Pool
                      </button>
                    )
                  )}
                  {canSubmit && (
                    <button
                      onClick={() => handleSubmitPool(pool)}
                      className="px-3 py-1.5 bg-green-600 text-white rounded text-sm hover:bg-green-700"
                    >
                      Submit Pool
                    </button>
                  )}
                  {isLeader && pool.status === 'open' && (
                    <button
                      onClick={() => handleLeavePool(pool.id)}
                      className="px-3 py-1.5 text-red-600 text-sm hover:bg-red-50 rounded"
                    >
                      Cancel Pool
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { api } from '../services/api';

const PERIOD_OPTIONS = [
  { months: 1, label: 'Monthly' },
  { months: 3, label: 'Quarterly' },
  { months: 6, label: 'Semi-annual' },
];

const MIN_PERIODS = 2;
const MAX_PERIODS = 24;
const PERIOD_DAYS = 30;

function formatDate(value) {
  return new Date(value).toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

function firstPaymentDate(periodMonths) {
  return formatDate(Date.now() + periodMonths * PERIOD_DAYS * 24 * 60 * 60 * 1000);
}

function ConfirmLockModal({ amountPerPeriod, asset, periodMonths, totalPeriods, totalCommitment, submitting, error, onConfirm, onClose }) {
  const periodLabel = PERIOD_OPTIONS.find((p) => p.months === periodMonths)?.label.toLowerCase();

  return (
    <div style={styles.overlay} onClick={onClose}>
      <div
        style={styles.modal}
        role="dialog"
        aria-modal="true"
        aria-label="Confirm recurring pledge"
        onClick={(e) => e.stopPropagation()}
      >
        <h2 style={{ margin: '0 0 0.5rem', fontSize: '1.1rem' }}>Lock {totalCommitment} {asset} now?</h2>
        <p style={{ margin: '0 0 1rem', color: 'var(--color-text-secondary)', fontSize: '0.88rem', lineHeight: 1.5 }}>
          Stellar has no recurring payments, so the whole commitment leaves your wallet immediately
          and is held in {totalPeriods} claimable balances on the ledger — one per period. CrowdPay
          releases each one to the campaign on its scheduled date.
        </p>
        <ul style={{ margin: '0 0 1rem', paddingLeft: '1.1rem', color: 'var(--color-text-secondary)', fontSize: '0.85rem', lineHeight: 1.6 }}>
          <li>
            {amountPerPeriod} {asset} {periodLabel}, {totalPeriods} times
          </li>
          <li>First payment on {firstPaymentDate(periodMonths)}</li>
          <li>Cancelling stops any payment more than 7 days away; you reclaim those funds yourself 30 days after their scheduled date</li>
        </ul>

        {error && <p className="alert alert--error" style={{ marginBottom: '0.75rem' }}>{error}</p>}

        <div style={{ display: 'flex', gap: '0.5rem', justifyContent: 'flex-end' }}>
          <button
            type="button"
            className="btn-secondary"
            onClick={onClose}
            style={{ fontSize: '0.85rem', padding: '0.4rem 1rem' }}
          >
            Cancel
          </button>
          <button
            type="button"
            className="btn-primary"
            onClick={onConfirm}
            disabled={submitting}
            aria-busy={submitting}
            style={{ fontSize: '0.85rem', padding: '0.4rem 1rem' }}
          >
            {submitting ? 'Locking funds…' : 'Confirm & Lock Funds'}
          </button>
        </div>
      </div>
    </div>
  );
}

export default function RecurringPledgeForm({ campaignId, asset, onSubscribed }) {
  const [open, setOpen] = useState(false);
  const [amountPerPeriod, setAmountPerPeriod] = useState('');
  const [periodMonths, setPeriodMonths] = useState(1);
  const [totalPeriods, setTotalPeriods] = useState(6);
  const [showConfirm, setShowConfirm] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [created, setCreated] = useState(null);

  const amount = parseFloat(amountPerPeriod);
  const amountValid = Number.isFinite(amount) && amount > 0;
  const totalCommitment = amountValid ? Number((amount * totalPeriods).toFixed(7)) : 0;

  async function confirmPledge() {
    setSubmitting(true);
    setError('');
    try {
      const subscription = await api.createSubscription(campaignId, {
        amountPerPeriod: amount,
        asset,
        periodMonths,
        totalPeriods,
      });
      setCreated(subscription);
      setShowConfirm(false);
      setOpen(false);
      setAmountPerPeriod('');
      onSubscribed?.(subscription);
    } catch (err) {
      setError(err.message || 'Could not start this recurring pledge');
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div style={{ marginTop: '0.75rem' }}>
      <button
        type="button"
        className="btn-secondary"
        aria-expanded={open}
        onClick={() => {
          setOpen((prev) => !prev);
          setCreated(null);
        }}
        style={{ width: '100%', padding: '0.6rem 1rem' }}
      >
        {open ? 'Hide monthly pledge' : 'Pledge Monthly'}
      </button>

      {created && !open && (
        <p className="alert alert--success" style={{ marginTop: '0.65rem', fontSize: '0.85rem' }}>
          Recurring pledge active — {created.totalCommitment} {asset} locked across{' '}
          {created.balanceIds.length} payments, first on {formatDate(created.firstPaymentDate)}.
        </p>
      )}

      {open && (
        <div
          style={{
            marginTop: '0.75rem',
            padding: '1rem',
            border: '1px solid var(--color-border)',
            borderRadius: '10px',
          }}
        >
          <label htmlFor="pledge-amount" style={styles.label}>
            Amount per period ({asset})
          </label>
          <input
            id="pledge-amount"
            type="number"
            min="0"
            step="0.0000001"
            value={amountPerPeriod}
            onChange={(e) => setAmountPerPeriod(e.target.value)}
            style={styles.input}
          />

          <fieldset style={{ border: 0, padding: 0, margin: '0.9rem 0 0' }}>
            <legend style={styles.label}>Frequency</legend>
            <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap' }}>
              {PERIOD_OPTIONS.map((option) => (
                <button
                  key={option.months}
                  type="button"
                  className={periodMonths === option.months ? 'btn-primary' : 'btn-secondary'}
                  aria-pressed={periodMonths === option.months}
                  onClick={() => setPeriodMonths(option.months)}
                  style={{ fontSize: '0.82rem', padding: '0.35rem 0.8rem' }}
                >
                  {option.label}
                </button>
              ))}
            </div>
          </fieldset>

          <label htmlFor="pledge-periods" style={{ ...styles.label, marginTop: '0.9rem' }}>
            Number of periods: {totalPeriods}
          </label>
          <input
            id="pledge-periods"
            type="range"
            min={MIN_PERIODS}
            max={MAX_PERIODS}
            value={totalPeriods}
            onChange={(e) => setTotalPeriods(Number(e.target.value))}
            style={{ width: '100%' }}
          />

          <div
            style={{
              marginTop: '0.9rem',
              padding: '0.75rem',
              borderRadius: '8px',
              background: 'var(--color-surface, rgba(0,0,0,0.04))',
            }}
          >
            <div style={{ fontSize: '0.78rem', color: 'var(--color-text-hint)' }}>
              Total commitment
            </div>
            <strong style={{ fontSize: '1.35rem' }}>
              {totalCommitment} {asset}
            </strong>
            <div style={{ fontSize: '0.8rem', color: 'var(--color-text-secondary)', marginTop: '0.2rem' }}>
              First payment {firstPaymentDate(periodMonths)} · locked on Stellar up front
            </div>
          </div>

          {error && !showConfirm && (
            <p className="alert alert--error" style={{ marginTop: '0.75rem', fontSize: '0.85rem' }}>
              {error}
            </p>
          )}

          <button
            type="button"
