import React, { useCallback, useEffect, useState } from 'react';
import { api } from '../services/api';

const DEFAULT_COMMISSION = 5;
const DEFAULT_MAX_REFERRERS = 20;

export default function ReferralProgramSettings({ campaignId }) {
  const [program, setProgram] = useState(null);
  const [enabled, setEnabled] = useState(false);
  const [commissionPercentage, setCommissionPercentage] = useState(DEFAULT_COMMISSION);
  const [maxReferrers, setMaxReferrers] = useState(DEFAULT_MAX_REFERRERS);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [status, setStatus] = useState('');

  useEffect(() => {
    if (!campaignId) return;
    api
      .getReferralProgram(campaignId)
      .then((data) => {
        setProgram(data);
        setEnabled(true);
        setCommissionPercentage(Number(data.commission_percentage));
        setMaxReferrers(Number(data.max_referrers));
      })
      .catch(() => {
        setProgram(null);
        setEnabled(false);
      });
  }, [campaignId]);

  const handleSave = useCallback(async () => {
    setSaving(true);
    setError('');
    setStatus('');
    try {
      const saved = await api.enableReferralProgram(campaignId, {
        commissionPercentage: Number(commissionPercentage),
        maxReferrers: Number(maxReferrers),
      });
      setProgram(saved);
      setStatus('Referral program saved.');
    } catch (err) {
      setError(err.message || 'Could not save the referral program');
    } finally {
      setSaving(false);
    }
  }, [campaignId, commissionPercentage, maxReferrers]);

  return (
    <div className="campaign-card" style={{ display: 'grid', gap: '0.85rem' }}>
      <label style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', fontWeight: 600 }}>
        <input
          type="checkbox"
          checked={enabled}
          onChange={(e) => setEnabled(e.target.checked)}
          aria-label="Enable referrals"
        />
        Enable Referrals
      </label>

      <p style={{ margin: 0, fontSize: '0.82rem', color: 'var(--color-text-muted)' }}>
        Supporters get a trackable share link. Their commission is paid out of the campaign balance
        in the same transaction as your withdrawal.
      </p>

      {enabled && (
        <>
          <div style={{ display: 'grid', gap: '0.35rem' }}>
            <label htmlFor="referral-commission" style={{ fontSize: '0.85rem', fontWeight: 600 }}>
              Commission: {commissionPercentage}%
            </label>
            <input
              id="referral-commission"
              type="range"
              min="1"
              max="20"
              step="1"
              value={commissionPercentage}
              onChange={(e) => setCommissionPercentage(Number(e.target.value))}
            />
          </div>

          <div style={{ display: 'grid', gap: '0.35rem' }}>
            <label htmlFor="referral-max" style={{ fontSize: '0.85rem', fontWeight: 600 }}>
              Maximum referrers
            </label>
            <input
              id="referral-max"
              type="number"
              min="1"
              max="100"
              value={maxReferrers}
              onChange={(e) => setMaxReferrers(e.target.value)}
              style={{ maxWidth: '8rem', padding: '0.4rem 0.5rem' }}
            />
          </div>

          <button
            type="button"
            className="btn-primary"
            onClick={handleSave}
            disabled={saving}
            style={{ justifySelf: 'start' }}
          >
            {saving ? 'Saving…' : program ? 'Update referral program' : 'Enable referrals'}
          </button>
        </>
      )}

      {error && <p style={{ margin: 0, color: 'var(--color-danger)', fontSize: '0.85rem' }}>{error}</p>}
      {status && <p style={{ margin: 0, color: 'var(--color-success)', fontSize: '0.85rem' }}>{status}</p>}
    </div>
  );
}

import { useRelativeTime } from '../hooks/useRelativeTime';

export default function RelativeTime({ date, title }) {
  const label = useRelativeTime(date);
  if (!date) return null;
  const dateObj = new Date(date);
  if (isNaN(dateObj.getTime())) return null;

  return (
    <time dateTime={dateObj.toISOString()} title={title ?? dateObj.toLocaleString()}>
      {label}
    </time>
  );
}

/**
 * ReputationGauge
 *
 * Displays a contributor's reputation score (0–1000) as an SVG radial gauge
 * with a tier label.  No external charting library required.
 *
 * Tiers (per spec):
 *   Newcomer    0–99
 *   Contributor 100–299
 *   Trusted     300–599
 *   Veteran     600–849
 *   Champion    850–1000
 */

const TIERS = [
  { label: 'Newcomer',    min: 0,   max: 99,   color: 'var(--color-text-hint)' },
  { label: 'Contributor', min: 100, max: 299,  color: 'var(--color-accent)' },
  { label: 'Trusted',     min: 300, max: 599,  color: 'var(--color-accent-light)' },
  { label: 'Veteran',     min: 600, max: 849,  color: '#7c3aed' },
  { label: 'Champion',    min: 850, max: 1000, color: 'var(--color-teal)' },
];

function getTier(score) {
  return TIERS.find((t) => score >= t.min && score <= t.max) || TIERS[0];
}

/** Convert polar coords to SVG cartesian. cx/cy = centre, r = radius. */
function polarToCartesian(cx, cy, r, angleDeg) {
  const rad = ((angleDeg - 90) * Math.PI) / 180;
  return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
}

/** Build an SVG arc path for a gauge that sweeps from startDeg to endDeg. */
function arcPath(cx, cy, r, startDeg, endDeg) {
  const start = polarToCartesian(cx, cy, r, endDeg);
  const end = polarToCartesian(cx, cy, r, startDeg);
  const large = endDeg - startDeg > 180 ? 1 : 0;
  return `M ${start.x} ${start.y} A ${r} ${r} 0 ${large} 0 ${end.x} ${end.y}`;
}

export default function ReputationGauge({ score = 0, size = 160 }) {
  const clamped = Math.max(0, Math.min(1000, score));
  const tier = getTier(clamped);

  // Gauge sweeps 240° (from -120° to +120° relative to bottom, i.e. 120°–360°)
  const START_DEG = 120;
  const END_DEG   = 420; // = 360 + 60, drawn as 420 for SVG arc maths
  const TOTAL_DEG = END_DEG - START_DEG; // 300°

  const cx = size / 2;
  const cy = size / 2;
  const r  = size * 0.38;
  const strokeWidth = size * 0.09;

  const filledDeg = START_DEG + (clamped / 1000) * TOTAL_DEG;

  const trackPath = arcPath(cx, cy, r, START_DEG, END_DEG);
  const fillPath  = clamped > 0 ? arcPath(cx, cy, r, START_DEG, filledDeg) : null;

  return (
    <div
      style={{
        display: 'inline-flex',
        flexDirection: 'column',
        alignItems: 'center',
        gap: '0.25rem',
      }}
      aria-label={`Reputation score: ${clamped} — ${tier.label}`}
      role="img"
    >
      <svg width={size} height={size * 0.75} viewBox={`0 0 ${size} ${size}`} aria-hidden="true">
        {/* Track */}
        <path
          d={trackPath}
          fill="none"
          stroke="var(--color-border, #e2e8f0)"
          strokeWidth={strokeWidth}
          strokeLinecap="round"
        />
        {/* Filled arc */}
        {fillPath && (
          <path
            d={fillPath}
            fill="none"
            stroke={tier.color}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            style={{ transition: 'stroke-dashoffset 0.6s ease' }}
          />
        )}
        {/* Score text */}
        <text
          x={cx}
          y={cy + size * 0.06}
          textAnchor="middle"
          fontSize={size * 0.2}
          fontWeight="700"
          fill="var(--color-text, #1a202c)"
        >
          {clamped}
        </text>
        <text
          x={cx}
          y={cy + size * 0.2}
          textAnchor="middle"
          fontSize={size * 0.1}
          fill="var(--color-text-secondary, #718096)"
        >
          / 1000
        </text>
      </svg>

      {/* Tier label */}
      <span
        style={{
          fontSize: '0.85rem',
          fontWeight: 600,
          color: tier.color,
          letterSpacing: '0.03em',
          textTransform: 'uppercase',
        }}
      >
        {tier.label}
      </span>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { api } from '../services/api';

const PERIOD_LABELS = { 1: 'Monthly', 3: 'Quarterly', 6: 'Semi-annual' };

function formatDate(value) {
  if (!value) return '—';
  return new Date(value).toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

function SubscriptionRow({ subscription, result, onCancelled }) {
  const [cancelling, setCancelling] = useState(false);
  const [error, setError] = useState('');

  async function cancel() {
    setCancelling(true);
    setError('');
    try {
      const summary = await api.cancelSubscription(subscription.campaign_id, subscription.id);
      onCancelled?.(subscription.id, summary);
    } catch (err) {
      setError(err.message || 'Could not cancel this subscription');
    } finally {
      setCancelling(false);
    }
  }

  return (
    <div className="campaign-card" style={{ minHeight: 'auto' }}>
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          gap: '0.75rem',
          flexWrap: 'wrap',
          alignItems: 'center',
        }}
      >
        <div>
          <Link
            to={`/campaigns/${subscription.campaign_id}`}
            style={{ fontWeight: 700, color: 'var(--color-accent)' }}
          >
            {subscription.campaign_title}
          </Link>
          <div style={{ fontSize: '0.85rem', color: 'var(--color-text-secondary)', marginTop: '0.25rem' }}>
            {subscription.amount_per_period} {subscription.asset} ·{' '}
            {PERIOD_LABELS[subscription.period_months] || `Every ${subscription.period_months} months`} ·{' '}
            {subscription.periods_claimed}/{subscription.total_periods} paid
          </div>
          <div style={{ fontSize: '0.85rem', color: 'var(--color-text-hint)', marginTop: '0.2rem' }}>
            Next payment: {formatDate(subscription.next_payment_date)}
          </div>
        </div>

        {subscription.status === 'active' ? (
          <button
            type="button"
            className="btn-secondary"
            onClick={cancel}
            disabled={cancelling}
            aria-busy={cancelling}
            style={{ fontSize: '0.82rem', padding: '0.35rem 0.9rem' }}
          >
            {cancelling ? 'Cancelling…' : 'Cancel'}
          </button>
        ) : (
          <span style={{ fontSize: '0.82rem', color: 'var(--color-text-hint)' }}>
            {subscription.status}
          </span>
        )}
      </div>

      {error && (
        <p className="alert alert--error" style={{ marginTop: '0.6rem', fontSize: '0.85rem' }}>
          {error}
        </p>
      )}

      {result && (
        <p className="alert alert--info" style={{ marginTop: '0.6rem', fontSize: '0.85rem' }}>
          {result.cancelled} future payment{result.cancelled === 1 ? '' : 's'} cancelled
          {result.nonCancellable > 0
            ? `, ${result.nonCancellable} could not be cancelled (already claimed or due within 7 days)`
            : ''}
          .
          {result.estimatedRefundDate
            ? ` You can reclaim the locked funds from ${formatDate(result.estimatedRefundDate)}.`
            : ''}
        </p>
      )}
    </div>
  );
}

export default function SubscriptionsPanel() {
  const [subscriptions, setSubscriptions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  // Cancellation summaries live here so they survive the refresh that follows a cancel.
  const [cancellations, setCancellations] = useState({});

  const load = useCallback(
    () =>
      api
        .getMySubscriptions()
        .then((data) => setSubscriptions(data.subscriptions || []))
        .catch((err) => setError(err.message || 'Could not load subscriptions'))
        .finally(() => setLoading(false)),
    []
  );

  useEffect(() => {
    load();
  }, [load]);

  function handleCancelled(subscriptionId, summary) {
    setCancellations((prev) => ({ ...prev, [subscriptionId]: summary }));
    load();
  }

  if (loading) return <p style={{ color: 'var(--color-text-hint)' }}>Loading subscriptions…</p>;
  if (error) return <p className="alert alert--error">{error}</p>;
  if (!subscriptions.length) {
    return (
      <p className="alert alert--info">
        You have no recurring pledges yet. Open a campaign and choose “Pledge Monthly” to start one.
      </p>
    );
  }

  return (
    <div style={{ display: 'grid', gap: '0.75rem' }}>
      {subscriptions.map((subscription) => (
        <SubscriptionRow
          key={subscription.id}
          subscription={subscription}
          result={cancellations[subscription.id]}
          onCancelled={handleCancelled}
        />
      ))}
    </div>
  );
}

