/**
 * Creator-facing treasury tab: balances, the policy as the contract holds it, a
 * withdrawal form that reports which constraint applies, and the on-chain history.
 */
export default function TreasuryPanel({ campaignId, assetType = 'USDC', isAuditor = false }) {
  const [status, setStatus] = useState(null);
  const [error, setError] = useState('');
  const [amount, setAmount] = useState('');
  const [destination, setDestination] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [outcome, setOutcome] = useState(null);

  const load = useCallback(() => {
    if (!campaignId) return;
    api
      .getTreasuryStatus(campaignId)
      .then((next) => {
        setStatus(next);
        setError('');
      })
      .catch((err) => setError(err.code === 'NOT_CONTRACT_WALLET' ? 'not_contract' : err.message));
  }, [campaignId]);

  useEffect(load, [load]);

  async function submitWithdrawal(event) {
    event.preventDefault();
    setSubmitting(true);
    setOutcome(null);
    try {
      const result = await api.requestTreasuryWithdrawal(campaignId, { amount, destination });
      setOutcome(
        result.type === 'pending_auditor'
          ? { kind: 'pending', message: 'Sent to the auditor for approval.' }
          : { kind: 'done', message: 'Withdrawal executed.' }
      );
      setAmount('');
      load();
    } catch (err) {
      setOutcome({ kind: 'error', message: describeRejection(err) });
    } finally {
      setSubmitting(false);
    }
  }

  async function approve(pendingId) {
    try {
      await api.approveTreasuryWithdrawal(campaignId, pendingId);
      load();
    } catch (err) {
      setOutcome({ kind: 'error', message: describeRejection(err) });
    }
  }

  if (error === 'not_contract') {
    return (
      <p style={{ color: 'var(--color-text-muted)' }}>
        This campaign uses the standard multisig wallet, so there is no contract treasury.
      </p>
    );
  }
  if (error) return <p style={{ color: 'var(--color-danger)' }}>{error}</p>;
  if (!status) return <p style={{ color: 'var(--color-text-muted)' }}>Loading treasury…</p>;

  return (
    <section aria-label="Treasury">
      <div>
        <h3>Balance</h3>
        <p>
          Received: <Amount value={status.totalReceived} asset={assetType} />
        </p>
        <p>
          Withdrawn: <Amount value={status.totalWithdrawn} asset={assetType} />
        </p>
        <p>
          Available: <Amount value={status.available} asset={assetType} />
        </p>
      </div>

      <div>
        <h3>Policy</h3>
        <ul>
          <li>Hold period: {status.policy.minHoldDays} days after the deadline</li>
          <li>Max single withdrawal: {status.policy.maxSingleWithdrawalPct}% of the balance</li>
          <li>Cooldown: {status.policy.withdrawalCooldownHours} hours between withdrawals</li>
          <li>
            Auditor required above:{' '}
            <Amount value={status.policy.requireAuditorForAbove} asset={assetType} />
          </li>
          <li>Auto-refund on miss: {status.policy.autoRefundOnMiss ? 'on' : 'off'}</li>
        </ul>
      </div>

      <form onSubmit={submitWithdrawal} aria-label="Request withdrawal">
        <h3>Request a withdrawal</h3>
        <label htmlFor="treasury-amount">Amount</label>
        <input
          id="treasury-amount"
          value={amount}
          inputMode="decimal"
          onChange={(e) => setAmount(e.target.value)}
        />
        <label htmlFor="treasury-destination">Destination</label>
        <input
          id="treasury-destination"
          value={destination}
          onChange={(e) => setDestination(e.target.value)}
        />
        {amount && Number(amount) > Number(status.policy.requireAuditorForAbove) && (
          <p style={{ color: 'var(--color-text-muted)' }}>
            This amount is above the auditor threshold, so it will need auditor approval.
          </p>
        )}
        <button type="submit" disabled={submitting || !amount || !destination}>
          {submitting ? 'Requesting…' : 'Request withdrawal'}
        </button>
        {outcome && (
          <p
            style={{
              color: outcome.kind === 'error' ? 'var(--color-danger)' : 'var(--color-success)',
            }}
          >
            {outcome.message}
          </p>
        )}
      </form>

      {status.pendingWithdrawals.length > 0 && (
        <div>
          <h3>Awaiting auditor approval</h3>
          <table>
            <thead>
              <tr>
                <th>Amount</th>
                <th>Destination</th>
                <th>Requested</th>
                {isAuditor && <th>Action</th>}
              </tr>
            </thead>
            <tbody>
              {status.pendingWithdrawals.map((entry) => (
                <tr key={entry.id}>
                  <td>
                    <Amount value={entry.amount} asset={assetType} />
                  </td>
                  <td>{entry.destination}</td>
                  <td>{new Date(entry.createdAt).toLocaleDateString()}</td>
                  {isAuditor && (
                    <td>
                      <button type="button" onClick={() => approve(entry.id)}>
                        Approve
                      </button>
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <div>
        <h3>Withdrawal history</h3>
        {status.withdrawalHistory.length === 0 ? (
          <p style={{ color: 'var(--color-text-muted)' }}>No withdrawals yet.</p>
        ) : (
          <table>
            <thead>
              <tr>
                <th>Amount</th>
                <th>Destination</th>
                <th>Date</th>
                <th>Approved by</th>
              </tr>
            </thead>
            <tbody>
              {status.withdrawalHistory.map((record) => (
                <tr key={record.id}>
                  <td>
                    <Amount value={record.amount} asset={assetType} />
                  </td>
                  <td>{record.destination}</td>
                  <td>{new Date(record.executedAt).toLocaleDateString()}</td>
                  <td>{record.approvedBy ? 'Auditor' : '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </section>
  );
}

/** Turns a contract rejection into something a creator can act on. */
export function describeRejection(err) {
  switch (err.code) {
    case 'HOLD_PERIOD_NOT_ELAPSED':
      return 'The hold period after the campaign deadline has not elapsed yet.';
    case 'EXCEEDS_MAX_WITHDRAWAL_PCT':
      return 'That is a larger share of the balance than the policy allows in one withdrawal.';
    case 'COOLDOWN_NOT_ELAPSED':
      return 'The cooldown since your last withdrawal has not elapsed yet.';
    case 'INSUFFICIENT_BALANCE':
      return 'The treasury does not hold that much.';
    case 'TREASURY_PAUSED':
      return 'The treasury is paused, so no funds can move.';
    case 'AUDITOR_NOT_CONFIGURED':
      return 'This amount needs an auditor, but none is configured for the campaign.';
    default:
      return err.message || 'The treasury rejected that request.';
  }
}

import React, { useState } from 'react';
import { api } from '../services/api';

/**
 * Policy configuration for a contract-mode campaign. Shown at creation time and
 * only until the treasury is deployed — after that the on-chain policy governs and
 * the backend refuses edits, so the form reports that rather than pretending to save.
 */
export default function TreasuryPolicyForm({ campaignId, initialPolicy = {}, onSaved }) {
  const [policy, setPolicy] = useState({
    minHoldDays: initialPolicy.min_hold_days ?? 0,
    maxSingleWithdrawalPct: initialPolicy.max_single_withdrawal_pct ?? 100,
    withdrawalCooldownHours: initialPolicy.withdrawal_cooldown_hours ?? 0,
    requireAuditorForAbove: initialPolicy.require_auditor_for_above ?? '0',
    autoRefundOnMiss: initialPolicy.auto_refund_on_miss ?? false,
  });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [saved, setSaved] = useState(false);

  const update = (field) => (event) => {
    const value =
      event.target.type === 'checkbox'
        ? event.target.checked
        : event.target.type === 'range' || event.target.type === 'number'
          ? Number(event.target.value)
          : event.target.value;
    setPolicy((current) => ({ ...current, [field]: value }));
    setSaved(false);
  };

  async function submit(event) {
    event.preventDefault();
    setSaving(true);
    setError('');
    try {
      const result = await api.setTreasuryPolicy(campaignId, policy);
      setSaved(true);
      if (onSaved) onSaved(result);
    } catch (err) {
      setError(
        err.code === 'TREASURY_ALREADY_DEPLOYED'
          ? 'The treasury is already deployed — its policy is fixed on-chain and cannot be edited.'
          : err.message || 'Could not save the treasury policy'
      );
    } finally {
      setSaving(false);
    }
  }

  return (
    <form onSubmit={submit} aria-label="Treasury policy">
      <p style={{ color: 'var(--color-text-muted)' }}>
        These rules are enforced by the Soroban contract that holds the funds, not by CrowdPay.
        Once the treasury is deployed they cannot be changed.
      </p>

      <label htmlFor="minHoldDays">
        Minimum hold period: <strong>{policy.minHoldDays} days</strong> after the deadline
      </label>
      <input
        id="minHoldDays"
        type="range"
        min="0"
        max="90"
        value={policy.minHoldDays}
        onChange={update('minHoldDays')}
      />

      <label htmlFor="maxSingleWithdrawalPct">
        Maximum single withdrawal: <strong>{policy.maxSingleWithdrawalPct}%</strong> of the balance
      </label>
      <input
        id="maxSingleWithdrawalPct"
        type="range"
        min="10"
        max="100"
        value={policy.maxSingleWithdrawalPct}
        onChange={update('maxSingleWithdrawalPct')}
      />

      <label htmlFor="withdrawalCooldownHours">
        Cooldown between withdrawals: <strong>{policy.withdrawalCooldownHours} hours</strong>
      </label>
      <input
        id="withdrawalCooldownHours"
        type="range"
        min="0"
        max="168"
        value={policy.withdrawalCooldownHours}
        onChange={update('withdrawalCooldownHours')}
      />

      <label htmlFor="requireAuditorForAbove">Auditor required above</label>
      <input
        id="requireAuditorForAbove"
        type="text"
        inputMode="decimal"
        value={policy.requireAuditorForAbove}
        onChange={update('requireAuditorForAbove')}
      />

      <label htmlFor="autoRefundOnMiss">
        <input
          id="autoRefundOnMiss"
          type="checkbox"
          checked={policy.autoRefundOnMiss}
          onChange={update('autoRefundOnMiss')}
        />
        Refund contributors automatically if the goal is missed
      </label>
      <small style={{ color: 'var(--color-text-muted)' }}>
        Anyone can trigger the refund once the deadline passes, so contributors are not dependent
        on you or CrowdPay acting.
      </small>

      {error && <p style={{ color: 'var(--color-danger)' }}>{error}</p>}
      {saved && <p style={{ color: 'var(--color-success)' }}>Treasury policy saved.</p>}

      <button type="submit" disabled={saving}>
        {saving ? 'Saving…' : 'Save treasury policy'}
      </button>
    </form>
  );
}

const TIER_LABELS = {
  none: 'Unverified',
  basic: 'Basic',
  standard: 'Standard',
  enhanced: 'Enhanced',
};

export default function VerificationBadge({ status, tier, compact = false, showTier = false }) {
  const effectiveTier = tier || 'none';
  const tierLabel = TIER_LABELS[effectiveTier] || 'Unverified';

  if (status === 'verified' || status === 'approved') {
    const label = showTier ? `Verified · ${tierLabel}` : 'Verified';
    return <span style={compact ? styles.verifiedCompact : styles.verified}>✓ {label}</span>;
  }
  if (status === 'pending') {
    return (
      <span style={compact ? styles.pendingCompact : styles.pending}>Pending verification</span>
    );
  }
  if (status === 'rejected' || status === 'declined') {
    return (
      <span style={compact ? styles.rejectedCompact : styles.rejected}>Verification rejected</span>
    );
  }

  return <span style={compact ? styles.warningCompact : styles.warning}>Not verified</span>;
}

