  dot: { width: 10, height: 10, borderRadius: '50%', background: 'var(--color-accent)', marginTop: '0.45rem' },
  card: { borderLeft: '2px solid var(--color-border-light)', paddingLeft: '0.85rem' },
  itemTop: { display: 'flex', justifyContent: 'space-between', gap: '1rem', flexWrap: 'wrap' },
  status: { textTransform: 'capitalize', color: 'var(--color-text-hint)', fontSize: '0.85rem' },
  meta: { marginTop: '0.25rem', color: 'var(--color-text-secondary)', fontSize: '0.9rem' },
  link: { display: 'inline-block', marginTop: '0.4rem', color: 'var(--color-accent)' },
};

import { useEffect, useState, useCallback } from 'react';
import { api } from '../services/api';
import { getNetwork, signTransaction } from '@stellar/freighter-api';
import { stellarExpertTxUrl } from '../config/stellar';
import { useToast } from '../context/ToastContext';
import RelativeTime from './RelativeTime';

const ELIGIBLE = ['active', 'funded'];

function statusLabel(row, isExpired) {
  if (isExpired) return 'Expired — please re-request';
  if (row.status === 'pending') {
    if (!row.creator_signed) return 'Awaiting creator signature';
    if (!row.platform_signed) return 'Awaiting platform release';
  }
  if (row.status === 'submitted') return 'Released on-chain';
  if (row.status === 'denied') return 'Denied / cancelled';
  if (row.status === 'failed') return 'Failed (see audit)';
  return row.status;
}

export default function WithdrawalsSection({ campaign, milestones = [], user, token, onReleased }) {
  const toast = useToast();
  const [forbidden, setForbidden] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [cap, setCap] = useState({ can_approve_platform: false });
  const [rows, setRows] = useState([]);
  const [form, setForm] = useState({ destination_key: '', amount: '' });
  const [busyId, setBusyId] = useState(null);
  const [eventsById, setEventsById] = useState({});
  const [openAudit, setOpenAudit] = useState(null);
  const [milestoneForms, setMilestoneForms] = useState({});
  const [uploadingMilestoneId, setUploadingMilestoneId] = useState(null);
  const [expiredIds, setExpiredIds] = useState(() => new Set());
  const [liveBalance, setLiveBalance] = useState(null);
  const [loadingBalance, setLoadingBalance] = useState(false);
  const [rejectingId, setRejectingId] = useState(null);
  const [rejectReason, setRejectReason] = useState('');
  const [confirmingSignId, setConfirmingSignId] = useState(null);

  const isCreator = user?.id && campaign.creator_id === user.id;
  const isAdmin = user?.role === 'admin';
  const hasMilestonePlan = milestones.length > 0;
  const canView = !forbidden && (isCreator || cap.can_approve_platform);
  const hasPending = rows.some((r) => r.status === 'pending');
  const canOpenRequest =
    isCreator && !hasMilestonePlan && ELIGIBLE.includes(campaign.status) && !hasPending;
  const pendingMilestones = milestones.filter((milestone) => milestone.status !== 'released');

  useEffect(() => {
    setMilestoneForms((current) => {
      const next = { ...current };
      let changed = false;
      for (const milestone of pendingMilestones) {
        if (!next[milestone.id]) {
          next[milestone.id] = {
            evidence_url: milestone.evidence_url || '',
            evidence_description: milestone.evidence_description || '',
            destination_key: milestone.destination_key || '',
          };
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [pendingMilestones]);

  useEffect(() => {
    if (!canOpenRequest) {
      setLiveBalance(null);
      return;
    }
    setLoadingBalance(true);
    api
      .getCampaignBalance(campaign.id)
      .then((b) => {
        setLiveBalance(parseFloat(b[campaign.asset_type] || '0'));
        setLoadingBalance(false);
      })
      .catch(() => setLoadingBalance(false));
  }, [canOpenRequest, campaign.id, campaign.asset_type]);

  const refresh = useCallback(async () => {
    if (!token) return;
    setError('');
    try {
      const caps = await api.getWithdrawalCapabilities(token);
      setCap(caps);
      const list = await api.listWithdrawals(campaign.id, token);
      setRows(list);
      setForbidden(false);
    } catch (e) {
      if (e.status === 403) {
        setForbidden(true);
        setRows([]);
      } else {
        setError(e.message || 'Could not load withdrawals.');
      }
    } finally {
      setLoading(false);
    }
  }, [campaign.id, token]);

  useEffect(() => {
    if (!token) {
      setLoading(false);
      return;
    }
    setLoading(true);
    refresh();
  }, [token, refresh]);

  async function loadEvents(id) {
    if (openAudit === id) {
      setOpenAudit(null);
      return;
    }
    if (eventsById[id]) {
      setOpenAudit(id);
      return;
    }
    try {
      const ev = await api.getWithdrawalEvents(id, token);
      setEventsById((m) => ({ ...m, [id]: ev }));
      setOpenAudit(id);
    } catch (e) {
      setError(e.message || 'Could not load audit trail.');
    }
  }

  async function handleRequest(e) {
    e.preventDefault();
    setBusyId('new');
    setError('');
    try {
      await api.requestWithdrawal({
        campaign_id: campaign.id,
        destination_key: form.destination_key.trim(),
        amount: form.amount.trim(),
      });
      setForm({ destination_key: '', amount: '' });
      await refresh();
      onReleased?.();
    } catch (err) {
      setError(err.message || 'Request failed.');
    } finally {
      setBusyId(null);
    }
  }

  async function runAction(id, fn, successMessage) {
    setBusyId(id);
    setError('');
    try {
      await fn();
      await refresh();
      onReleased?.();
      if (successMessage) toast?.(successMessage, 'success');
    } catch (err) {
      if (err.status === 410) {
        setExpiredIds((prev) => new Set([...prev, id]));
      } else {
        setError(err.message || 'Action failed.');
      }
    } finally {
      setBusyId(null);
    }
  }

  async function signAsFreighter(id) {
    setBusyId(id);
    setError('');
    try {
      const wr = await api.getWithdrawal(id, token);
      const unsignedXdr = wr.unsigned_xdr;
      if (!unsignedXdr) throw new Error('Missing unsigned transaction');

      const network = await getNetwork();
      if (network?.error) throw new Error('Could not read Freighter network');

      const signed = await signTransaction(unsignedXdr, {
        networkPassphrase: network?.networkPassphrase,
        address: user?.wallet_public_key,
      });
      if (signed?.error) throw new Error(signed.error?.message || 'Freighter signing failed');
      if (!signed?.signedTxXdr) throw new Error('Freighter did not return a signed transaction');

      await api.approveWithdrawalCreator(id, { signed_xdr: signed.signedTxXdr });
      await refresh();
    } catch (err) {
      setError(err.message || 'Could not sign with Freighter');
    } finally {
      setBusyId(null);
    }
  }

  function setMilestoneField(milestoneId, field, value) {
    setMilestoneForms((current) => ({
      ...current,
      [milestoneId]: { ...(current[milestoneId] || {}), [field]: value },
    }));
  }

  async function uploadMilestoneFile(milestoneId, file) {
    if (!file) return;
    setUploadingMilestoneId(milestoneId);
    setError('');
    try {
      const result = await api.uploadMilestoneEvidence(milestoneId, file);
      setMilestoneField(milestoneId, 'evidence_url', result.evidence_url);
      toast?.('Evidence file uploaded', 'success');
    } catch (err) {
      setError(err.message || 'Evidence upload failed.');
    } finally {
      setUploadingMilestoneId(null);
    }
  }

  async function requestMilestoneRelease(milestoneId) {
    const payload = milestoneForms[milestoneId] || {};
    if (!payload.evidence_url?.trim() || !payload.destination_key?.trim()) {
      setError('Milestone evidence and payout destination are both required.');
      return;
    }
    setBusyId(`milestone-${milestoneId}`);
    setError('');
    try {
      await api.submitMilestoneEvidence(milestoneId, {
        evidence_url: payload.evidence_url.trim(),
        evidence_description: payload.evidence_description?.trim() || undefined,
        destination_key: payload.destination_key.trim(),
      });
      await refresh();
      onReleased?.();
      toast?.('Evidence submitted for platform review', 'success');
    } catch (err) {
      setError(err.message || 'Milestone release request failed.');
    } finally {
      setBusyId(null);
    }
  }

  function milestoneStatusLabel(status) {
    if (status === 'pending_review') return 'Awaiting platform review';
    if (status === 'rejected') return 'Rejected — update evidence and resubmit';
    if (status === 'released') return 'Released';
    return 'Not submitted';
  }

  if (!token || forbidden) return null;
  if (loading) {
    return (
      <section style={styles.section} aria-label="Fund release">
        <h2 style={styles.h2}>Manual fund release</h2>
        <p style={{ color: 'var(--color-text-muted)', fontSize: '0.9rem' }}>Loading…</p>
      </section>
    );
  }
  if (!canView) return null;

  return (
    <section style={styles.section} aria-label="Fund release" data-no-print>
      <h2 style={styles.h2}>Manual fund release</h2>
      <p style={styles.intro}>
        Funds leave the campaign wallet only after <strong>you</strong> (creator) and{' '}
        <strong>CrowdPay</strong> (platform) both approve the same transaction. Every step is logged
        for review.
      </p>

      {hasMilestonePlan && (
        <p className="alert alert--info" role="status">
          This campaign uses milestone-based releases. Manual one-shot withdrawal requests are
          disabled; approvals happen through milestone review.
        </p>
      )}

      {hasMilestonePlan && isCreator && (
        <div style={{ display: 'grid', gap: '0.75rem', marginBottom: '1rem' }}>
          {pendingMilestones.map((milestone) => {
            const canSubmit = ['pending', 'rejected'].includes(milestone.status);
            const isPendingReview = milestone.status === 'pending_review';
            return (
              <div key={milestone.id} style={styles.card}>
                <h3 style={styles.h3}>Request milestone release</h3>
                <p style={styles.hint}>
                  {milestone.title} · {Number(milestone.release_percentage).toLocaleString()}% of
                  raised funds
                </p>
                <p
                  style={{ ...styles.hint, fontWeight: 600, color: 'var(--color-text-secondary)' }}
                >
                  Status: {milestoneStatusLabel(milestone.status)}
                </p>
                {milestone.status === 'rejected' && milestone.review_note && (
                  <div className="alert alert--error" style={{ marginBottom: '0.55rem' }}>
                    Rejection reason: {milestone.review_note}
                  </div>
                )}
                {isPendingReview && (
                  <div className="alert alert--info" style={{ marginBottom: '0.55rem' }}>
                    Your evidence is under review. You will be notified when the platform approves
                    or rejects this milestone.
                  </div>
                )}
                {milestone.review_note && milestone.status !== 'rejected' && (
                  <div className="alert alert--info" style={{ marginBottom: '0.55rem' }}>
                    {milestone.review_note}
                  </div>
                )}
                <label className="label-strong" htmlFor={`milestone-evidence-file-${milestone.id}`}>
                  Upload evidence file
                </label>
                <input
                  id={`milestone-evidence-file-${milestone.id}`}
                  type="file"
                  accept="image/*,.pdf,.doc,.docx,.txt"
                  disabled={!canSubmit || uploadingMilestoneId === milestone.id}
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) uploadMilestoneFile(milestone.id, file);
                    e.target.value = '';
                  }}
                  style={{ marginBottom: '0.65rem' }}
                />
                <label className="label-strong" htmlFor={`milestone-evidence-${milestone.id}`}>
                  Evidence URL
                </label>
                <input
                  id={`milestone-evidence-${milestone.id}`}
                  value={milestoneForms[milestone.id]?.evidence_url || ''}
                  onChange={(e) => setMilestoneField(milestone.id, 'evidence_url', e.target.value)}
                  placeholder="https:// or upload a file above"
                  disabled={!canSubmit}
                  style={{ marginBottom: '0.65rem' }}
                />
                <label className="label-strong" htmlFor={`milestone-description-${milestone.id}`}>
                  Evidence description
                </label>
                <textarea
                  id={`milestone-description-${milestone.id}`}
                  value={milestoneForms[milestone.id]?.evidence_description || ''}
                  onChange={(e) =>
                    setMilestoneField(milestone.id, 'evidence_description', e.target.value)
                  }
                  placeholder="Describe what you delivered (demo link summary, deliverable notes, etc.)"
                  rows={3}
                  disabled={!canSubmit}
                  style={{ marginBottom: '0.65rem', resize: 'vertical', fontFamily: 'inherit' }}
                />
                <label className="label-strong" htmlFor={`milestone-destination-${milestone.id}`}>
                  Destination address
                </label>
                <input
                  id={`milestone-destination-${milestone.id}`}
                  value={milestoneForms[milestone.id]?.destination_key || ''}
                  onChange={(e) =>
                    setMilestoneField(milestone.id, 'destination_key', e.target.value)
                  }
                  placeholder="G..."
                  disabled={!canSubmit}
                  style={{ marginBottom: '0.65rem' }}
                />
                <button
                  type="button"
                  className="btn-primary"
                  disabled={
                    !canSubmit ||
                    busyId === `milestone-${milestone.id}` ||
                    uploadingMilestoneId === milestone.id ||
                    milestone.status === 'released'
                  }
                  onClick={() => requestMilestoneRelease(milestone.id)}
                  style={{ width: '100%' }}
                >
                  {busyId === `milestone-${milestone.id}`
                    ? 'Submitting…'
                    : uploadingMilestoneId === milestone.id
                      ? 'Uploading…'
                      : isPendingReview
                        ? 'Awaiting review'
                        : 'Submit evidence for review'}
                </button>
              </div>
            );
          })}
        </div>
      )}

      {!ELIGIBLE.includes(campaign.status) && (
        <p className="alert alert--info" role="status">
          New withdrawal requests are disabled while campaign status is{' '}
          <strong>{campaign.status}</strong>.
        </p>
      )}

      {error && (
        <p className="alert alert--error" role="alert">
          {error}
        </p>
      )}

      {canOpenRequest && (
        <form onSubmit={handleRequest} style={styles.card}>
          <h3 style={styles.h3}>Request a release</h3>
          <p style={styles.hint}>
            Destination must be a valid Stellar public key. Amount is in {campaign.asset_type}.
          </p>
          {liveBalance !== null && (
            <p
              style={{
                fontSize: '0.82rem',
                color: 'var(--color-text-secondary)',
                marginBottom: '0.5rem',
              }}
            >
              Available on-chain:{' '}
              <strong>
                {liveBalance.toLocaleString()} {campaign.asset_type}
              </strong>{' '}
              <button
                type="button"
                style={{
                  fontSize: '0.8rem',
                  color: 'var(--color-accent)',
                  background: 'none',
                  padding: 0,
                  border: 'none',
                  cursor: 'pointer',
                  textDecoration: 'underline',
                }}
                onClick={() => setForm((f) => ({ ...f, amount: String(liveBalance) }))}
              >
                Use max
              </button>
            </p>
          )}
          {loadingBalance && (
            <p
              style={{
                fontSize: '0.82rem',
                color: 'var(--color-text-hint)',
                marginBottom: '0.5rem',
              }}
            >
              Loading balance…
            </p>
          )}
          <label className="label-strong" htmlFor="wd-dest">
            Destination address
          </label>
          <input
            id="wd-dest"
            value={form.destination_key}
            onChange={(e) => setForm((f) => ({ ...f, destination_key: e.target.value }))}
            placeholder="G…"
            required
            style={{ marginBottom: '0.75rem' }}
            autoComplete="off"
          />
          <label className="label-strong" htmlFor="wd-amt">
            Amount ({campaign.asset_type})
          </label>
          <input
            id="wd-amt"
            type="number"
            inputMode="decimal"
            min="0.0000001"
            step="any"
            value={form.amount}
            onChange={(e) => setForm((f) => ({ ...f, amount: e.target.value }))}
            required
            style={{ marginBottom: '0.75rem' }}
          />
          {liveBalance !== null && Number(form.amount) > liveBalance && (
            <p
              className="alert alert--error"
              style={{ fontSize: '0.82rem', marginBottom: '0.75rem' }}
              role="alert"
            >
              Amount exceeds available balance
            </p>
          )}
          <button
            type="submit"
            className="btn-primary"
            disabled={
              busyId === 'new' || (liveBalance !== null && Number(form.amount) > liveBalance)
            }
            style={{ width: '100%' }}
          >
            {liveBalance !== null && Number(form.amount) > liveBalance
              ? 'Amount exceeds balance'
              : busyId === 'new'
                ? 'Submitting…'
                : 'Submit request'}
          </button>
        </form>
      )}

      {isCreator && hasPending && (
        <p className="alert alert--info" style={{ marginTop: '1rem' }} role="status">
          You have a pending release. Complete signatures, cancel before you sign, or wait for
          platform decision.
        </p>
      )}

      <h3 style={{ ...styles.h3, marginTop: '1.5rem' }}>Requests & audit</h3>
      {rows.length === 0 ? (
        <p style={{ color: 'var(--color-text-muted)', fontSize: '0.9rem' }}>
          No withdrawal activity yet.
        </p>
      ) : (
        <ul style={styles.list}>
          {rows.map((row) => (
            <li key={row.id} style={styles.row}>
              <div style={{ minWidth: 0, flex: 1 }}>
                <div style={styles.rowTitle}>
                  {Number(row.amount).toLocaleString()} {campaign.asset_type} →{' '}
                  <code style={styles.code}>
                    {row.destination_key.slice(0, 6)}…{row.destination_key.slice(-4)}
                  </code>
                </div>
                <div style={styles.meta}>{statusLabel(row, expiredIds.has(row.id))}</div>
                {expiredIds.has(row.id) && (
                  <div
                    className="alert alert--warning"
                    style={{ marginTop: '0.5rem', fontSize: '0.8rem' }}
                    role="alert"
                  >
                    This withdrawal XDR has expired. Please cancel this request and submit a new
                    one.
                  </div>
                )}
                {row.denial_reason && (
                  <div
                    className="alert alert--error"
                    style={{ marginTop: '0.5rem', fontSize: '0.8rem' }}
                  >
                    {row.denial_reason}
                  </div>
                )}
                {row.tx_hash && (
                  <a
                    href={stellarExpertTxUrl(row.tx_hash)}
                    target="_blank"
                    rel="noopener noreferrer"
                    style={{ fontSize: '0.82rem', color: 'var(--color-accent)', fontWeight: 600 }}
                  >
                    View transaction
                  </a>
                )}
                {openAudit === row.id && eventsById[row.id] && (
                  <ol style={styles.audit}>
                    {eventsById[row.id].map((ev) => (
                      <li key={ev.id}>
                        <strong>{ev.action}</strong>
                        {ev.note ? ` — ${ev.note}` : ''}
                        <span style={{ color: 'var(--color-text-muted)' }}>
                          {' '}
                          (<RelativeTime date={ev.created_at} />)
                        </span>
                      </li>
                    ))}
                  </ol>
                )}
              </div>

              <div style={styles.actions}>
                <button
                  type="button"
                  className="btn-secondary"
                  onClick={() => loadEvents(row.id)}
                  style={{ fontSize: '0.8rem' }}
                >
                  {openAudit === row.id ? 'Hide audit' : 'Audit trail'}
                </button>

                {/* Creator actions — before signing */}
                {row.status === 'pending' && !row.creator_signed && isCreator && (
                  <>
                    <button
                      type="button"
                      className="btn-secondary"
                      disabled={busyId === row.id}
                      onClick={() =>
                        runAction(
                          row.id,
                          () => api.cancelWithdrawal(row.id, { reason: 'Cancelled by creator' }),
                          'Withdrawal cancelled'
                        )
                      }
                      style={{ fontSize: '0.8rem' }}
                    >
                      Cancel
                    </button>
                    {confirmingSignId === row.id ? (
                      <div style={styles.confirmPanel}>
                        <p style={{ fontSize: '0.82rem', fontWeight: 600, marginBottom: '0.4rem' }}>
                          Confirm release of{' '}
                          <strong>
                            {Number(row.amount).toLocaleString()} {campaign.asset_type}
                          </strong>{' '}
                          to:
                        </p>
                        <code style={{ fontSize: '0.75rem', wordBreak: 'break-all', color: '#555' }}>
                          {row.destination_key}
                        </code>
                        <p style={{ fontSize: '0.78rem', color: '#b45309', marginTop: '0.4rem' }}>
                          This signature cannot be undone.
                        </p>
                        <div style={{ display: 'flex', gap: '0.4rem', marginTop: '0.6rem' }}>
                          <button
                            type="button"
                            className="btn-primary"
                            style={{ fontSize: '0.8rem' }}
                            disabled={busyId === row.id}
                            onClick={() => {
                              setConfirmingSignId(null);
                              if (user?.wallet_type === 'freighter') {
                                signAsFreighter(row.id);
                              } else {
                                runAction(
                                  row.id,
                                  () => api.approveWithdrawalCreator(row.id),
                                  'Withdrawal signed',
                                );
                              }
                            }}
                          >
                            {busyId === row.id ? 'Signing…' : 'Yes, sign now'}
                          </button>
                          <button
                            type="button"
                            className="btn-secondary"
                            style={{ fontSize: '0.8rem' }}
                            onClick={() => setConfirmingSignId(null)}
                          >
                            Go back
                          </button>
                        </div>
                      </div>
                    ) : (
                      <button
                        type="button"
                        className="btn-primary"
                        disabled={busyId === row.id}

                        style={{ fontSize: '0.8rem' }}
                        onClick={() => setConfirmingSignId(row.id)}
                      >
                        {user?.wallet_type === 'freighter' ? 'Sign in Freighter' : 'Sign as creator'}
                      </button>
                    )}
                  </>
                )}

                {/* Platform admin actions — after creator signed */}
                {row.status === 'pending' &&
                  row.creator_signed &&
                  !row.platform_signed &&
                  cap.can_approve_platform &&
                  !expiredIds.has(row.id) && (
                    <>
                      {rejectingId === row.id ? (
                        <div
                          style={{
                            marginTop: '0.5rem',
                            display: 'flex',
                            flexDirection: 'column',
                            gap: '0.4rem',
                            width: '100%',
                          }}
                        >
                          <textarea
                            value={rejectReason}
                            onChange={(e) => setRejectReason(e.target.value)}
                            placeholder="Reason for rejection (saved to audit log)"
                            rows={2}
                            style={{
                              fontSize: '0.85rem',
                              resize: 'vertical',
                              padding: '0.5rem',
                              borderRadius: '6px',
                              border: '1px solid var(--color-border-light)',
                              fontFamily: 'inherit',
                            }}
                            autoFocus
                          />
                          <div style={{ display: 'flex', gap: '0.4rem' }}>
                            <button
                              type="button"
                              className="btn-primary"
                              style={{ fontSize: '0.8rem', flex: 1 }}
                              disabled={busyId === row.id}
                              onClick={() => {
                                runAction(
                                  row.id,
                                  () =>
                                    api.rejectWithdrawal(row.id, {
                                      reason: rejectReason || 'Rejected by platform',
                                    }),
                                  'Withdrawal rejected'
                                );
                                setRejectingId(null);
                                setRejectReason('');
                              }}
                            >
                              Confirm reject
                            </button>
                            <button
                              type="button"
                              className="btn-secondary"
                              style={{ fontSize: '0.8rem', flex: 1 }}
                              onClick={() => {
                                setRejectingId(null);
                                setRejectReason('');
                              }}
                            >
                              Cancel
                            </button>
                          </div>
                        </div>
                      ) : (
                        <>
                          <button
                            type="button"
                            className="btn-secondary"
                            disabled={busyId === row.id}
                            onClick={() => setRejectingId(row.id)}
                            style={{ fontSize: '0.8rem' }}
                          >
                            Reject
                          </button>
                          <button
                            type="button"
                            className="btn-primary"
                            disabled={busyId === row.id}
                            onClick={() =>
                              runAction(
                                row.id,
                                () => api.approveWithdrawalPlatform(row.id),
                                'Withdrawal approved'
                              )
                            }
                            style={{ fontSize: '0.8rem' }}
                          >
                            {busyId === row.id ? 'Approving…' : 'Admin approve & submit'}
                          </button>
                        </>
                      )}
                    </>
                  )}
              </div>
            </li>
          ))}
        </ul>
      )}

      {cap.can_approve_platform && isAdmin && (
        <p style={{ ...styles.hint, marginTop: '1rem' }}>
          Admin actions sign using the platform server key after creator approval. Every transition
          is written to audit history.
        </p>
      )}
    </section>
  );
}

const styles = {
  section: {
    marginTop: '2rem',
    paddingTop: '1.5rem',
    borderTop: '1px solid var(--color-border-light)',
  },
  h2: { fontSize: '1.15rem', fontWeight: 800, marginBottom: '0.5rem' },
  h3: { fontSize: '1rem', fontWeight: 700, marginBottom: '0.5rem' },
  intro: {
    color: 'var(--color-text-secondary)',
    fontSize: '0.9rem',
    lineHeight: 1.55,
    marginBottom: '1rem',
  },
  hint: {
    color: 'var(--color-text-hint)',
    fontSize: '0.82rem',
    lineHeight: 1.45,
    marginBottom: '0.65rem',
  },
  card: {
    background: 'var(--color-bg)',
    border: '1px solid var(--color-border-light)',
    borderRadius: '10px',
    padding: '1.1rem',
    display: 'flex',
    flexDirection: 'column',
    gap: '0.25rem',
  },
  list: {
    listStyle: 'none',
    display: 'flex',
    flexDirection: 'column',
    gap: '0.75rem',
    margin: 0,
    padding: 0,
  },
  row: {
    display: 'flex',
    flexDirection: 'column',
    gap: '0.65rem',
    background: 'var(--color-bg)',
    border: '1px solid var(--color-border-lighter)',
    borderRadius: '10px',
    padding: '0.85rem 1rem',
  },
  rowTitle: { fontSize: '0.9rem', fontWeight: 600, color: 'var(--color-text-primary)' },
  meta: { fontSize: '0.8rem', color: 'var(--color-text-hint)' },
  code: { fontSize: '0.78rem' },
  actions: { display: 'flex', flexWrap: 'wrap', gap: '0.45rem', alignItems: 'center' },
  audit: {
    marginTop: '0.5rem',
    paddingLeft: '1.1rem',
    fontSize: '0.78rem',
    color: 'var(--color-text-secondary)',
    lineHeight: 1.5,
  },
};

import React, { useState } from 'react';

export default function CampaignForm({ initialData = {}, onSubmit }) {
  const [deadline, setDeadline] = useState(initialData.deadline ? initialData.deadline.slice(0, 16) : '');
  const [title, setTitle] = useState(initialData.title || '');
  const [targetAmount, setTargetAmount] = useState(initialData.target_amount || '');

  const tomorrow = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString().slice(0, 16);

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit({ title, target_amount: targetAmount, deadline: deadline ? new Date(deadline).toISOString() : null });
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label>Title</label>
        <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} required />
      </div>
      <div>
        <label>Target Amount</label>
        <input type="number" value={targetAmount} onChange={(e) => setTargetAmount(e.target.value)} required />
      </div>
      <div>
        <label>Deadline</label>
        <input
          type="datetime-local"
          min={tomorrow}
          value={deadline}
          onChange={(e) => setDeadline(e.target.value)}
          required
        />
      </div>
      <button type="submit">Save Campaign</button>
    </form>
  );
}

import React, { useEffect, useState } from 'react';
import DOMPurify from 'dompurify';

/**
 * ImpactReportDisplay — Shows published impact report on campaign page.
 * Prominently displayed post-completion.
 * Includes: report content, image gallery, milestone list, share buttons.
 * Has impact badge showing the creator published a report.
 */
export function ImpactReportDisplay({ report, campaignTitle }) {
  if (!report) {
    return null;
  }

  function escapeHtml(text) {
    return text
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&#39;');
  }

  function markdownToHtml(markdown) {
    const escaped = escapeHtml(markdown || '');
    return escaped
      .replace(/^### (.*)$/gm, '<h3>$1</h3>')
      .replace(/^## (.*)$/gm, '<h2>$1</h2>')
      .replace(/^# (.*)$/gm, '<h1>$1</h1>')
      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.*?)\*/g, '<em>$1</em>')
      .replace(
        /\[(.*?)\]\((https?:\/\/[^\s)]+)\)/g,
        '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>'
      )
      .replace(/\n/g, '<br />');
  }

  const htmlContent = markdownToHtml(report.content);

  return (
    <section
      aria-labelledby="impact-report-heading"
      style={{
        marginTop: '2rem',
        padding: '1.5rem',
        backgroundColor: 'var(--color-bg-alt)',
        border: '2px solid var(--color-accent-light)',
        borderRadius: '0.75rem',
      }}
      id="impact-report"
    >
      {/* Impact Badge */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '0.5rem',
          marginBottom: '1rem',
        }}
      >
        <span style={{ fontSize: '1.5rem' }} aria-hidden="true">
          🏆
        </span>
        <span
          style={{
            fontSize: '0.85rem',
            fontWeight: '600',
            color: 'var(--color-accent)',
            textTransform: 'uppercase',
            letterSpacing: '0.5px',
          }}
        >
          Impact Report Published
        </span>
      </div>

      {/* Report Title */}
      <h2
        id="impact-report-heading"
        style={{
          fontSize: '1.5rem',
          marginBottom: '0.5rem',
          color: 'var(--color-text)',
        }}
      >
        {report.title}
      </h2>

      {/* Report Summary */}
      {report.summary && (
        <p
          style={{
            fontSize: '0.95rem',
            color: 'var(--color-text-hint)',
            marginBottom: '1.5rem',
            fontStyle: 'italic',
          }}
        >
          {report.summary}
        </p>
      )}

      {/* Published Date */}
      <p
        style={{
          fontSize: '0.85rem',
          color: 'var(--color-text-hint)',
          marginBottom: '1.5rem',
        }}
      >
        Published on {new Date(report.publishedAt).toLocaleDateString('en-US', { 
          year: 'numeric', 
          month: 'long', 
          day: 'numeric' 
        })}
      </p>

      {/* Rendered Markdown Content */}
      <div
        dangerouslySetInnerHTML={{
          __html: DOMPurify.sanitize(htmlContent),
        }}
        style={{
          lineHeight: 1.7,
          color: 'var(--color-text)',
          marginBottom: '2rem',
        }}
      />

      {/* Image Gallery */}
      {report.images && report.images.length > 0 && (
        <div style={{ marginBottom: '2rem' }}>
          <h3 style={{ fontSize: '1.1rem', marginBottom: '1rem' }}>📸 Gallery</h3>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))',
              gap: '1rem',
            }}
          >
            {report.images
              .sort((a, b) => (a.order ?? 0) - (b.order ?? 0))
              .map((img, idx) => (
                <figure
                  key={idx}
                  style={{
                    margin: 0,
                    overflow: 'hidden',
                    borderRadius: '0.5rem',
                  }}
                >
                  <img
                    src={img.url}
                    alt={img.caption || `Impact report image ${idx + 1}`}
                    style={{
                      width: '100%',
                      height: '200px',
                      objectFit: 'cover',
                      display: 'block',
                    }}
                  />
                  {img.caption && (
                    <figcaption
                      style={{
                        padding: '0.5rem',
                        backgroundColor: 'white',
                        fontSize: '0.85rem',
                        color: 'var(--color-text-hint)',
                        textAlign: 'center',
                      }}
                    >
                      {img.caption}
                    </figcaption>
                  )}
                </figure>
              ))}
          </div>
        </div>
      )}

      {/* Videos */}
      {report.videos && report.videos.length > 0 && (
        <div style={{ marginBottom: '2rem' }}>
          <h3 style={{ fontSize: '1.1rem', marginBottom: '1rem' }}>🎬 Videos</h3>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
              gap: '1rem',
            }}
          >
            {report.videos.map((video, idx) => (
              <div
                key={idx}
                style={{
                  borderRadius: '0.5rem',
                  overflow: 'hidden',
                  backgroundColor: '#000',
                }}
              >
                {video.thumbnail && (
                  <a href={video.url} target="_blank" rel="noopener noreferrer" style={{ display: 'block' }}>
                    <img
                      src={video.thumbnail}
                      alt={video.title || `Video ${idx + 1}`}
                      style={{
                        width: '100%',
                        height: '200px',
                        objectFit: 'cover',
                        display: 'block',
                      }}
                    />
                    <div
                      style={{
                        position: 'absolute',
                        top: '50%',
                        left: '50%',
                        transform: 'translate(-50%, -50%)',
                        color: 'white',
                        fontSize: '3rem',
                        opacity: 0.8,
                      }}
                    >
                      ▶️
                    </div>
                  </a>
                )}
                {video.title && (
                  <div
                    style={{
                      padding: '0.75rem',
                      backgroundColor: 'white',
                      fontSize: '0.9rem',
                      fontWeight: '500',
                    }}
                  >
                    <a
                      href={video.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      style={{
                        color: 'var(--color-accent)',
                        textDecoration: 'none',
                      }}
                    >
                      {video.title} →
                    </a>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Milestones List */}
      {report.milestones && report.milestones.length > 0 && (
        <div
          style={{
            padding: '1.5rem',
            backgroundColor: 'white',
            borderRadius: '0.5rem',
            marginBottom: '1rem',
          }}
        >
          <h3 style={{ fontSize: '1.1rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <span>🎯</span> Milestones Achieved
          </h3>
          <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
            {report.milestones.map((milestone, idx) => (
              <li
                key={idx}
                style={{
                  padding: '1rem',
                  borderLeft: '4px solid var(--color-accent)',
                  backgroundColor: 'var(--color-bg-alt)',
                  marginBottom: idx < report.milestones.length - 1 ? '0.75rem' : 0,
                  borderRadius: '0.25rem',
                }}
              >
                <div style={{ fontWeight: '600', color: 'var(--color-text)', marginBottom: '0.25rem' }}>
                  ✓ {milestone.title}
                </div>
                {milestone.description && (
                  <div style={{ fontSize: '0.9rem', color: 'var(--color-text-hint)' }}>
                    {milestone.description}
                  </div>
                )}
                {milestone.achievedAt && (
                  <div style={{ fontSize: '0.8rem', color: 'var(--color-text-hint)', marginTop: '0.25rem' }}>
                    Achieved on {new Date(milestone.achievedAt).toLocaleDateString()}
                  </div>
                )}
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Share Buttons */}
      <div
        style={{
          display: 'flex',
          gap: '1rem',
          marginTop: '1.5rem',
          padding: '1rem 0',
          borderTop: '1px solid var(--color-border)',
        }}
      >
        <span style={{ fontSize: '0.85rem', fontWeight: '500', display: 'flex', alignItems: 'center' }}>
          Share this report:
        </span>
        <a
          href={`https://twitter.com/intent/tweet?text=Check out the impact report from ${campaignTitle}: ${window.location.href}%23impact-report&via=CrowdPay`}
          target="_blank"
          rel="noopener noreferrer"
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: '0.35rem',
            padding: '0.4rem 0.75rem',
            backgroundColor: '#1DA1F2',
            color: 'white',
            textDecoration: 'none',
            borderRadius: '0.35rem',
            fontSize: '0.85rem',
            fontWeight: '500',
          }}
        >
          𝕏
        </a>
        <a
          href={`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(window.location.href)}`}
          target="_blank"
          rel="noopener noreferrer"
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: '0.35rem',
            padding: '0.4rem 0.75rem',
            backgroundColor: '#1877F2',
            color: 'white',
            textDecoration: 'none',
            borderRadius: '0.35rem',
            fontSize: '0.85rem',
            fontWeight: '500',
          }}
        >
          f
        </a>
        <a
          href={`https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(window.location.href)}`}
          target="_blank"
          rel="noopener noreferrer"
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: '0.35rem',
            padding: '0.4rem 0.75rem',
            backgroundColor: '#0A66C2',
            color: 'white',
            textDecoration: 'none',
            borderRadius: '0.35rem',
            fontSize: '0.85rem',
            fontWeight: '500',
          }}
        >
          in
        </a>
      </div>

      {/* View Count */}
      <div style={{ marginTop: '1rem', fontSize: '0.8rem', color: 'var(--color-text-hint)' }}>
        {report.viewsCount} {report.viewsCount === 1 ? 'view' : 'views'}
      </div>
    </section>
  );
}

export default ImpactReportDisplay;

import React, { useState, useEffect, useCallback } from 'react';
import SimpleMDEEditor from 'react-simplemde-editor';
import DOMPurify from 'dompurify';
import 'easymde/dist/easymde.min.css';
import { api } from '../../services/api';
import { useToast } from '../../context/ToastContext';

/**
 * ImpactReportEditor — Rich content editor for campaign creators.
 * Allows writing markdown content, uploading images, adding video links,
 * and marking milestones achieved.
 *
 * Only visible to campaign creator on completed campaigns.
 * Renders a preview mode before publishing.
 */
export function ImpactReportEditor({ campaignId, existingReport, onPublished }) {
  const [tab, setTab] = useState('write');
  const [content, setContent] = useState(existingReport?.content ?? '');
  const [title, setTitle] = useState(existingReport?.title ?? '');
  const [summary, setSummary] = useState(existingReport?.summary ?? '');
  const [milestones, setMilestones] = useState(existingReport?.milestones ?? []);
  const [newMilestone, setNewMilestone] = useState({ title: '', description: '' });
  const [isSaving, setIsSaving] = useState(false);
  const [isPublishing, setIsPublishing] = useState(false);
  const [lastSaved, setLastSaved] = useState(existingReport?.updatedAt ?? null);
  const [showPublishConfirm, setShowPublishConfirm] = useState(false);
  const { showToast } = useToast();

  // Auto-save draft every 30 seconds
  useEffect(() => {
    const timer = setInterval(() => {
      if (title || content) {
        saveDraft();
      }
    }, 30000);

    return () => clearInterval(timer);
  }, [title, content, summary, milestones]);

  async function saveDraft() {
    if (!title && !content) return;

    setIsSaving(true);
    try {
      if (existingReport?.id) {
        // Update existing draft
        await api.put(`/campaigns/${campaignId}/impact-report`, {
          title,
          content,
          summary,
          milestones,
        });
      } else {
        // Create new draft
        const response = await api.post(`/campaigns/${campaignId}/impact-report`, {
          title,
          content,
          summary,
          milestones,
        });
        // Update local state with new report ID
        if (!existingReport) {
          existingReport = { id: response.id };
        }
      }
      setLastSaved(new Date());
      showToast('Draft saved', 'success');
    } catch (error) {
      console.error('Failed to save draft:', error);
      showToast('Failed to save draft', 'error');
    } finally {
      setIsSaving(false);
    }
  }

  const handleAddMilestone = () => {
    if (newMilestone.title.trim()) {
      setMilestones([
        ...milestones,
        {
          title: newMilestone.title,
          description: newMilestone.description,
          achievedAt: new Date().toISOString(),
        },
      ]);
      setNewMilestone({ title: '', description: '' });
    }
  };

  const handleRemoveMilestone = (index) => {
    setMilestones(milestones.filter((_, i) => i !== index));
  };

  async function handlePublish() {
    if (!title || !content) {
      showToast('Title and content are required', 'error');
      return;
    }

    // Save draft first
    await saveDraft();

    setIsPublishing(true);
    try {
      await api.post(`/campaigns/${campaignId}/impact-report/publish`);
      showToast('Impact report published successfully!', 'success');
      setShowPublishConfirm(false);
      if (onPublished) {
        onPublished();
      }
    } catch (error) {
      console.error('Failed to publish report:', error);
      showToast('Failed to publish report', 'error');
    } finally {
      setIsPublishing(false);
    }
  }

  function escapeHtml(text) {
    return text
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&#39;');
  }

  function markdownToHtml(markdown) {
    const escaped = escapeHtml(markdown || '');
    return escaped
      .replace(/^### (.*)$/gm, '<h3>$1</h3>')
      .replace(/^## (.*)$/gm, '<h2>$1</h2>')
      .replace(/^# (.*)$/gm, '<h1>$1</h1>')
      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.*?)\*/g, '<em>$1</em>')
      .replace(
        /\[(.*?)\]\((https?:\/\/[^\s)]+)\)/g,
        '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>'
      )
      .replace(/\n/g, '<br />');
  }

  const htmlContent = markdownToHtml(content);

  return (
    <div style={{ marginTop: '2rem' }}>
      <h2>Create Impact Report</h2>

      {/* Tabs */}
      <div style={{ display: 'flex', gap: '1rem', borderBottom: '1px solid var(--color-border)' }}>
        <button
          type="button"
          onClick={() => setTab('write')}
          style={{
            background: 'none',
            border: 'none',
            padding: '0.75rem 1rem',
            fontSize: '0.95rem',
            fontWeight: tab === 'write' ? 'bold' : 'normal',
            color: tab === 'write' ? 'var(--color-accent)' : 'var(--color-text-hint)',
            cursor: 'pointer',
            borderBottom: tab === 'write' ? '2px solid var(--color-accent)' : 'transparent',
          }}
        >
          ✏️ Write
        </button>
        <button
          type="button"
          onClick={() => setTab('preview')}
          style={{
            background: 'none',
            border: 'none',
            padding: '0.75rem 1rem',
            fontSize: '0.95rem',
            fontWeight: tab === 'preview' ? 'bold' : 'normal',
            color: tab === 'preview' ? 'var(--color-accent)' : 'var(--color-text-hint)',
            cursor: 'pointer',
            borderBottom: tab === 'preview' ? '2px solid var(--color-accent)' : 'transparent',
          }}
        >
          👁️ Preview
        </button>
      </div>

      {/* Write Tab */}
      {tab === 'write' && (
        <div style={{ marginTop: '1.5rem' }}>
          <div style={{ marginBottom: '1.5rem' }}>
            <label htmlFor="report-title" style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 'bold' }}>
              Report Title
            </label>
            <input
              id="report-title"
              type="text"
              placeholder="e.g., Campaign Impact Summary 2026"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              maxLength="255"
              style={{
                width: '100%',
                padding: '0.75rem',
                border: '1px solid var(--color-border)',
                borderRadius: '0.5rem',
                fontSize: '1rem',
              }}
            />
          </div>

          <div style={{ marginBottom: '1.5rem' }}>
            <label htmlFor="report-summary" style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 'bold' }}>
              Summary (Optional)
            </label>
            <textarea
              id="report-summary"
              placeholder="Short summary for notifications (max 500 chars)"
              value={summary}
              onChange={(e) => setSummary(e.target.value)}
              maxLength="500"
              rows="2"
              style={{
                width: '100%',
                padding: '0.75rem',
                border: '1px solid var(--color-border)',
                borderRadius: '0.5rem',
                fontSize: '1rem',
                fontFamily: 'inherit',
              }}
            />
          </div>

          <div style={{ marginBottom: '1.5rem' }}>
            <label htmlFor="report-content" style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 'bold' }}>
              Report Content
            </label>
            <SimpleMDEEditor
              value={content}
              onChange={(val) => setContent(val)}
              options={{
                spellChecker: false,
                toolbar: [
                  'bold', 'italic', 'heading', '|',
                  'quote', 'unordered-list', 'ordered-list', '|',
                  'link', '|',
                  'preview', 'side-by-side', 'fullscreen', '|',
                  'guide'
                ],
              }}
            />
          </div>

          {/* Milestones Section */}
          <div style={{ marginBottom: '1.5rem', padding: '1rem', backgroundColor: 'var(--color-bg-alt)', borderRadius: '0.5rem' }}>
            <h3>Milestones Achieved</h3>
            <p style={{ color: 'var(--color-text-hint)', fontSize: '0.9rem' }}>
              Track key achievements and milestones reached during the campaign.
            </p>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '1rem', marginBottom: '1rem' }}>
              <input
                type="text"
                placeholder="Milestone title"
                value={newMilestone.title}
                onChange={(e) => setNewMilestone({ ...newMilestone, title: e.target.value })}
                style={{
                  padding: '0.75rem',
                  border: '1px solid var(--color-border)',
                  borderRadius: '0.5rem',
                }}
              />
              <textarea
                placeholder="Description"
                value={newMilestone.description}
                onChange={(e) => setNewMilestone({ ...newMilestone, description: e.target.value })}
                rows="2"
                style={{
                  padding: '0.75rem',
                  border: '1px solid var(--color-border)',
                  borderRadius: '0.5rem',
                  fontFamily: 'inherit',
                }}
              />
              <button
                type="button"
                onClick={handleAddMilestone}
                style={{
                  padding: '0.75rem',
                  backgroundColor: 'var(--color-accent)',
                  color: 'white',
                  border: 'none',
                  borderRadius: '0.5rem',
                  cursor: 'pointer',
                  fontWeight: 'bold',
                }}
              >
                Add Milestone
              </button>
            </div>

            {milestones.length > 0 && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                {milestones.map((m, idx) => (
                  <div
                    key={idx}
                    style={{
                      padding: '0.75rem',
                      backgroundColor: 'white',
                      border: '1px solid var(--color-border)',
                      borderRadius: '0.5rem',
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'start',
                    }}
                  >
                    <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 'bold' }}>{m.title}</div>
                      <div style={{ fontSize: '0.9rem', color: 'var(--color-text-hint)' }}>{m.description}</div>
                    </div>
                    <button
                      type="button"
                      onClick={() => handleRemoveMilestone(idx)}
                      style={{
                        background: 'none',
                        border: 'none',
                        color: 'var(--color-error)',
                        cursor: 'pointer',
                        fontSize: '1.1rem',
                        padding: '0.5rem',
                      }}
                      title="Remove milestone"
                    >
                      ✕
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Save & Publish Buttons */}
          <div style={{ display: 'flex', gap: '1rem', alignItems: 'center', marginTop: '2rem' }}>
            <button
              type="button"
              onClick={saveDraft}
              disabled={isSaving}
              style={{
                padding: '0.75rem 1.5rem',
                backgroundColor: 'var(--color-border)',
                color: 'var(--color-text)',
                border: 'none',
                borderRadius: '0.5rem',
                cursor: isSaving ? 'not-allowed' : 'pointer',
                opacity: isSaving ? 0.6 : 1,
              }}
            >
              {isSaving ? 'Saving...' : 'Save Draft'}
            </button>

            <button
              type="button"
              onClick={() => setShowPublishConfirm(true)}
              disabled={isPublishing || !title || !content}
              style={{
                padding: '0.75rem 1.5rem',
                backgroundColor: 'var(--color-accent)',
                color: 'white',
                border: 'none',
                borderRadius: '0.5rem',
                cursor: 'pointer',
                opacity: isPublishing || !title || !content ? 0.6 : 1,
                fontWeight: 'bold',
              }}
            >
              {isPublishing ? 'Publishing...' : '🚀 Publish & Notify Contributors'}
            </button>

            {lastSaved && (
              <span style={{ fontSize: '0.85rem', color: 'var(--color-text-hint)' }}>
                Last saved: {new Date(lastSaved).toLocaleTimeString()}
              </span>
            )}
          </div>
        </div>
      )}

      {/* Preview Tab */}
      {tab === 'preview' && (
        <div style={{ marginTop: '1.5rem' }}>
          <div style={{ marginBottom: '2rem' }}>
            <h2>{title || '(No title)'}</h2>
            {summary && (
              <p style={{ fontSize: '0.95rem', color: 'var(--color-text-hint)', marginBottom: '1rem' }}>
                <em>{summary}</em>
              </p>
            )}
            <div
              dangerouslySetInnerHTML={{
                __html: DOMPurify.sanitize(htmlContent),
              }}
              style={{
                lineHeight: 1.6,
                color: 'var(--color-text)',
                marginBottom: '2rem',
              }}
            />
          </div>

          {milestones.length > 0 && (
            <div
              style={{
                padding: '1.5rem',
                backgroundColor: 'var(--color-bg-alt)',
                borderRadius: '0.5rem',
                marginBottom: '2rem',
              }}
            >
              <h3>Milestones Achieved 🎯</h3>
              <ul style={{ listStyle: 'none', padding: 0 }}>
                {milestones.map((m, idx) => (
                  <li
                    key={idx}
                    style={{
                      padding: '0.75rem 0',
                      borderBottom: idx < milestones.length - 1 ? '1px solid var(--color-border)' : 'none',
                    }}
                  >
                    <strong>{m.title}</strong>
                    <p style={{ margin: '0.25rem 0 0 0', color: 'var(--color-text-hint)', fontSize: '0.9rem' }}>
                      {m.description}
                    </p>
                  </li>
                ))}
              </ul>
            </div>
          )}

          <div style={{ display: 'flex', gap: '1rem' }}>
            <button
              type="button"
              onClick={() => setTab('write')}
              style={{
                padding: '0.75rem 1.5rem',
                backgroundColor: 'var(--color-border)',
                color: 'var(--color-text)',
                border: 'none',
                borderRadius: '0.5rem',
                cursor: 'pointer',
              }}
            >
              ← Back to Edit
            </button>

            <button
              type="button"
              onClick={() => setShowPublishConfirm(true)}
              disabled={isPublishing || !title || !content}
              style={{
                padding: '0.75rem 1.5rem',
                backgroundColor: 'var(--color-accent)',
                color: 'white',
                border: 'none',
                borderRadius: '0.5rem',
                cursor: 'pointer',
                opacity: isPublishing || !title || !content ? 0.6 : 1,
                fontWeight: 'bold',
              }}
            >
              {isPublishing ? 'Publishing...' : '🚀 Publish & Notify Contributors'}
            </button>
          </div>
        </div>
      )}

      {/* Publish Confirmation Modal */}
      {showPublishConfirm && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000,
          }}
        >
          <div
            style={{
              backgroundColor: 'white',
              padding: '2rem',
              borderRadius: '0.75rem',
              maxWidth: '500px',
              boxShadow: '0 10px 40px rgba(0, 0, 0, 0.2)',
            }}
          >
            <h3>Publish Impact Report?</h3>
            <p>
              Once published, all contributors to this campaign will be notified about your impact report.
              You can still update the draft before publishing.
            </p>

            <p style={{ fontSize: '0.9rem', color: 'var(--color-text-hint)' }}>
              <strong>Title:</strong> {title}
            </p>

            <div style={{ display: 'flex', gap: '1rem', marginTop: '1.5rem', justifyContent: 'flex-end' }}>
              <button
                type="button"
                onClick={() => setShowPublishConfirm(false)}
                style={{
                  padding: '0.75rem 1.5rem',
                  backgroundColor: 'var(--color-border)',
                  color: 'var(--color-text)',
                  border: 'none',
                  borderRadius: '0.5rem',
                  cursor: 'pointer',
                }}
              >
                Cancel
              </button>

              <button
                type="button"
                onClick={handlePublish}
                disabled={isPublishing}
                style={{
                  padding: '0.75rem 1.5rem',
                  backgroundColor: 'var(--color-accent)',
                  color: 'white',
                  border: 'none',
                  borderRadius: '0.5rem',
                  cursor: isPublishing ? 'not-allowed' : 'pointer',
                  opacity: isPublishing ? 0.6 : 1,
                  fontWeight: 'bold',
                }}
              >
                {isPublishing ? 'Publishing...' : '🚀 Publish & Notify'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default ImpactReportEditor;

import React, { useEffect, useState, useCallback } from 'react';
import { api } from '../../services/api';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
} from 'recharts';

export default function VelocityWidget({ campaignId }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [viewMode, setViewMode] = useState('7d');
  const [thresholdInput, setThresholdInput] = useState('');
  const [savingThreshold, setSavingThreshold] = useState(false);

  const fetchVelocity = useCallback(async () => {
    try {
      const res = await api.getCampaignVelocity(campaignId);
      setData(res);
      if (res?.alerts?.threshold !== undefined) {
        setThresholdInput(res.alerts.threshold);
      }
    } catch (err) {
      setError(err.message || 'Failed to load contribution velocity');
    } finally {
      setLoading(false);
    }
  }, [campaignId]);

  useEffect(() => {
    if (!campaignId) return;
    fetchVelocity();
    const interval = setInterval(fetchVelocity, 5 * 60 * 1000);
    return () => clearInterval(interval);
  }, [campaignId, fetchVelocity]);

  const handleSaveThreshold = async (e) => {
    e.preventDefault();
    setSavingThreshold(true);
    try {
      const res = await api.updateVelocityThreshold(campaignId, Number(thresholdInput));
      setData(prev => ({
        ...prev,
        alerts: {
          ...prev.alerts,
          threshold: res.threshold,
          is_below_threshold: prev.velocity.amount_per_hour < res.threshold,
        },
      }));
    } catch (err) {
      setError(err.message || 'Failed to update alert threshold');
    } finally {
      setSavingThreshold(false);
    }
  };

  if (loading && !data) return <div className="campaign-card">Loading velocity widget…</div>;
  if (error && !data) return <div className="campaign-card" style={{ color: 'var(--color-danger)' }}>{error}</div>;

  const velocity = data?.velocity || {};
  const projected = data?.projected_completion_date;
  const comparison = data?.category_comparison || {};
  const alerts = data?.alerts || {};
  const trends = data?.trends || {};
  const chartData = viewMode === '7d' ? trends.view_7d || [] : trends.view_30d || [];

  return (
    <div className="campaign-card" style={{ display: 'grid', gap: '1rem', padding: '1.25rem' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '0.5rem' }}>
        <h3 style={{ margin: 0, fontSize: '1.15rem' }}>Contribution Velocity & Funding Pace</h3>
        <span style={{ fontSize: '0.75rem', color: 'var(--color-text-hint)' }}>Refreshes every 5m</span>
      </div>

      {alerts.is_below_threshold && (
        <div style={{ background: 'rgba(239, 68, 68, 0.1)', border: '1px solid var(--color-danger)', padding: '0.75rem', borderRadius: '6px', color: 'var(--color-danger)', fontSize: '0.85rem' }}>
          ⚠️ <strong>Velocity Alert:</strong> Current hourly velocity ({velocity.amount_per_hour}/hr) has dropped below your configured threshold ({alerts.threshold}/hr).
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(130px, 1fr))', gap: '0.75rem' }}>
        <div style={{ background: 'var(--color-bg-subtle)', padding: '0.75rem', borderRadius: '6px' }}>
          <div style={{ fontSize: '0.75rem', color: 'var(--color-text-hint)' }}>Velocity (Hourly)</div>
          <div style={{ fontSize: '1.1rem', fontWeight: 700 }}>{velocity.amount_per_hour || 0} /hr</div>
        </div>
        <div style={{ background: 'var(--color-bg-subtle)', padding: '0.75rem', borderRadius: '6px' }}>
          <div style={{ fontSize: '0.75rem', color: 'var(--color-text-hint)' }}>Velocity (Daily)</div>
          <div style={{ fontSize: '1.1rem', fontWeight: 700 }}>{velocity.amount_per_day || 0} /day</div>
        </div>
        <div style={{ background: 'var(--color-bg-subtle)', padding: '0.75rem', borderRadius: '6px' }}>
          <div style={{ fontSize: '0.75rem', color: 'var(--color-text-hint)' }}>Projected Completion</div>
          <div style={{ fontSize: '0.95rem', fontWeight: 700 }}>
            {projected ? new Date(projected).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) : 'N/A'}
          </div>
        </div>
        <div style={{ background: 'var(--color-bg-subtle)', padding: '0.75rem', borderRadius: '6px' }}>
          <div style={{ fontSize: '0.75rem', color: 'var(--color-text-hint)' }}>Category Avg (Weekly)</div>
          <div style={{ fontSize: '1.1rem', fontWeight: 700 }}>{comparison.category_avg_weekly || 0}</div>
        </div>
      </div>

      <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
          <span style={{ fontSize: '0.9rem', fontWeight: 600 }}>Velocity Trend</span>
          <div style={{ display: 'flex', gap: '0.25rem' }}>
            <button
              type="button"
              className={viewMode === '7d' ? 'btn-primary' : 'btn-secondary'}
              style={{ padding: '0.2rem 0.5rem', fontSize: '0.75rem' }}
              onClick={() => setViewMode('7d')}
            >
              7 Days
            </button>
            <button
              type="button"
              className={viewMode === '30d' ? 'btn-primary' : 'btn-secondary'}
              style={{ padding: '0.2rem 0.5rem', fontSize: '0.75rem' }}
              onClick={() => setViewMode('30d')}
            >
              30 Days
            </button>
          </div>
        </div>
        <div style={{ width: '100%', height: '180px' }}>
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chartData} margin={{ top: 5, right: 10, left: -20, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="var(--color-border)" />
              <XAxis dataKey="date" tick={{ fontSize: 10 }} />
              <YAxis tick={{ fontSize: 10 }} />
              <Tooltip />
              <Line type="monotone" dataKey="amount" stroke="#7c3aed" strokeWidth={2} dot={false} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      <form onSubmit={handleSaveThreshold} style={{ display: 'flex', gap: '0.5rem', alignItems: 'center', flexWrap: 'wrap', marginTop: '0.5rem', borderTop: '1px solid var(--color-border)', paddingTop: '0.75rem' }}>
        <label htmlFor="velocity-threshold" style={{ fontSize: '0.8rem', flex: '1 1 180px' }}>
          Alert when hourly velocity drops below:
        </label>
        <input
          id="velocity-threshold"
          type="number"
          min="0"
          step="any"
          value={thresholdInput}
