import { createContext, useContext, useState, useCallback, useEffect } from 'react';
import * as Sentry from '@sentry/react';
import { api } from '../services/api';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [ready, setReady] = useState(false);

  const refreshUser = useCallback(async () => {
    const userData = await api.getMe();
    if (userData && userData.id) {
      setUser(userData);
    } else {
      setUser(null);
    }
    return userData;
  }, []);

  useEffect(() => {
    let active = true;

    async function validateAndRefreshUser() {
      // Check if user has a valid session (token is in httpOnly cookie)
      try {
        // Always fetch fresh user data from server — never trust client-stored role/admin flags
        const userData = await api.getMe();
        if (!active) return;
        if (userData && userData.id) {
          setUser(userData);
        } else {
          setUser(null);
        }
      } catch (err) {
        if (!active) return;
        // If token is invalid, expired, or user was deleted, log out
        if (err.status === 401 || err.status === 404) {
          setUser(null);
        }
      } finally {
        if (active) {
          setReady(true);
        }
      }
    }

    validateAndRefreshUser();

    return () => {
      active = false;
    };
  }, []);

  const login = useCallback(async (userData) => {
    setUser(userData);
    Sentry.setUser({ id: userData.id, email: userData.email, role: userData.role });
    setReady(true);
  }, []);

  const logout = useCallback(async () => {
    try {
      await api.logout();
    } catch (_err) {
      /* ignore */
    }
    setUser(null);
    Sentry.setUser(null);
    setReady(true);
  }, []);

  const updateUser = useCallback((userData) => {
    setUser(userData);
  }, []);

  const exitImpersonation = useCallback(async () => {
    await api.adminExitImpersonation();
    return refreshUser();
  }, [refreshUser]);

  return (
    <AuthContext.Provider
      value={{ user, ready, login, logout, updateUser, refreshUser, exitImpersonation }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);

import { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react';
import { retryQueuedRequests } from '../services/api';

const NetworkStatusContext = createContext({ isOnline: true });

export function NetworkStatusProvider({ children }) {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const wasOfflineRef = useRef(false);

  const handleOnline = useCallback(() => {
    setIsOnline(true);
    if (wasOfflineRef.current) {
      wasOfflineRef.current = false;
      retryQueuedRequests();
    }
  }, []);

  const handleOffline = useCallback(() => {
    setIsOnline(false);
    wasOfflineRef.current = true;
  }, []);

  useEffect(() => {
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [handleOnline, handleOffline]);

  return (
    <NetworkStatusContext.Provider value={{ isOnline }}>
      {children}
    </NetworkStatusContext.Provider>
  );
}

export const useNetworkStatus = () => useContext(NetworkStatusContext);

import { createContext, useContext, useEffect, useState } from 'react';

const ThemeContext = createContext();

export function ThemeProvider({ children }) {
  const [dark, setDark] = useState(() => {
    // Check localStorage first
    const saved = localStorage.getItem('theme');
    if (saved) {
      return saved === 'dark';
    }
    // Fall back to system preference
    return window.matchMedia('(prefers-color-scheme: dark)').matches;
  });

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', dark ? 'dark' : 'light');
    localStorage.setItem('theme', dark ? 'dark' : 'light');
  }, [dark]);

  const toggleTheme = () => setDark((prev) => !prev);

  return <ThemeContext.Provider value={{ dark, toggleTheme }}>{children}</ThemeContext.Provider>;
}

export function useTheme() {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
}

