  useEffect(() => {
    if (!window.EventSource) return;

    let es = null;
    let retryDelay = 1000;
    let retryTimeout = null;
    let isUnmounted = false;

    function connect() {
      if (isUnmounted) return;

      es = new EventSource(`/api/campaigns/${id}/stream`);

      es.onopen = () => {
        setIsLive(true);
        retryDelay = 1000;
      };

      es.onmessage = (e) => {
        let msg;
        try {
          msg = JSON.parse(e.data);
        } catch {
          return;
        }

        if (msg.type === 'contribution') {
          setCampaign((prev) => (prev ? { ...prev, raised_amount: msg.raised_amount } : prev));
          setContributions((prev) => {
            const current = prev || [];
            const exists = current.some((c) => c.tx_hash === msg.contribution.tx_hash);
            if (exists) return current;

            setTotalContributions((t) => t + 1);

            const updated = [msg.contribution, ...current];
            if (!showAll && updated.length > 10) {
              return updated.slice(0, 10);
            }
            return updated;
          });
        }
      };

      es.onerror = () => {
        setIsLive(false);
        es.close();

        if (!isUnmounted) {
          retryTimeout = setTimeout(() => {
            connect();
            retryDelay = Math.min(retryDelay * 2, 30000);
          }, retryDelay);
        }
      };
    }

    connect();

    return () => {
      isUnmounted = true;
      if (es) es.close();
      if (retryTimeout) clearTimeout(retryTimeout);
      setIsLive(false);
    };
  }, [id, showAll]);

