  async function submitUpdate(e) {
    e.preventDefault();
    setUpdatesError('');

    if (updateForm.body.length > UPDATE_BODY_MAX) {
      setUpdatesError(
        `Update body must be ${UPDATE_BODY_MAX} characters or fewer (currently ${updateForm.body.length})`
      );
