              </button>
              <button
                type="button"
                className="btn-primary"
                onClick={handleSaveEdit}
                disabled={editLoading}
                style={{ opacity: editLoading ? 0.6 : 1 }}
              >
                {editLoading ? 'Saving...' : 'Save Changes'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Campaign Confirmation Dialog */}
      {showDeleteDialog && campaign && (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="delete-campaign-title"
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0, 0, 0, 0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000,
          }}
        >
          <div
            ref={deleteModalRef}
            style={{
              background: 'var(--color-surface)',
              borderRadius: '8px',
              padding: '2rem',
              maxWidth: '500px',
              width: '90%',
              boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)',
            }}
          >
            <h2
              id="delete-campaign-title"
              style={{
                fontSize: '1.5rem',
                fontWeight: 700,
                marginBottom: '1rem',
                color: 'var(--color-text-primary)',
              }}
            >
              Delete Campaign
            </h2>
            <p
              style={{
                fontSize: '0.95rem',
                color: 'var(--color-text-secondary)',
                marginBottom: '1.5rem',
                lineHeight: 1.5,
              }}
            >
              Are you sure you want to delete this campaign? This action cannot be undone. All
              contribution and withdrawal history will be preserved, but the campaign will no longer
              be visible to the public.
            </p>
            <div style={{ marginBottom: '1.5rem' }}>
              <label
                style={{
                  display: 'block',
                  fontWeight: 600,
                  marginBottom: '0.5rem',
                  fontSize: '0.9rem',
                  color: 'var(--color-text-primary)',
                }}
              >
                Type the campaign title to confirm:
              </label>
              <input
                type="text"
                value={deleteConfirmation}
                onChange={(e) => setDeleteConfirmation(e.target.value)}
                placeholder={campaign.title}
                style={{
                  width: '100%',
                  padding: '0.75rem',
                  border: '1px solid var(--color-border)',
                  borderRadius: '4px',
                  fontSize: '1rem',
                  boxSizing: 'border-box',
                }}
              />
            </div>
            {deleteError && (
              <p className="alert alert--error" style={{ marginBottom: '1.5rem' }}>
                {deleteError}
              </p>
            )}
            <div
              style={{
                display: 'flex',
                gap: '1rem',
                justifyContent: 'flex-end',
              }}
            >
              <button
                type="button"
                className="btn-secondary"
                onClick={() => {
                  setShowDeleteDialog(false);
                  setDeleteConfirmation('');
                  setDeleteError('');
                }}
                disabled={deleteLoading}
                style={{ opacity: deleteLoading ? 0.6 : 1 }}
              >
                Cancel
              </button>
              <button
                type="button"
                className="btn-primary"
                onClick={handleDeleteCampaign}
                disabled={deleteLoading || deleteConfirmation !== campaign.title}
                style={{
                  opacity: deleteLoading || deleteConfirmation !== campaign.title ? 0.6 : 1,
                  background: 'var(--color-status-error)',
                  borderColor: 'var(--color-status-error)',
                }}
              >
                {deleteLoading ? 'Deleting...' : 'Delete Campaign'}
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}

