    (sum, milestone) => sum + (Number(milestone.release_percentage) || 0),
    0
  );
}

export default function CreateCampaign() {
  const { t } = useTranslation();
  const { user, ready, updateUser } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [step, setStep] = useState(1);
  const [form, setForm] = useState({
    title: location.state?.prefill?.title || '',
    description: location.state?.prefill?.description || '',
    target_amount: location.state?.prefill?.target_amount || '',
    asset_type: location.state?.prefill?.asset_type || 'USDC',
    deadline: '',
    category: '',
    country: '',
    min_contribution: location.state?.prefill?.min_contribution || '',
    max_contribution: location.state?.prefill?.max_contribution || '',
    max_per_user: location.state?.prefill?.max_per_user || '',
    show_backer_amounts: location.state?.prefill?.show_backer_amounts ?? true,
    template_id: '',
    // Soroban treasury (#687). 'standard' keeps the threshold-2 multisig wallet;
    // 'contract' deploys a treasury contract that enforces the policy below.
    wallet_mode: 'standard',
    treasury_policy: {
      minHoldDays: 0,
      maxSingleWithdrawalPct: 100,
      withdrawalCooldownHours: 0,
      requireAuditorForAbove: '0',
      autoRefundOnMiss: false,
    },
    milestones: [],
    reward_tiers: [],

  });
  const [coverImageFile, setCoverImageFile] = useState(null);
  const [coverImagePreview, setCoverImagePreview] = useState('');
  const [isDragOverCover, setIsDragOverCover] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [duplicateWarning, setDuplicateWarning] = useState(null);
  const today = new Date().toISOString().split('T')[0];
  const [showCreatorTips, setShowCreatorTips] = useState(isCreatorOnboardingVisible);
  // A draft found in storage on load. Auto-save stays paused until the creator
  // restores or discards it, so an untouched form cannot overwrite it.
  const [pendingDraft, setPendingDraft] = useState(() =>
    location.state?.prefill ? null : loadDraft()
  );
  const [draftSavedAt, setDraftSavedAt] = useState(null);
  const [draftSaving, setDraftSaving] = useState(false);
  const [draftId, setDraftId] = useState(null);
  const [templates, setTemplates] = useState([]);

  // Local storage save (immediate indicator, updated by server save)
  const localSaveTimer = useRef(null);

  useEffect(() => {
    if (pendingDraft) return;
    if (!hasDraftContent(form)) return;

    if (localSaveTimer.current) clearTimeout(localSaveTimer.current);
    localSaveTimer.current = setTimeout(() => {
      const draft = saveDraft(form, step);
      if (draft && !draftId) setDraftSavedAt(draft.saved_at);
    }, DRAFT_SAVE_DEBOUNCE_MS);

    return () => {
      if (localSaveTimer.current) clearTimeout(localSaveTimer.current);
    };
  }, [form, step, pendingDraft, draftId]);

  // Server auto-save every 30s (debounced, with indicator)
  const serverSaveTimer = useRef(null);

  useEffect(() => {
    if (pendingDraft) return;
    if (!hasDraftContent(form)) return;
    if (!user) return;

    if (serverSaveTimer.current) clearTimeout(serverSaveTimer.current);

    serverSaveTimer.current = setTimeout(async () => {
      setDraftSaving(true);
      try {
        const result = await api.saveCampaignDraft({ form_data: form, step });
        setDraftId(result.id);
        setDraftSavedAt(result.saved_at);
        saveDraft(form, step);
      } catch {
        // server save failed — local storage is the fallback
      }
      setDraftSaving(false);
    }, SERVER_DRAFT_SAVE_MS);

    return () => {
      if (serverSaveTimer.current) clearTimeout(serverSaveTimer.current);
    };
  }, [form, step, pendingDraft, user]);

  // On mount, check for a server draft and offer to restore it
  useEffect(() => {
    if (!user) return;
    if (location.state?.prefill) return;

    let cancelled = false;

    api.getMyCampaignDraft()
      .then((serverDraft) => {
        if (cancelled) return;
        const localDraft = loadDraft();

        const serverTime = new Date(serverDraft.saved_at).getTime();
        const localTime = localDraft ? new Date(localDraft.saved_at).getTime() : 0;

        if (serverTime > localTime) {
          setPendingDraft({
            form: serverDraft.form_data,
            step: serverDraft.step,
            saved_at: serverDraft.saved_at,
          });
          setDraftId(serverDraft.id);
        } else if (localDraft) {
          setDraftId(null);
        }
      })
      .catch(() => {
        if (cancelled) return;
      });

    return () => { cancelled = true; };
  }, [user, location.state?.prefill]);

  function restoreDraft() {
    setForm(pendingDraft.form);
    setStep(pendingDraft.step || 1);
    setDraftSavedAt(pendingDraft.saved_at);
    setPendingDraft(null);
  }

  function discardDraft() {
    if (draftId) {
      api.deleteCampaignDraft(draftId).catch(() => {});
    }
    clearDraft();
    setPendingDraft(null);
    setDraftSavedAt(null);
    setDraftId(null);
  }

  function discardCurrentDraft() {
    if (draftId) {
      api.deleteCampaignDraft(draftId).catch(() => {});
    }
    clearDraft();
    setDraftSavedAt(null);
    setDraftId(null);
    setForm({
      title: '',
      description: '',
      target_amount: '',
      asset_type: 'USDC',
      deadline: '',
      category: '',
      country: '',
      min_contribution: '',
      max_contribution: '',
      max_per_user: '',
      show_backer_amounts: true,
      template_id: '',
      milestones: [],
      reward_tiers: [],
      min_reputation_score: 0,
      required_attestations: [],
    });
    setStep(1);
    setError('');
  }

  useEffect(() => {
    if (ready && !user) {
      navigate('/login', { replace: true, state: { from: '/campaigns/new' } });
    }
  }, [ready, user, navigate]);

  useEffect(() => {
    if (!user) return;
    api
      .getMe()
      .then(updateUser)
      .catch(() => {});
  }, [user, updateUser]);

  useEffect(() => {
    if (typeof api.getCampaignTemplates !== 'function') return;
    let cancelled = false;
    api.getCampaignTemplates()
      .then((result) => {
        if (!cancelled) setTemplates(Array.isArray(result) ? result : []);
      })
      .catch(() => {});
    return () => { cancelled = true; };
  }, []);

  function setField(field) {
    return (e) => setForm((f) => ({ ...f, [field]: e.target.value }));
  }

  function updateTreasuryPolicy(field, value) {
    setForm((f) => ({ ...f, treasury_policy: { ...f.treasury_policy, [field]: value } }));
  }

  function setDescription(value) {
    setForm((f) => ({ ...f, description: value }));
  }

  function selectAsset(value) {
    setForm((f) => ({ ...f, asset_type: value }));
  }

  function applyTemplate(templateId) {
    const template = templates.find((item) => item.id === templateId);
    if (!template) {
      setForm((f) => ({ ...f, template_id: '' }));
      return;
    }
    const data = template.template_data || {};
    setForm((f) => ({
      ...f,
      template_id: template.id,
      title: data.title || f.title,
      description: data.description || f.description,
      target_amount: data.target_amount || f.target_amount,
      category: template.category || f.category,
      milestones: Array.isArray(data.milestones) ? data.milestones : f.milestones,
      reward_tiers: Array.isArray(data.reward_tiers) ? data.reward_tiers : f.reward_tiers,
    }));
    setError('');
  }

  function setCoverImage(file) {
    if (!file) {
      setCoverImageFile(null);
      setCoverImagePreview('');
      return;
    }
    if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) {
      setError('Cover image must be JPG, PNG, or WEBP.');
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      setError('Cover image must be smaller than 5MB.');
      return;
    }
    setCoverImageFile(file);
    setError('');
    const reader = new FileReader();
    reader.onload = () => setCoverImagePreview(reader.result || '');
    reader.readAsDataURL(file);
  }

  function handleCoverImageChange(e) {
    setCoverImage(e.target.files?.[0] || null);
  }

  function handleCoverImageDrop(e) {
    e.preventDefault();
    setIsDragOverCover(false);
    const file = e.dataTransfer?.files?.[0] || null;
    setCoverImage(file);
  }

  function dismissTips() {
    dismissCreatorOnboarding();
    setShowCreatorTips(false);
  }

  function setMilestoneField(index, field, value) {
    setForm((f) => ({
      ...f,
      milestones: f.milestones.map((milestone, milestoneIndex) =>
        milestoneIndex === index ? { ...milestone, [field]: value } : milestone
      ),
    }));
  }

  function addMilestone() {
    setForm((f) => {
      if (f.milestones.length >= 5) return f;
      return { ...f, milestones: [...f.milestones, emptyMilestone()] };
    });
  }

  function removeMilestone(index) {
    setForm((f) => ({
      ...f,
      milestones: f.milestones.filter((_, milestoneIndex) => milestoneIndex !== index),
    }));
  }

  function setTierField(index, field, value) {
    setForm((f) => ({
      ...f,
      reward_tiers: f.reward_tiers.map((tier, tierIndex) =>
        tierIndex === index ? { ...tier, [field]: value } : tier
      ),
    }));
  }

  function addTier() {
    setForm((f) => {
      if (f.reward_tiers.length >= 10) return f;
      return { ...f, reward_tiers: [...f.reward_tiers, emptyTier()] };
    });
  }

  function removeTier(index) {
    setForm((f) => ({
      ...f,
      reward_tiers: f.reward_tiers.filter((_, tierIndex) => tierIndex !== index),
    }));
  }

  function validateTiers() {
    if (form.reward_tiers.length === 0) {
      setError('');
      return true;
    }
    if (form.reward_tiers.length > 10) {
      setError('Campaigns can define at most 10 reward tiers.');
      return false;
    }

    for (let index = 0; index < form.reward_tiers.length; index += 1) {
      const tier = form.reward_tiers[index];
      if (!tier.title.trim()) {
        setError(`Reward tier ${index + 1} needs a title.`);
        return false;
      }
      if (!tier.min_amount || Number(tier.min_amount) <= 0) {
        setError(`Reward tier ${index + 1} needs a minimum amount greater than zero.`);
        return false;
      }
      if (tier.limit && (Number(tier.limit) <= 0 || !Number.isInteger(Number(tier.limit)))) {
        setError(`Reward tier ${index + 1} limit must be a positive whole number.`);
        return false;
      }
      if (tier.estimated_delivery && tier.estimated_delivery < today) {
        setError(`Reward tier ${index + 1} estimated delivery must be today or in the future.`);
        return false;
      }
    }

    setError('');
    return true;
  }

  function validateStep1() {
    if (!form.title.trim()) {
      setError('Please enter a campaign title.');
      return false;
    }
    if (!form.target_amount || Number(form.target_amount) <= 0) {
      setError('Enter a fundraising goal greater than zero.');
      return false;
    }
    setError('');
    return true;
  }

  function validateStep2() {
    if (form.deadline) {
      const deadlineDate = new Date(form.deadline);
      const now = new Date();
      if (deadlineDate.getTime() <= now.getTime()) {
        setError('Deadline must be today or in the future (UTC).');
        return false;
      }
    }
    if (form.min_contribution && Number(form.min_contribution) <= 0) {
      setError('Minimum contribution must be greater than zero.');
      return false;
    }
    if (form.max_contribution) {
      if (Number(form.max_contribution) <= 0) {
        setError('Maximum contribution must be greater than zero.');
        return false;
      }
      if (form.min_contribution && Number(form.max_contribution) <= Number(form.min_contribution)) {
        setError('Maximum contribution must be greater than minimum contribution.');
        return false;
      }
      if (form.target_amount && Number(form.max_contribution) > Number(form.target_amount)) {
        setError('Maximum contribution cannot exceed the target amount.');
        return false;
      }
    }
    if (form.max_per_user) {
      if (Number(form.max_per_user) <= 0) {
        setError('Per-contributor cap must be greater than zero.');
        return false;
      }
      if (form.min_contribution && Number(form.max_per_user) <= Number(form.min_contribution)) {
        setError('Per-contributor cap must be greater than minimum contribution.');
        return false;
      }
    }

    setError('');
    return true;
  }

  function validateMilestones() {
    if (form.milestones.length === 0) {
      setError('');
      return true;
    }
    if (form.milestones.length > 5) {
      setError('Campaigns can define at most 5 milestones.');
      return false;
    }

    for (let index = 0; index < form.milestones.length; index += 1) {
      const milestone = form.milestones[index];
      if (!milestone.title.trim()) {
        setError(`Milestone ${index + 1} needs a title.`);
        return false;
      }
      if (!milestone.description.trim()) {
        setError(`Milestone ${index + 1} needs a description.`);
        return false;
      }
      if (!milestone.release_percentage || Number(milestone.release_percentage) <= 0) {
        setError(`Milestone ${index + 1} needs a release percentage greater than zero.`);
        return false;
      }
    }

    const total = milestonePercentTotal(form.milestones);
    if (Math.abs(total - 100) > 0.0001) {
      setError('Milestone percentages must sum to exactly 100%.');
      return false;
    }

    setError('');
    return true;
  }

  async function handleSubmit(e) {
    e.preventDefault();
    if (!validateStep1() || !validateStep2() || !validateMilestones() || !validateTiers()) return;

    if (!duplicateWarning) {
      setLoading(true);
      try {
        const checkRes = await api.checkDuplicateCampaign({ title: form.title.trim(), description: form.description.trim() });
        if (checkRes.isDuplicate) {
          setDuplicateWarning(`This campaign resembles an existing campaign: "${checkRes.similarTo}". It will be flagged for admin review.`);
          setLoading(false);
          return;
        }
      } catch (err) {
        // ignore error and proceed
      }
    }

    setLoading(true);
    setError('');
    try {
      let formattedDeadline = undefined;
      if (form.deadline) {
        // Convert YYYY-MM-DD date string to ISO 8601 with UTC (Z suffix)
        const [year, month, day] = form.deadline.split('-').map(Number);
        const deadlineDate = new Date(Date.UTC(year, month - 1, day, 23, 59, 59, 999));
        formattedDeadline = deadlineDate.toISOString();
      }

      const campaign = await api.createCampaign({
        title: form.title.trim(),
        description: form.description.trim() || undefined,
        target_amount: form.target_amount,
        asset_type: form.asset_type,
        deadline: formattedDeadline,
        category: form.category || undefined,
        country: form.country?.trim() || undefined,
        min_contribution: form.min_contribution ? Number(form.min_contribution) : undefined,
        max_contribution: form.max_contribution ? Number(form.max_contribution) : undefined,
        max_per_user: form.max_per_user ? Number(form.max_per_user) : undefined,
        template_id: form.template_id || undefined,
        milestones: form.milestones.length
          ? form.milestones.map((milestone) => ({
              title: milestone.title.trim(),
              description: milestone.description.trim(),
              release_percentage: Number(milestone.release_percentage),
          }))
          : undefined,
        reward_tiers: form.reward_tiers.length
          ? form.reward_tiers.map((tier) => ({
              title: tier.title.trim(),
              description: tier.description.trim() || null,
              min_amount: Number(tier.min_amount),
              limit: tier.limit ? parseInt(tier.limit, 10) : null,
              estimated_delivery: tier.estimated_delivery || null,
              nft_enabled: Boolean(tier.nft_enabled),
              nft_metadata_url: tier.nft_metadata_url?.trim() || null,
              nft_artwork_url: tier.nft_artwork_url?.trim() || null,
            }))
          : undefined,
      });

      // The policy needs a campaign to attach to, so it is saved once the campaign
      // exists. A failure here leaves the campaign on the standard wallet rather
      // than presenting it as contract-backed when it is not.
      if (form.wallet_mode === 'contract') {
        try {
          await api.setTreasuryPolicy(campaign.id, form.treasury_policy);
        } catch (policyError) {
          setError(
            policyError.message ||
              'Campaign created, but the treasury policy could not be saved. Set it in campaign settings.'
          );
        }
      }

      // Save contributor requirements if any were set (#689)
      const hasRequirements =
        (form.min_reputation_score > 0) || (form.required_attestations ?? []).length > 0;
      if (hasRequirements) {
        try {
          await api.setCampaignRequirements(campaign.id, {
            min_reputation_score: form.min_reputation_score ?? 0,
            required_attestations: form.required_attestations ?? [],
          });
        } catch (reqErr) {
          // Non-fatal: campaign exists, requirements can be set later in settings
          setError(
            reqErr.message ||
              'Campaign created, but contributor requirements could not be saved. Update them in campaign settings.'
          );
        }
      }

      clearDraft();
      if (draftId) {
        api.deleteCampaignDraft(draftId).catch(() => {});
        setDraftId(null);
      }

      let coverUploadError = '';
      if (coverImageFile) {
        try {
          await api.uploadCampaignCoverImage(campaign.id, coverImageFile);
        } catch (uploadError) {
          coverUploadError =
            uploadError.message || 'Campaign created, but cover image upload failed.';
        }
      }

      navigate(`/campaigns/${campaign.id}`, {
        state: { created: true, coverUploadError: coverUploadError || undefined },
      });
    } catch (err) {
      if (err.status === 401) {
        setError('Your session expired. Please log in again.');
        navigate('/login', { state: { from: '/campaigns/new' } });
      } else {
        setError(err.message || 'Could not create campaign. Try again.');
      }
      setLoading(false);
    }
  }

  if (!ready) {
    return (
      <main className="container page-narrow" style={{ paddingTop: '3rem' }}>
        <p className="alert alert--info">Restoring your session…</p>
      </main>
    );
  }

  if (!user) {
    return (
      <main className="container page-narrow" style={{ paddingTop: '3rem' }}>
        <p className="alert alert--info">Redirecting to sign in…</p>
      </main>
    );
  }

  if (user?.role !== 'creator' && user?.role !== 'admin') {
    return (
      <main className="container page-narrow" style={{ paddingTop: '3rem' }}>
        <p className="alert alert--info">Only creator or admin accounts can start campaigns.</p>
      </main>
    );
  }

  const kycRequired =
    user?.kyc_required_for_campaigns ??
    String(import.meta.env.VITE_KYC_REQUIRED_FOR_CAMPAIGNS ?? 'true').toLowerCase() !== 'false';

  const verificationStatus = user?.verification_status || user?.kyc_status || 'unverified';
  const verificationTier = user?.verification_tier || 'none';
  const isVerified = verificationStatus === 'verified' || verificationStatus === 'approved';

  const TIER_LIMITS = { none: 0, basic: 5000, standard: 50000, enhanced: Infinity };
  const tierLimit = TIER_LIMITS[verificationTier] ?? 0;
  const goalAmount = Number(form.target_amount) || 0;
  const exceedsTierLimit = kycRequired && isVerified && goalAmount > tierLimit && tierLimit < Infinity;

  if (kycRequired && !isVerified) {
    return (
      <main className="container page-narrow" style={{ paddingTop: '3rem', paddingBottom: '3rem' }}>
        <KycPrompt onUserUpdate={updateUser} title="Complete Verification to Create Campaigns" />
        <p style={{ marginTop: '1rem', fontSize: '0.9rem', color: 'var(--color-text-hint)' }}>
          Current verification status: <strong>{verificationStatus}</strong>.
        </p>
      </main>
    );
  }

  const milestoneTotal = milestonePercentTotal(form.milestones);

  return (
    <main className="container page-mid" style={{ paddingTop: '1.75rem', paddingBottom: '3rem' }}>
      <nav aria-label="Progress" style={{ marginBottom: '1.25rem' }}>
        <ol
          style={{
            listStyle: 'none',
            display: 'flex',
            gap: '0.5rem',
            flexWrap: 'wrap',
            fontSize: '0.8rem',
            fontWeight: 600,
            color: 'var(--color-text-hint)',
          }}
        >
          <li aria-current={step === 1 ? 'step' : undefined}>
            <span style={{ color: step === 1 ? 'var(--color-accent)' : 'var(--color-text-muted)' }}>
              {t('createCampaign.steps.goalAsset')}
            </span>
          </li>
          <li aria-hidden="true">→</li>
          <li aria-current={step === 2 ? 'step' : undefined}>
            <span style={{ color: step === 2 ? 'var(--color-accent)' : 'var(--color-text-muted)' }}>
              {t('createCampaign.steps.detailsLaunch')}
            </span>
          </li>
        </ol>
      </nav>

      <h1
        style={{
          fontSize: 'clamp(1.5rem, 4vw, 1.85rem)',
          fontWeight: 800,
          marginBottom: '0.35rem',
        }}
      >
        {t('createCampaign.title')}
      </h1>
      <p
        style={{
          color: 'var(--color-text-secondary)',
          marginBottom: '1.25rem',
          fontSize: '0.95rem',
          lineHeight: 1.55,
        }}
      >
        {t('createCampaign.subtitle')}
      </p>

      {showCreatorTips && (
        <OnboardingCallout title={t('createCampaign.tipsTitle')} onDismiss={dismissTips}>
          <ul>
            <li>{t('createCampaign.tip1')}</li>
            <li>{t('createCampaign.tip2')}</li>
            <li>{t('createCampaign.tip3')}</li>
          </ul>
        </OnboardingCallout>
      )}

      {pendingDraft && (
        <div className="alert alert--info" style={{ marginBottom: '1.25rem' }} role="status">
          <p>
            You have an unsaved draft from{' '}
            <strong>{new Date(pendingDraft.saved_at).toLocaleString()}</strong>.
          </p>
          <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', marginTop: '0.65rem' }}>
            <button type="button" className="btn-primary" onClick={restoreDraft}>
              Restore draft
            </button>
            <button type="button" className="btn-secondary" onClick={discardDraft}>
              Discard draft
            </button>
          </div>
        </div>
      )}

      {!pendingDraft && (draftSaving || draftSavedAt) && (
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '0.65rem',
            flexWrap: 'wrap',
            marginBottom: '1rem',
            fontSize: '0.8rem',
            color: 'var(--color-text-hint)',
          }}
          role="status"
          aria-live="polite"
        >
          <span>
            {draftSaving
              ? 'Saving draft…'
              : `Draft saved ${new Date(draftSavedAt).toLocaleTimeString()}`}
          </span>
          {draftSavedAt && (
            <button
              type="button"
              onClick={discardCurrentDraft}
              style={{
                background: 'none',
                border: 'none',
                padding: 0,
                color: 'var(--color-accent)',
                fontWeight: 600,
                cursor: 'pointer',
                fontSize: '0.8rem',
              }}
            >
              Discard draft
            </button>
          )}
        </div>
      )}

      <form onSubmit={handleSubmit}>
        {location.state?.prefill && (
          <div className="alert alert--info" style={{ marginBottom: '1.25rem' }}>
            Pre-filled from an existing campaign. Review and adjust before launching.
          </div>
        )}
        {step === 1 && (
          <>
            {templates.length > 0 && (
              <div className="form-stack" style={{ marginBottom: '1rem' }}>
                <label className="label-strong" htmlFor="cc-template">
                  Start with a template (Optional)
                </label>
                <select
                  id="cc-template"
                  value={form.template_id}
                  onChange={(event) => applyTemplate(event.target.value)}
                >
                  <option value="">Start from scratch</option>
                  {templates.map((template) => (
                    <option key={template.id} value={template.id}>
                      {template.name} — {template.description}
                    </option>
                  ))}
                </select>
                {form.template_id && (
                  <small style={{ color: 'var(--color-text-hint)' }}>
                    The template filled in your campaign details. You can customize every field.
                  </small>
                )}
              </div>
            )}
            <div className="form-stack">
              <label className="label-strong" htmlFor="cc-title">
                {t('createCampaign.campaignTitle')}
              </label>
              <input
                id="cc-title"
                value={form.title}
                onChange={setField('title')}
                placeholder={t('createCampaign.campaignTitlePlaceholder')}
                required
                aria-required="true"
                autoComplete="off"
              />
            </div>

            <div className="form-stack" style={{ marginTop: '1rem' }}>
              <label className="label-strong" htmlFor="cc-target">
                {t('createCampaign.fundraisingGoal')}
              </label>
              <input
                id="cc-target"
                type="number"
                inputMode="decimal"
                min="0.0000001"
                step="any"
                value={form.target_amount}
                onChange={setField('target_amount')}
                placeholder="0.00"
                required
                aria-required="true"
              />
              {kycRequired && isVerified && verificationTier !== 'enhanced' && (
                <small style={{ color: 'var(--color-text-hint)', fontSize: '0.8rem' }}>
                  Your {verificationTier} tier allows campaign goals up to ${tierLimit.toLocaleString()}.
                  {verificationTier === 'basic' && ' Upgrade to Standard for up to $50,000.'}
                  {verificationTier === 'standard' && ' Upgrade to Enhanced for unlimited goals.'}
                </small>
              )}
              {exceedsTierLimit && (
                <div className="alert alert--warning" style={{ marginTop: '0.5rem', fontSize: '0.85rem' }}>
                  <strong>Goal exceeds your {verificationTier} tier limit of ${tierLimit.toLocaleString()}.</strong>
                  <p style={{ margin: '0.35rem 0 0', fontSize: '0.82rem' }}>
                    {verificationTier === 'basic' && 'Upgrade to Standard verification (ID + address) to run campaigns up to $50,000.'}
                    {verificationTier === 'standard' && 'Upgrade to Enhanced verification (ID + address + liveness) for unlimited campaign goals.'}
                  </p>
                </div>
              )}
            </div>

            <div className="form-stack" style={{ marginTop: '1rem' }}>
              <label className="label-strong" htmlFor="cc-category">
                Category (Optional)
              </label>
              <input
                id="cc-category"
                value={form.category}
                onChange={setField('category')}
                placeholder="e.g. tech, art, community"
                autoComplete="off"
              />
            </div>

            <div style={{ marginTop: '1.25rem', border: '1px dashed var(--color-border)', padding: '1rem', borderRadius: '8px' }}>
              <h3 style={{ fontSize: '1rem', fontWeight: 700, marginBottom: '0.5rem' }}>Contribution limits (Optional)</h3>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
                <div className="form-stack">
                  <label className="label-strong" htmlFor="cc-min-contrib">
                    {t('createCampaign.minContribution')}
                  </label>
                  <input
                    id="cc-min-contrib"
                    type="number"
                    inputMode="decimal"
                    min="0.0000001"
                    step="any"
                    value={form.min_contribution}
                    onChange={setField('min_contribution')}
                    placeholder="e.g. 5"
                  />
                </div>
                <div className="form-stack">
                  <label className="label-strong" htmlFor="cc-max-contrib">
                    {t('createCampaign.maxContribution')}
                  </label>
                  <input
                    id="cc-max-contrib"
                    type="number"
                    inputMode="decimal"
                    min="0.0000001"
                    step="any"
                    value={form.max_contribution}
                    onChange={setField('max_contribution')}
                    placeholder="e.g. 500"
                  />
                </div>
              </div>
            </div>

            <fieldset style={{ border: 'none', margin: '1.25rem 0 0', padding: 0 }}>
              <legend className="label-strong" style={{ marginBottom: '0.5rem' }}>
                {t('createCampaign.settlementAsset')}
              </legend>
              <p
                style={{
                  fontSize: '0.8rem',
                  color: 'var(--color-text-hint)',
                  marginBottom: '0.65rem',
                }}
              >
                {t('createCampaign.settlementAssetHelp')}
              </p>
              <div className="asset-picker" role="radiogroup" aria-label="Settlement asset">
                {ASSETS.map((a) => (
                  <label
                    key={a.value}
                    className={`asset-picker__option${form.asset_type === a.value ? ' asset-picker__option--selected' : ''}`}
                  >
                    <input
                      type="radio"
                      name="asset_type"
                      value={a.value}
                      checked={form.asset_type === a.value}
                      onChange={() => selectAsset(a.value)}
                    />
                    <div className="asset-picker__code">{a.label}</div>
                    <div className="asset-picker__hint">{a.hint}</div>
                  </label>
                ))}
              </div>
            </fieldset>

            <fieldset className="form-stack" style={{ marginTop: '1rem' }}>
              <legend className="label-strong">Treasury mode</legend>
              <p style={{ color: 'var(--color-text-muted)', marginBottom: '0.65rem' }}>
                Standard uses the two-of-two multisig wallet. Contract holds the funds in a
                Soroban treasury that enforces your spending rules on-chain — the rules cannot be
                changed once the campaign is created.
              </p>
              <div role="radiogroup" aria-label="Treasury mode">
                <label>
                  <input
                    type="radio"
                    name="wallet_mode"
                    value="standard"
                    checked={form.wallet_mode === 'standard'}
                    onChange={() => setForm((f) => ({ ...f, wallet_mode: 'standard' }))}
                  />
                  Standard multisig
                </label>
                <label>
                  <input
                    type="radio"
                    name="wallet_mode"
                    value="contract"
                    checked={form.wallet_mode === 'contract'}
                    onChange={() => setForm((f) => ({ ...f, wallet_mode: 'contract' }))}
                  />
                  Soroban contract treasury
                </label>
              </div>

              {form.wallet_mode === 'contract' && (
                <div className="form-stack" aria-label="Treasury policy">
                  <label htmlFor="cc-min-hold">
                    Minimum hold period: <strong>{form.treasury_policy.minHoldDays} days</strong>{' '}
                    after the deadline
                  </label>
                  <input
                    id="cc-min-hold"
                    type="range"
                    min="0"
                    max="90"
                    value={form.treasury_policy.minHoldDays}
                    onChange={(e) => updateTreasuryPolicy('minHoldDays', Number(e.target.value))}
                  />

                  <label htmlFor="cc-max-pct">
                    Maximum single withdrawal:{' '}
                    <strong>{form.treasury_policy.maxSingleWithdrawalPct}%</strong> of the balance
                  </label>
                  <input
                    id="cc-max-pct"
                    type="range"
                    min="10"
                    max="100"
                    value={form.treasury_policy.maxSingleWithdrawalPct}
                    onChange={(e) =>
                      updateTreasuryPolicy('maxSingleWithdrawalPct', Number(e.target.value))
                    }
                  />

                  <label htmlFor="cc-cooldown">
                    Cooldown between withdrawals:{' '}
                    <strong>{form.treasury_policy.withdrawalCooldownHours} hours</strong>
                  </label>
                  <input
                    id="cc-cooldown"
                    type="range"
                    min="0"
                    max="168"
                    value={form.treasury_policy.withdrawalCooldownHours}
                    onChange={(e) =>
                      updateTreasuryPolicy('withdrawalCooldownHours', Number(e.target.value))
                    }
                  />

                  <label htmlFor="cc-auditor-above">
                    Auditor required above ({form.asset_type})
                  </label>
                  <input
                    id="cc-auditor-above"
                    type="text"
                    inputMode="decimal"
                    value={form.treasury_policy.requireAuditorForAbove}
                    onChange={(e) =>
                      updateTreasuryPolicy('requireAuditorForAbove', e.target.value)
                    }
                  />

                  <label htmlFor="cc-auto-refund">
                    <input
                      id="cc-auto-refund"
                      type="checkbox"
                      checked={form.treasury_policy.autoRefundOnMiss}
                      onChange={(e) =>
                        updateTreasuryPolicy('autoRefundOnMiss', e.target.checked)
                      }
                    />
                    Refund contributors automatically if the goal is missed
                  </label>
                  <small style={{ color: 'var(--color-text-muted)' }}>
                    Anyone can trigger the refund once the deadline passes, so contributors are
                    not dependent on you or CrowdPay acting.
                  </small>
                </div>
              )}
            </fieldset>

            <div className="form-stack" style={{ marginTop: '1rem' }}>
              <label className="label-strong" htmlFor="cc-category">
                Category{' '}
                <span style={{ fontWeight: 500, color: 'var(--color-text-muted)' }}>
                  (optional)
                </span>
              </label>
              <select id="cc-category" value={form.category} onChange={setField('category')}>
                <option value="">Select a category</option>
                {CATEGORIES.map((c) => (
                  <option key={c.value} value={c.value}>
                    {c.label}
                  </option>
                ))}
              </select>
            </div>

            <div className="form-group" style={{ marginTop: '1rem' }}>
              <label className="label-strong" htmlFor="cc-country">
                Location{' '}
                <span style={{ fontWeight: 500, color: 'var(--color-text-muted)' }}>
                  (optional)
                </span>
              </label>
              <input
                id="cc-country"
                type="text"
                value={form.country}
                onChange={setField('country')}
                placeholder="e.g. United States, Kenya, Global"
                maxLength={80}
              />
            </div>

            {error && (
              <p className="alert alert--error" style={{ marginTop: '1rem' }} role="alert">
                {error}
              </p>
            )}

            <button
              type="button"
              className="btn-primary"
              style={{ width: '100%', marginTop: '1.25rem' }}
              onClick={() => {
                if (validateStep1()) setStep(2);
              }}
            >
              {t('createCampaign.continueToDetails')}
            </button>
          </>
        )}

        {step === 2 && (
          <>
            <div
              style={{
                display: 'flex',
                flexWrap: 'wrap',
                alignItems: 'center',
                gap: '0.75rem',
                background: 'var(--color-surface)',
                border: '1px solid var(--color-border-lightest)',
                borderRadius: '12px',
                padding: '1rem',
                marginBottom: '1rem',
              }}
            >
              <button
                type="button"
                onClick={() => {
                  setError('');
                  setStep(1);
                }}
                style={{
                  border: 'none',
                  background: 'transparent',
                  color: 'var(--color-accent)',
                  padding: 0,
                  cursor: 'pointer',
                  fontWeight: 600,
                }}
              >
                ← Edit
              </button>
              <span style={{ fontWeight: 700 }}>{form.title || 'Untitled campaign'}</span>
              <span style={{ color: 'var(--color-text-muted)' }}>
                Goal: {form.target_amount || '—'} {form.asset_type || ''}
              </span>
            </div>
            <div className="form-stack">
              <label className="label-strong" htmlFor="cc-desc">
                {t('createCampaign.description')}{' '}
                <span style={{ fontWeight: 500, color: 'var(--color-text-muted)' }}>
                  {t('createCampaign.optional')}
                </span>
              </label>
              <SimpleMDE
                id="cc-desc"
                value={form.description}
                onChange={setDescription}
                options={{
                  spellChecker: false,
                  placeholder: t('createCampaign.descriptionPlaceholder'),
                }}
              />
            </div>

            <div className="form-stack" style={{ marginTop: '1rem' }}>
              <label className="label-strong" htmlFor="cc-cover">
                {t('createCampaign.coverImage')}{' '}
                <span style={{ fontWeight: 500, color: 'var(--color-text-muted)' }}>
                  {t('createCampaign.optional')}
                </span>
              </label>
              <div
                onDragOver={(e) => {
                  e.preventDefault();
                  setIsDragOverCover(true);
                }}
                onDragLeave={() => setIsDragOverCover(false)}
                onDrop={handleCoverImageDrop}
                style={{
                  border: `2px dashed ${isDragOverCover ? 'var(--color-accent)' : 'var(--color-border-lightest)'}`,
                  borderRadius: '12px',
                  padding: '0.9rem',
                  background: isDragOverCover ? 'var(--color-accent-lightest)' : 'var(--color-surface)',
                }}
              >
                <input
                  id="cc-cover"
                  type="file"
                  accept="image/jpeg,image/png,image/webp"
                  onChange={handleCoverImageChange}
                />
                <p
                  style={{
                    marginTop: '0.45rem',
                    marginBottom: 0,
                    color: 'var(--color-text-hint)',
                    fontSize: '0.8rem',
                  }}
                >
                  {t('createCampaign.coverImageHelp')}
                </p>
              </div>
              {coverImagePreview && (
                <img
                  src={coverImagePreview}
                  alt="Cover preview"
                  style={{
                    marginTop: '0.75rem',
                    width: '100%',
                    borderRadius: '12px',
                    maxHeight: '220px',
                    objectFit: 'cover',
                  }}
                />
              )}
            </div>

            <div className="form-stack" style={{ marginTop: '1rem' }}>
              <label className="label-strong" htmlFor="cc-deadline">
                {t('createCampaign.deadline')}{' '}
                <span style={{ fontWeight: 500, color: 'var(--color-text-muted)' }}>
                  {t('createCampaign.optional')}
                </span>
              </label>
              <input
                id="cc-deadline"
                type="date"
                min={today}
                value={form.deadline}
                onChange={setField('deadline')}
              />
            </div>

            <div
              className="form-stack"
              style={{
                marginTop: '1.25rem',
                flexDirection: 'row',
                alignItems: 'center',
                gap: '0.5rem',
              }}
            >
              <input
                id="cc-show-backers"
                type="checkbox"
                style={{ width: 'auto', margin: 0 }}
                checked={form.show_backer_amounts}
                onChange={(e) => setForm((f) => ({ ...f, show_backer_amounts: e.target.checked }))}
              />
              <label
                htmlFor="cc-show-backers"
                style={{ fontWeight: 600, fontSize: '0.9rem', cursor: 'pointer' }}
              >
                {t('createCampaign.showAmounts')}
              </label>
            </div>
            <p
              style={{ fontSize: '0.8rem', color: 'var(--color-text-hint)', marginTop: '0.35rem' }}
            >
              {t('createCampaign.showAmountsHelp')}
            </p>

            <details style={{ marginTop: '1rem' }}>
              <summary style={{ cursor: 'pointer', fontWeight: 600, fontSize: '0.9rem' }}>
                Contribution limits (optional)
              </summary>
              <div
                style={{
                  marginTop: '0.75rem',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: '0.75rem',
                }}
              >
                <div className="form-stack">
                  <label htmlFor="cc-min">Minimum per contribution ({form.asset_type})</label>
                  <input
                    id="cc-min"
                    type="number"
                    min="0"
                    step="any"
                    value={form.min_contribution}
                    onChange={setField('min_contribution')}
                    placeholder="No minimum"
                  />
                </div>
                <div className="form-stack">
                  <label htmlFor="cc-max">Maximum per contribution ({form.asset_type})</label>
                  <input
                    id="cc-max"
                    type="number"
                    min="0"
                    step="any"
                    value={form.max_contribution}
                    onChange={setField('max_contribution')}
                    placeholder="No maximum"
                  />
                </div>
                <div className="form-stack">
                  <label htmlFor="cc-maxuser">Per-contributor cap ({form.asset_type})</label>
                  <input
                    id="cc-maxuser"
                    type="number"
                    min="0"
                    step="any"
                    value={form.max_per_user}
                    onChange={setField('max_per_user')}
                    placeholder="No cap"
                  />
                </div>
              </div>
            </details>

            {error && (
              <p className="alert alert--error" style={{ marginTop: '1rem' }} role="alert">
                {error}
              </p>
            )}

            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                gap: '0.65rem',
                marginTop: '1.25rem',
              }}
            >
              <button
                type="button"
                className="btn-primary"
                style={{ width: '100%' }}
                onClick={() => {
                  if (validateStep2()) setStep(3);
                }}
              >
                {t('createCampaign.continueToMilestones')}
              </button>
              <button
                type="button"
                className="btn-secondary"
                style={{ width: '100%' }}
                onClick={() => {
                  setError('');
                  setStep(1);
                }}
              >
                {t('createCampaign.back')}
              </button>
            </div>
          </>
        )}

        {step === 3 && (
          <>
            <div className="campaign-card" style={{ marginBottom: '1rem' }}>
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: '0.75rem',
                  flexWrap: 'wrap',
                  marginBottom: '0.5rem',
                }}
              >
                <strong>{t('createCampaign.milestonePlan')}</strong>
                <span
                  style={{
                    fontSize: '0.85rem',
                    color:
                      milestoneTotal === 100 || form.milestones.length === 0
                        ? 'var(--color-success-text)'
                        : 'var(--color-warning-text)',
                  }}
                >
                  {t('createCampaign.milestoneTotal', { count: milestoneTotal.toLocaleString() })}
                </span>
              </div>
              <p
                style={{
                  color: 'var(--color-text-secondary)',
                  fontSize: '0.88rem',
                  lineHeight: 1.5,
                }}
              >
                {t('createCampaign.milestoneHelp')}
              </p>
            </div>

            {form.milestones.length === 0 ? (
              <div className="alert alert--info" style={{ marginBottom: '1rem' }}>
                {t('createCampaign.noMilestones')}
              </div>
            ) : (
              <div style={{ display: 'grid', gap: '0.85rem' }}>
                {form.milestones.map((milestone, index) => (
                  <div key={index} className="campaign-card">
                    <div
                      style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        gap: '0.75rem',
                        alignItems: 'center',
                        marginBottom: '0.5rem',
                      }}
                    >
                      <strong>{t('createCampaign.milestone', { count: index + 1 })}</strong>
                      <button
                        type="button"
                        className="btn-secondary"
                        onClick={() => removeMilestone(index)}
                        style={{ fontSize: '0.8rem' }}
                      >
                        Remove
                      </button>
                    </div>
                    <div className="form-stack">
                      <label className="label-strong">{t('createCampaign.milestoneTitle')}</label>
                      <input
                        value={milestone.title}
                        onChange={(e) => setMilestoneField(index, 'title', e.target.value)}
                        placeholder="e.g. Deliver prototype"
                      />
                    </div>
                    <div className="form-stack" style={{ marginTop: '0.75rem' }}>
                      <label className="label-strong">
                        {t('createCampaign.milestoneDescription')}
                      </label>
                      <textarea
                        value={milestone.description}
                        onChange={(e) => setMilestoneField(index, 'description', e.target.value)}
                        rows={3}
                        placeholder="Explain what contributors should expect before this release unlocks."
                      />
                    </div>
                    <div className="form-stack" style={{ marginTop: '0.75rem' }}>
                      <label className="label-strong">{t('createCampaign.milestoneRelease')}</label>
                      <input
                        type="number"
                        inputMode="decimal"
                        min="0.01"
                        step="0.01"
                        value={milestone.release_percentage}
                        onChange={(e) =>
                          setMilestoneField(index, 'release_percentage', e.target.value)
                        }
                        placeholder="25"
                      />
                    </div>
                  </div>
                ))}
              </div>
            )}

            {form.milestones.length < 5 && (
              <button
                type="button"
                className="btn-secondary"
                style={{ width: '100%', marginTop: '1rem' }}
                onClick={addMilestone}
              >
                {t('createCampaign.addMilestone')}
              </button>
            )}

            <div className="campaign-card" style={{ marginTop: '1.75rem', marginBottom: '1rem' }}>
              <strong>Reward tiers <span style={{ fontWeight: 500, color: 'var(--color-text-muted)' }}>(optional)</span></strong>
              <p style={{ color: 'var(--color-text-secondary)', fontSize: '0.88rem', lineHeight: 1.5, marginTop: '0.35rem' }}>
                Offer backer perks at set contribution levels. Backers who contribute at or above a {"tier's"} minimum unlock it. Up to 10 tiers.
              </p>
            </div>

            {form.reward_tiers.length === 0 ? (
              <div className="alert alert--info" style={{ marginBottom: '1rem' }}>
                No reward tiers yet. Tiers are optional — you can launch without them.
              </div>
            ) : (
              <div style={{ display: 'grid', gap: '0.85rem' }}>
                {form.reward_tiers.map((tier, index) => (
                  <div key={index} className="campaign-card">
                    <div style={{ display: 'flex', justifyContent: 'space-between', gap: '0.75rem', alignItems: 'center', marginBottom: '0.5rem' }}>
                      <strong>Tier {index + 1}</strong>
                      <button type="button" className="btn-secondary" onClick={() => removeTier(index)} style={{ fontSize: '0.8rem' }}>
                        Remove
                      </button>
                    </div>
                    <div className="form-stack">
                      <label className="label-strong">Title</label>
                      <input
                        value={tier.title}
                        onChange={(e) => setTierField(index, 'title', e.target.value)}
                        placeholder="e.g. Early Bird"
                      />
                    </div>
                    <div className="form-stack" style={{ marginTop: '0.75rem' }}>
                      <label className="label-strong">Description <span style={{ fontWeight: 500, color: 'var(--color-text-muted)' }}>(optional)</span></label>
                      <textarea
                        value={tier.description}
                        onChange={(e) => setTierField(index, 'description', e.target.value)}
                        rows={2}
                        placeholder="What backers get at this tier."
                      />
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem', marginTop: '0.75rem' }}>
                      <div className="form-stack">
                        <label className="label-strong">Minimum amount ({form.asset_type})</label>
                        <input
                          type="number"
                          inputMode="decimal"
                          min="0.0000001"
                          step="any"
                          value={tier.min_amount}
                          onChange={(e) => setTierField(index, 'min_amount', e.target.value)}
                          placeholder="e.g. 25"
                        />
                      </div>
                      <div className="form-stack">
                        <label className="label-strong">Limit <span style={{ fontWeight: 500, color: 'var(--color-text-muted)' }}>(optional)</span></label>
                        <input
                          type="number"
                          inputMode="numeric"
                          min="1"
                          step="1"
                          value={tier.limit}
                          onChange={(e) => setTierField(index, 'limit', e.target.value)}
                          placeholder="Unlimited"
                        />
                      </div>
                    </div>
                    <div className="form-stack" style={{ marginTop: '0.75rem' }}>
                      <label className="label-strong">Estimated delivery <span style={{ fontWeight: 500, color: 'var(--color-text-muted)' }}>(optional)</span></label>
                      <input
                        type="date"
                        min={today}
                        value={tier.estimated_delivery}
                        onChange={(e) => setTierField(index, 'estimated_delivery', e.target.value)}
                      />
                    </div>
                    <div className="campaign-card" style={{ marginTop: '0.75rem', padding: '0.85rem' }}>
                      <label style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontWeight: 700 }}>
                        <input
                          type="checkbox"
                          checked={Boolean(tier.nft_enabled)}
                          onChange={(e) => setTierField(index, 'nft_enabled', e.target.checked)}
                        />
                        Issue an NFT proof of support for this tier
                      </label>
                      <p style={{ marginTop: '0.45rem', marginBottom: '0.65rem', fontSize: '0.84rem', color: 'var(--color-text-secondary)' }}>
                        Contributors who unlock this tier will receive a unique NFT reward record linked to the campaign.
                      </p>
                      {Boolean(tier.nft_enabled) && (
                        <div style={{ display: 'grid', gap: '0.65rem' }}>
                          <div className="form-stack">
                            <label className="label-strong">Metadata URL <span style={{ fontWeight: 500, color: 'var(--color-text-muted)' }}>(optional)</span></label>
                            <input
                              value={tier.nft_metadata_url || ''}
                              onChange={(e) => setTierField(index, 'nft_metadata_url', e.target.value)}
                              placeholder="https://ipfs.io/ipfs/..."
                            />
                          </div>
                          <div className="form-stack">
                            <label className="label-strong">Artwork URL <span style={{ fontWeight: 500, color: 'var(--color-text-muted)' }}>(optional)</span></label>
                            <input
                              value={tier.nft_artwork_url || ''}
                              onChange={(e) => setTierField(index, 'nft_artwork_url', e.target.value)}
                              placeholder="https://ipfs.io/ipfs/..."
                            />
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}

            {form.reward_tiers.length < 10 && (
              <button type="button" className="btn-secondary" style={{ width: '100%', marginTop: '1rem' }} onClick={addTier}>
                Add reward tier
              </button>
            )}

            <div className="alert alert--info" style={{ marginTop: '1.25rem' }} role="status">
              <strong>{t('createCampaign.launchSummary')}</strong> {form.title || 'Untitled'} with a
              goal of {form.target_amount || '—'} {form.asset_type}
              {form.min_contribution && ` (Min: ${form.min_contribution} ${form.asset_type})`}
              {form.max_contribution && ` (Max: ${form.max_contribution} ${form.asset_type})`}
              {form.max_per_user && ` (Cap: ${form.max_per_user} ${form.asset_type})`}
              {form.milestones.length
                ? ` and ${form.milestones.length} milestone release${form.milestones.length > 1 ? 's' : ''}.`
                : ' and no milestone plan.'}
            </div>

            {/* ── Contributor Requirements (#689) ─────────────────────────── */}
            <div className="campaign-card" style={{ marginTop: '1.25rem' }}>
              <strong style={{ display: 'block', marginBottom: '0.5rem' }}>
                Contributor Requirements
              </strong>
              <p style={{ fontSize: '0.85rem', color: 'var(--color-text-secondary)', marginBottom: '1rem' }}>
                Optionally restrict who can contribute to this campaign. Contributors who don&apos;t
                meet these requirements will be blocked.
              </p>

              {/* Minimum reputation score */}
              <label className="label-strong" htmlFor="min_reputation_score">
                Minimum reputation score (0 = no minimum)
              </label>
              <input
                id="min_reputation_score"
                type="range"
                min="0"
                max="500"
                step="10"
                value={form.min_reputation_score ?? 0}
                onChange={(e) =>
                  setForm((f) => ({ ...f, min_reputation_score: Number(e.target.value) }))
                }
                style={{ width: '100%', margin: '0.5rem 0' }}
              />
              <div style={{ fontSize: '0.85rem', color: 'var(--color-text-secondary)', marginBottom: '1rem' }}>
                Selected: <strong>{form.min_reputation_score ?? 0}</strong>
              </div>

              {/* Required attestations */}
              <label className="label-strong" style={{ display: 'block', marginBottom: '0.5rem' }}>
                Required KYC attestations
              </label>
              {[
                { value: 'kyc_basic',    label: 'KYC Basic'    },
                { value: 'kyc_standard', label: 'KYC Standard' },
                { value: 'kyc_enhanced', label: 'KYC Enhanced' },
              ].map(({ value, label }) => {
                const current = form.required_attestations ?? [];
                const checked = current.includes(value);
                return (
                  <label
                    key={value}
                    style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.4rem', cursor: 'pointer' }}
                  >
                    <input
                      type="checkbox"
                      checked={checked}
                      onChange={() =>
                        setForm((f) => ({
                          ...f,
                          required_attestations: checked
                            ? (f.required_attestations ?? []).filter((a) => a !== value)
                            : [...(f.required_attestations ?? []), value],
                        }))
                      }
                    />
                    <span style={{ fontSize: '0.875rem' }}>{label}</span>
                  </label>
                );
              })}

              {((form.min_reputation_score > 0) || (form.required_attestations ?? []).length > 0) && (
                <div className="alert alert--info" style={{ marginTop: '0.75rem', fontSize: '0.82rem' }}>
                  Contributors without these requirements will be blocked from contributing to this campaign.
                </div>
              )}
            </div>

            {error && (
              <p className="alert alert--error" style={{ marginTop: '1rem' }} role="alert">
                {error}
              </p>
            )}

            {duplicateWarning && (
              <div className="alert alert--warning" style={{ marginTop: '1rem' }} role="alert">
                <p><strong>Warning:</strong> {duplicateWarning}</p>
                <p style={{ marginTop: '0.5rem', fontSize: '0.9rem' }}>You can still launch it, but it will be hidden until reviewed by an admin.</p>
              </div>
            )}

            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                gap: '0.65rem',
                marginTop: '1.25rem',
              }}
            >
              <button
                type="submit"
                className="btn-primary"
                disabled={loading}
                style={{ width: '100%' }}
              >
                {loading ? t('createCampaign.creatingWallet') : t('createCampaign.launchCampaign')}
              </button>
              <button
                type="button"
                className="btn-secondary"
                style={{ width: '100%' }}
                disabled={loading}
                onClick={() => {
                  setError('');
                  setStep(2);
                }}
              >
                Back
              </button>
            </div>
          </>
        )}
      </form>

      <p style={{ marginTop: '1.5rem', fontSize: '0.85rem', color: 'var(--color-text-hint)' }}>
        <Link to="/discover" style={{ color: 'var(--color-accent)', fontWeight: 600 }}>
          {t('createCampaign.backToCampaigns')}
        </Link>
      </p>
    </main>
  );
}

import React, { useEffect, useState } from 'react';
import { Link, Navigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import { api } from '../services/api';

const MiniLineChart = React.lazy(() => import('../components/MiniLineChart'));

import {
  XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid,
} from 'recharts';

function StatCard({ label, value }) {
  return (
    <div className="campaign-card" style={{ minHeight: 'auto', padding: '0.6rem 0.75rem' }}>
      <strong style={{ fontSize: '1rem' }}>{value}</strong>
      <div style={{ fontSize: '0.78rem', color: 'var(--color-text-hint)' }}>{label}</div>
    </div>
  );
}

function BenchmarkBar({ creator, platform, label }) {
  const maxVal = Math.max(creator || 0, platform || 0, 1);
  return (
    <div style={{ marginBottom: '0.6rem' }}>
      <div style={{ fontSize: '0.82rem', fontWeight: 600, marginBottom: '0.25rem' }}>{label}</div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.15rem' }}>
        <span style={{ fontSize: '0.75rem', width: 60, color: 'var(--color-text-secondary)' }}>You</span>
        <div style={{ flex: 1, background: 'var(--color-surface)', borderRadius: 4, height: 12 }}>
          <div style={{ width: `${(creator / maxVal) * 100}%`, height: 12, borderRadius: 4, background: 'var(--color-accent)' }} />
        </div>
        <span style={{ fontSize: '0.75rem', width: 50, textAlign: 'right' }}>{creator?.toFixed(1) ?? '—'}</span>
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
        <span style={{ fontSize: '0.75rem', width: 60, color: 'var(--color-text-hint)' }}>Platform</span>
        <div style={{ flex: 1, background: 'var(--color-surface)', borderRadius: 4, height: 12 }}>
          <div style={{ width: `${(platform / maxVal) * 100}%`, height: 12, borderRadius: 4, background: '#94a3b8' }} />
        </div>
        <span style={{ fontSize: '0.75rem', width: 50, textAlign: 'right' }}>{platform?.toFixed(1) ?? '—'}</span>
      </div>
    </div>
  );
}

export default function CreatorAnalytics() {
  const { user, ready } = useAuth();
  const { t } = useTranslation();
  const [overview, setOverview] = useState(null);
  const [campaigns, setCampaigns] = useState([]);
  const [benchmarks, setBenchmarks] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [sortField, setSortField] = useState('goal_pct');
  const [sortDir, setSortDir] = useState('desc');

  const isCreator = user?.role === 'creator' || user?.role === 'admin';

  useEffect(() => {
    if (!user || !isCreator) return;
    setLoading(true);
    Promise.all([
      api.getCreatorAnalyticsOverview(),
      api.getMyCampaigns({ limit: 50 }),
      api.getCreatorBenchmarks(),
    ])
      .then(([ov, campRes, bm]) => {
        setOverview(ov);
        setCampaigns(Array.isArray(campRes) ? campRes : campRes?.data || []);
        setBenchmarks(bm);
      })
      .catch((err) => setError(err.message || 'Failed to load analytics'))
      .finally(() => setLoading(false));
  }, [user, isCreator]);

  if (!ready) return null;
  if (!user) return <Navigate to="/login" replace />;
  if (!isCreator) return <Navigate to="/dashboard" replace />;

  function toggleSort(field) {
    if (sortField === field) {
      setSortDir((d) => (d === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortField(field);
      setSortDir('desc');
    }
  }

  const campaignsWithGoal = campaigns.map((c) => ({
    ...c,
    goal_pct: Number(c.target_amount) > 0
      ? Math.min(100, (Number(c.raised_amount) / Number(c.target_amount)) * 100)
      : 0,
    contributor_count: c.contributor_count ?? 0,
  }));

  const sorted = [...campaignsWithGoal].sort((a, b) => {
    const av = a[sortField] ?? 0;
    const bv = b[sortField] ?? 0;
    return sortDir === 'asc' ? av - bv : bv - av;
  });

  const benchmarkComparisons = benchmarks?.comparisons || [];
  const avgCreatorGoalPct = benchmarkComparisons.length > 0
    ? benchmarkComparisons.reduce((s, c) => s + (c.creator?.goal_pct || 0), 0) / benchmarkComparisons.length
    : 0;
  const avgPlatformGoalPct = benchmarkComparisons.filter((c) => c.platform).length > 0
    ? benchmarkComparisons.filter((c) => c.platform).reduce((s, c) => s + (c.platform?.avg_goal_pct || 0), 0) /
      benchmarkComparisons.filter((c) => c.platform).length
    : 0;

  const avgCreatorTimeFirst = benchmarkComparisons.filter((c) => c.creator?.time_to_first_contribution_hours !== null && c.creator?.time_to_first_contribution_hours !== undefined).length > 0
    ? benchmarkComparisons.filter((c) => c.creator?.time_to_first_contribution_hours !== null && c.creator?.time_to_first_contribution_hours !== undefined)
        .reduce((s, c) => s + c.creator.time_to_first_contribution_hours, 0) /
      benchmarkComparisons.filter((c) => c.creator?.time_to_first_contribution_hours !== null && c.creator?.time_to_first_contribution_hours !== undefined).length
    : null;
  const avgPlatformTimeFirst = benchmarkComparisons.filter((c) => c.platform?.avg_time_to_first_contribution_hours !== null && c.platform?.avg_time_to_first_contribution_hours !== undefined).length > 0
    ? benchmarkComparisons.filter((c) => c.platform?.avg_time_to_first_contribution_hours !== null && c.platform?.avg_time_to_first_contribution_hours !== undefined)
        .reduce((s, c) => s + c.platform.avg_time_to_first_contribution_hours, 0) /
      benchmarkComparisons.filter((c) => c.platform?.avg_time_to_first_contribution_hours !== null && c.platform?.avg_time_to_first_contribution_hours !== undefined).length
    : null;

  return (
    <main className="container" style={{ paddingTop: '2rem', paddingBottom: '3rem' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '0.5rem', marginBottom: '1.25rem' }}>
        <h1 style={{ fontSize: '1.6rem', fontWeight: 800 }}>Creator Analytics</h1>
        <Link to="/dashboard?tab=analytics" style={{ color: 'var(--color-accent)', fontWeight: 600, fontSize: '0.9rem' }}>
          Back to Dashboard
        </Link>
      </div>

      {error && <p className="alert alert--error">{error}</p>}
      {loading && <p style={{ color: 'var(--color-text-hint)' }}>{t('common.loading')}</p>}

      {overview && !loading && (
        <>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(150px,1fr))', gap: '0.75rem', marginBottom: '1.25rem' }}>
            <StatCard label="Total Raised" value={`${Number(overview.total_raised).toLocaleString()}`} />
            <StatCard label="Unique Contributors" value={overview.unique_contributors} />
            <StatCard label="Total Campaigns" value={overview.total_campaigns} />
            <StatCard label="Active" value={overview.active_campaigns} />
            <StatCard label="Completed" value={overview.completed_campaigns} />
            <StatCard label="Expired" value={overview.expired_campaigns} />
            <StatCard label="Avg Contribution" value={Number(overview.avg_contribution).toLocaleString(undefined, { maximumFractionDigits: 2 })} />
            <StatCard label="7-Day Velocity" value={Number(overview.velocity_7d_avg).toLocaleString(undefined, { maximumFractionDigits: 2 })} />
            <StatCard label="30-Day Velocity" value={Number(overview.velocity_30d_avg).toLocaleString(undefined, { maximumFractionDigits: 2 })} />
          </div>

          {overview.best_performing_campaign && (
            <div className="campaign-card" style={{ minHeight: 'auto', marginBottom: '1.25rem' }}>
              <strong style={{ display: 'block', marginBottom: '0.4rem' }}>Best Performing Campaign</strong>
              <Link
                to={`/campaigns/${overview.best_performing_campaign.id}`}
                style={{ color: 'var(--color-accent)', fontWeight: 600 }}
              >
                {overview.best_performing_campaign.title}
              </Link>
              <div style={{ fontSize: '0.88rem', marginTop: '0.25rem', color: 'var(--color-text-secondary)' }}>
                {overview.best_performing_campaign.goal_pct}% of goal reached
                {' · '}
                {Number(overview.best_performing_campaign.raised_amount).toLocaleString()} / {Number(overview.best_performing_campaign.target_amount).toLocaleString()} {overview.best_performing_campaign.asset_type}
              </div>
            </div>
          )}

          <div className="campaign-card" style={{ minHeight: 'auto', marginBottom: '1.25rem' }}>
            <strong style={{ display: 'block', marginBottom: '0.6rem' }}>30-Day Velocity Trend</strong>
            <React.Suspense fallback={<p style={{ color: 'var(--color-text-hint)', fontSize: '0.9rem' }}>Loading chart…</p>}>
              <MiniLineChart data={overview.velocity_30d_avg ? [{ day: '30d avg', total_amount: overview.velocity_30d_avg }, { day: '7d avg', total_amount: overview.velocity_7d_avg }] : []} dataKey="total_amount" label="Amount" />
            </React.Suspense>
          </div>
        </>
      )}

      {campaigns.length > 0 && !loading && (
        <div className="campaign-card" style={{ minHeight: 'auto', marginBottom: '1.25rem' }}>
          <strong style={{ display: 'block', marginBottom: '0.6rem' }}>Campaign Performance</strong>
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.82rem' }}>
              <thead>
                <tr style={{ borderBottom: '2px solid var(--color-border)', textAlign: 'left' }}>
                  {[
                    { key: 'title', label: 'Campaign' },
                    { key: 'goal_pct', label: 'Goal %' },
                    { key: 'raised_amount', label: 'Raised' },
                    { key: 'target_amount', label: 'Target' },
                    { key: 'contributor_count', label: 'Contributors' },
                    { key: 'status', label: 'Status' },
                  ].map(({ key, label }) => (
                    <th
                      key={key}
                      onClick={() => key !== 'title' && key !== 'status' && toggleSort(key)}
                      style={{
                        padding: '0.4rem 0.5rem',
                        cursor: key !== 'title' && key !== 'status' ? 'pointer' : 'default',
                        userSelect: 'none',
                      }}
                    >
                      {label}
                      {sortField === key && (sortDir === 'asc' ? ' ↑' : ' ↓')}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {sorted.map((c) => (
                  <tr key={c.id} style={{ borderBottom: '1px solid var(--color-border-lighter)' }}>
                    <td style={{ padding: '0.4rem 0.5rem' }}>
                      <Link to={`/dashboard/analytics/${c.id}`} style={{ color: 'var(--color-accent)', fontWeight: 600 }}>
                        {c.title}
                      </Link>
                    </td>
                    <td style={{ padding: '0.4rem 0.5rem' }}>{c.goal_pct.toFixed(1)}%</td>
                    <td style={{ padding: '0.4rem 0.5rem' }}>{Number(c.raised_amount).toLocaleString()}</td>
                    <td style={{ padding: '0.4rem 0.5rem' }}>{Number(c.target_amount).toLocaleString()}</td>
                    <td style={{ padding: '0.4rem 0.5rem' }}>{c.contributor_count}</td>
                    <td style={{ padding: '0.4rem 0.5rem' }}>{c.status}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {benchmarks && !loading && benchmarkComparisons.length > 0 && (
        <div className="campaign-card" style={{ minHeight: 'auto' }}>
          <strong style={{ display: 'block', marginBottom: '0.6rem' }}>Platform Benchmarks</strong>
          <p style={{ fontSize: '0.82rem', color: 'var(--color-text-hint)', marginBottom: '0.75rem' }}>
            Your campaign averages compared to anonymised platform medians (minimum 10 campaigns per bracket).
          </p>
          <BenchmarkBar creator={avgCreatorGoalPct} platform={avgPlatformGoalPct} label="Avg Goal % Reached" />
          {avgCreatorTimeFirst !== null && avgPlatformTimeFirst !== null && (
            <BenchmarkBar creator={avgCreatorTimeFirst} platform={avgPlatformTimeFirst} label="Avg Time to First Contribution (hours)" />
          )}
          <div style={{ marginTop: '0.75rem', overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.82rem' }}>
              <thead>
                <tr style={{ borderBottom: '2px solid var(--color-border)', textAlign: 'left' }}>
                  <th style={{ padding: '0.3rem 0.5rem' }}>Campaign</th>
                  <th style={{ padding: '0.3rem 0.5rem' }}>Bracket</th>
                  <th style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>Your Goal %</th>
                  <th style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>Platform Avg %</th>
                  <th style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>Your Time (hrs)</th>
                  <th style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>Platform Time (hrs)</th>
                  <th style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>Your Contributors</th>
                  <th style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>Platform Avg</th>
                </tr>
              </thead>
              <tbody>
                {benchmarkComparisons.map((bm) => (
                  <tr key={bm.campaign_id} style={{ borderBottom: '1px solid var(--color-border-lighter)' }}>
                    <td style={{ padding: '0.3rem 0.5rem' }}>
                      <Link to={`/dashboard/analytics/${bm.campaign_id}`} style={{ color: 'var(--color-accent)' }}>
                        {campaigns.find((c) => c.id === bm.campaign_id)?.title || bm.campaign_id}
                      </Link>
                    </td>
                    <td style={{ padding: '0.3rem 0.5rem' }}>{bm.bracket}</td>
                    <td style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>{bm.creator?.goal_pct?.toFixed(1) ?? '—'}</td>
                    <td style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>{bm.platform?.avg_goal_pct?.toFixed(1) ?? '—'}</td>
                    <td style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>{bm.creator?.time_to_first_contribution_hours?.toFixed(1) ?? '—'}</td>
                    <td style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>{bm.platform?.avg_time_to_first_contribution_hours?.toFixed(1) ?? '—'}</td>
                    <td style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>{bm.creator?.contributor_count ?? '—'}</td>
                    <td style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>{bm.platform?.avg_contributor_count?.toFixed(1) ?? '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </main>
  );
}

import React, { useEffect, useState, useCallback } from 'react';
import { Link, useParams, Navigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import { api } from '../services/api';
import VelocityWidget from '../components/campaign/VelocityWidget';

import {
  LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid,
  PieChart, Pie, Cell, BarChart, Bar,
} from 'recharts';

const DONUT_COLORS = ['#7c3aed', '#22c55e', '#f59e0b', '#ef4444', '#3b82f6', '#ec4899', '#14b8a6'];

function StatCard({ label, value }) {
  return (
    <div className="campaign-card" style={{ minHeight: 'auto', padding: '0.6rem 0.75rem' }}>
      <strong style={{ fontSize: '1rem' }}>{value}</strong>
      <div style={{ fontSize: '0.78rem', color: 'var(--color-text-hint)' }}>{label}</div>
    </div>
  );
}

export default function CreatorCampaignAnalytics() {
  const { campaignId } = useParams();
  const { user, ready } = useAuth();
  const { t } = useTranslation();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [exporting, setExporting] = useState(false);

  const isCreator = user?.role === 'creator' || user?.role === 'admin';

  useEffect(() => {
    if (!user || !isCreator || !campaignId) return;
    setLoading(true);
    api
      .getCreatorCampaignAnalytics(campaignId)
      .then(setData)
      .catch((err) => setError(err.message || 'Failed to load campaign analytics'))
      .finally(() => setLoading(false));
  }, [user, isCreator, campaignId]);

  const handleExport = useCallback(async () => {
    if (!campaignId) return;
    setExporting(true);
    setError('');
    try {
      const { blob, filename } = await api.exportCreatorCampaignData(campaignId);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    } catch (err) {
      if (err.status === 429) {
        setError('Daily export limit reached (5/day). Try again tomorrow.');
      } else {
        setError(err.message || 'Export failed');
      }
    } finally {
      setExporting(false);
    }
  }, [campaignId]);

  if (!ready) return null;
  if (!user) return <Navigate to="/login" replace />;
  if (!isCreator) return <Navigate to="/dashboard" replace />;

  const retention = data?.contributor_retention;
  const retentionData = retention
    ? [
        { name: 'New', value: retention.new },
        { name: 'Returning', value: retention.returning },
      ]
    : [];

  const assetMixData = (data?.asset_mix || []).map((a) => ({
    name: a.asset,
    value: Number(a.total),
    count: a.count,
  }));

  const milestonesData = (data?.milestones || []).map((m) => ({
    name: m.title,
    progress: m.progress_pct,
    target: m.percentage,
    status: m.status,
  }));

  return (
    <main className="container" style={{ paddingTop: '2rem', paddingBottom: '3rem' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '0.5rem', marginBottom: '1.25rem' }}>
        <h1 style={{ fontSize: '1.6rem', fontWeight: 800 }}>
          {data?.campaign?.title || 'Campaign Analytics'}
        </h1>
        <div style={{ display: 'flex', gap: '1rem', alignItems: 'center' }}>
          <button type="button" className="btn-secondary" onClick={handleExport} disabled={exporting}>
            {exporting ? 'Exporting…' : 'Export CSV'}
          </button>
          <Link to="/dashboard/analytics" style={{ color: 'var(--color-accent)', fontWeight: 600, fontSize: '0.9rem' }}>
            ← Back to Analytics
          </Link>
        </div>
      </div>

      {error && <p className="alert alert--error">{error}</p>}
      {loading && <p style={{ color: 'var(--color-text-hint)' }}>{t('common.loading')}</p>}

      {campaignId && (
        <div style={{ marginBottom: '1.5rem' }}>
          <VelocityWidget campaignId={campaignId} />
        </div>
      )}

      {data && !loading && (
        <>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(150px,1fr))', gap: '0.75rem', marginBottom: '1.25rem' }}>
            <StatCard label="Raised" value={`${Number(data.campaign.raised_amount).toLocaleString()} ${data.campaign.asset_type}`} />
            <StatCard label="Target" value={`${Number(data.campaign.target_amount).toLocaleString()} ${data.campaign.asset_type}`} />
            <StatCard label="Goal %" value={`${Number(data.campaign.target_amount) > 0 ? Math.min(100, (Number(data.campaign.raised_amount) / Number(data.campaign.target_amount)) * 100).toFixed(1) : 0}%`} />
            <StatCard label="Contributors" value={retention?.total || 0} />
            <StatCard label="Retention Rate" value={`${retention?.retention_rate || 0}%`} />
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(300px,1fr))', gap: '1.25rem' }}>
            <div className="campaign-card">
              <h3 style={{ marginBottom: '1rem', fontSize: '1.1rem' }}>Asset Mix</h3>
              {assetMixData.length > 0 ? (
                <div style={{ width: '100%', height: '220px' }}>
                  <ResponsiveContainer>
                    <PieChart>
                      <Pie data={assetMixData} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={80} label>
                        {assetMixData.map((_, index) => (
                          <Cell key={`cell-${index}`} fill={DONUT_COLORS[index % DONUT_COLORS.length]} />
                        ))}
                      </Pie>
                      <Tooltip />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              ) : (
                <p style={{ color: 'var(--color-text-hint)' }}>No contribution data</p>
              )}
            </div>

            <div className="campaign-card">
              <h3 style={{ marginBottom: '1rem', fontSize: '1.1rem' }}>Milestone Progress</h3>
              {milestonesData.length > 0 ? (
                <div style={{ width: '100%', height: '220px' }}>
                  <ResponsiveContainer>
                    <BarChart data={milestonesData} layout="vertical" margin={{ top: 5, right: 20, left: 20, bottom: 5 }}>
                      <CartesianGrid strokeDasharray="3 3" />
                      <XAxis type="number" domain={[0, 100]} />
                      <YAxis dataKey="name" type="category" width={80} />
                      <Tooltip />
                      <Bar dataKey="progress" fill="#22c55e" />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              ) : (
                <p style={{ color: 'var(--color-text-hint)' }}>No milestones defined</p>
              )}
            </div>
          </div>
        </>
      )}
    </main>
  );
}

import React, { useEffect, useState, useCallback } from 'react';
import { Link, Navigate, useSearchParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import { api } from '../services/api';
import KycPrompt from '../components/KycPrompt';
import VerificationBadge from '../components/VerificationBadge';
import CampaignStatusBadge from '../components/CampaignStatusBadge';
import ContributorDashboard from '../components/ContributorDashboard';
import SubscriptionsPanel from '../components/SubscriptionsPanel';
import FollowedCampaigns from '../components/FollowedCampaigns';
import DepositModal from '../components/DepositModal';
import ApiKeysPanel from '../components/ApiKeysPanel';
import { stellarExpertTxUrl, stellarExpertAccountUrl } from '../config/stellar';
import ThankYouModal from '../components/ThankYouModal';

const BackerInsightsCard = React.lazy(() => import('../components/BackerInsightsCard'));
const MiniLineChart = React.lazy(() => import('../components/MiniLineChart'));

const TABS = [
  { id: 'campaigns', labelKey: 'dashboard.tabs.campaigns' },
  { id: 'contributions', labelKey: 'dashboard.tabs.contributions' },
  { id: 'subscriptions', labelKey: 'dashboard.tabs.subscriptions' },
  { id: 'following', labelKey: 'dashboard.tabs.following' },
  { id: 'analytics', labelKey: 'dashboard.tabs.analytics' },
  { id: 'api-keys', labelKey: 'dashboard.tabs.apiKeys' },
];

function progressPct(campaign) {
  if (!Number(campaign.target_amount)) return 0;
  return Math.min(100, (Number(campaign.raised_amount) / Number(campaign.target_amount)) * 100);
}

function exportCSV(rows, filename) {
  if (!rows.length) return;
  const keys = Object.keys(rows[0]);
  const csv = [
    keys.join(','),
    ...rows.map((r) => keys.map((k) => JSON.stringify(r[k] ?? '')).join(',')),
  ].join('\n');
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
  a.download = filename;
  a.click();
}

function daysUntil(dateStr) {
  if (!dateStr) return null;
  return Math.ceil((new Date(dateStr) - new Date()) / (1000 * 60 * 60 * 24));
}

function daysSince(dateStr) {
  if (!dateStr) return null;
  return Math.floor((new Date() - new Date(dateStr)) / (1000 * 60 * 60 * 24));
}

function buildActionItems(campaigns, milestonesByCampaign, lastUpdateByCampaign) {
  const items = [];

  campaigns.forEach((campaign) => {
    if (campaign.status === 'draft') {
      items.push({
        key: `draft-${campaign.id}`,
        priority: 2,
        campaignId: campaign.id,
        title: `"${campaign.title}" is still a draft`,
        detail: 'Publish it so backers can find and support it.',
      });
      return;
    }

    if (campaign.status !== 'active') return;

    const approvedMilestones = (milestonesByCampaign[campaign.id] || []).filter(
      (m) => m.status === 'approved'
    );
    if (approvedMilestones.length > 0) {
      items.push({
        key: `withdraw-${campaign.id}`,
        priority: 0,
        campaignId: campaign.id,
        title: `Funds ready to withdraw for "${campaign.title}"`,
        detail: `${approvedMilestones.length} approved milestone${approvedMilestones.length > 1 ? 's' : ''} awaiting release.`,
      });
    }

    const lastUpdate = lastUpdateByCampaign[campaign.id];
    const campaignAgeDays = daysSince(campaign.created_at) ?? 0;
    const sinceUpdateDays = lastUpdate ? daysSince(lastUpdate.created_at) : campaignAgeDays;
    if (campaignAgeDays >= 7 && (sinceUpdateDays === null || sinceUpdateDays >= 10)) {
      items.push({
        key: `update-${campaign.id}`,
        priority: 1,
        campaignId: campaign.id,
        title: `"${campaign.title}" needs an update`,
        detail: lastUpdate
          ? `Last update was ${sinceUpdateDays} days ago. Backers stay engaged when they hear from you.`
          : 'No updates posted yet. Share your progress with backers.',
      });
    }

    const pct = progressPct(campaign);
    const deadlineDays = daysUntil(campaign.deadline);
    if (deadlineDays !== null && deadlineDays >= 0 && deadlineDays <= 7 && pct < 75) {
      items.push({
        key: `deadline-${campaign.id}`,
        priority: 1,
        campaignId: campaign.id,
        title: `"${campaign.title}" is running out of time`,
        detail: `${deadlineDays} day${deadlineDays === 1 ? '' : 's'} left at ${pct.toFixed(0)}% funded. Consider sharing it again.`,
      });
    }

    if (campaign.is_hidden) {
      items.push({
        key: `hidden-${campaign.id}`,
        priority: 2,
        campaignId: campaign.id,
        title: `"${campaign.title}" is hidden from discovery`,
        detail: 'Make it visible again if you want new backers to find it.',
      });
    }
  });

  return items.sort((a, b) => a.priority - b.priority);
}

function ActionCenter({ campaigns }) {
  const [milestonesByCampaign, setMilestonesByCampaign] = useState({});
  const [lastUpdateByCampaign, setLastUpdateByCampaign] = useState({});
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    const activeCampaigns = campaigns.filter((c) => c.status === 'active');
    if (activeCampaigns.length === 0) {
      setLoaded(true);
      return;
    }
    let cancelled = false;
    Promise.all(
      activeCampaigns.map((c) =>
        Promise.all([
          api.getMilestones(c.id).catch(() => []),
          api.getCampaignUpdates(c.id, { limit: 1 }).catch(() => null),
        ]).then(([milestones, updatesRes]) => [c.id, milestones, updatesRes])
      )
    ).then((results) => {
      if (cancelled) return;
      const milestoneMap = {};
      const updateMap = {};
      results.forEach(([id, milestones, updatesRes]) => {
        milestoneMap[id] = milestones || [];
        const updates = Array.isArray(updatesRes) ? updatesRes : updatesRes?.updates;
        if (updates && updates.length > 0) updateMap[id] = updates[0];
      });
      setMilestonesByCampaign(milestoneMap);
      setLastUpdateByCampaign(updateMap);
      setLoaded(true);
    });
    return () => {
      cancelled = true;
    };
  }, [campaigns]);

  if (!loaded) return null;

  const items = buildActionItems(campaigns, milestonesByCampaign, lastUpdateByCampaign);
  if (items.length === 0) return null;

  return (
    <div className="campaign-card" style={{ marginBottom: '1rem', minHeight: 'auto' }}>
      <strong style={{ fontSize: '1rem' }}>What needs your attention</strong>
      <div style={{ display: 'grid', gap: '0.6rem', marginTop: '0.75rem' }}>
        {items.map((item) => (
          <Link
            key={item.key}
            to={`/campaigns/${item.campaignId}`}
            style={{
              display: 'block',
              padding: '0.65rem 0.85rem',
              borderRadius: '8px',
              border: '1px solid var(--color-border-lighter)',
              textDecoration: 'none',
              color: 'inherit',
            }}
          >
            <div style={{ fontWeight: 700, fontSize: '0.9rem' }}>{item.title}</div>
            <div style={{ fontSize: '0.82rem', color: 'var(--color-text-secondary)', marginTop: '0.15rem' }}>
              {item.detail}
            </div>
          </Link>
        ))}
      </div>
    </div>
  );
}

function MilestoneFunnel({ campaignId }) {
  const { t } = useTranslation();
  const [milestones, setMilestones] = useState(null);
  const [campaign, setCampaign] = useState(null);

  useEffect(() => {
    Promise.all([api.getMilestones(campaignId), api.getCampaign(campaignId)])
      .then(([ms, c]) => {
        setMilestones(ms);
        setCampaign(c);
      })
      .catch(() => {});
  }, [campaignId]);

  if (!milestones || milestones.length === 0) return null;

  const raised = Number(campaign?.raised_amount || 0);
  const target = Number(campaign?.target_amount || 1);

  return (
    <div style={{ marginTop: '0.75rem' }}>
      <strong style={{ fontSize: '0.9rem' }}>{t('dashboard.milestoneFunnel')}</strong>
      {milestones.map((m) => {
        const threshold = (Number(m.release_percentage) / 100) * target;
        const pct = Math.min(100, (raised / threshold) * 100);
        return (
          <div key={m.id} style={{ marginTop: '0.5rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.82rem' }}>
              <span>{m.title}</span>
              <span style={{ color: 'var(--color-text-hint)' }}>
                {m.release_percentage}% ·{' '}
                {t('dashboard.percentFunded', { percent: pct.toFixed(0) })}
              </span>
            </div>
            <div
              style={{
                background: 'var(--color-surface)',
                borderRadius: 99,
                height: 6,
                marginTop: 3,
              }}
            >
              <div
                style={{
                  width: `${pct}%`,
                  height: 6,
                  borderRadius: 99,
                  background: m.status === 'released' ? '#22c55e' : 'var(--color-accent)',
                }}
              />
            </div>
          </div>
        );
      })}
    </div>
  );
}

export default function Dashboard() {
  const { user, ready, updateUser } = useAuth();
  const { t } = useTranslation();
  const [searchParams, setSearchParams] = useSearchParams();
  const tabParam = searchParams.get('tab');
  const activeTab =
    tabParam === 'contributions'
      ? 'contributions'
      : tabParam === 'subscriptions'
        ? 'subscriptions'
        : tabParam === 'following'
          ? 'following'
          : tabParam === 'referrals'
            ? 'referrals'
            : tabParam === 'analytics'
              ? 'analytics'
              : tabParam === 'api-keys'
                ? 'api-keys'
                : 'campaigns';

  const [stats, setStats] = useState(null);
  const [campaigns, setCampaigns] = useState([]);
  const [loadingCampaigns, setLoadingCampaigns] = useState(true);
  const [campaignsPage, setCampaignsPage] = useState(1);
  const [campaignsTotalPages, setCampaignsTotalPages] = useState(1);
  const [campaignsTotal, setCampaignsTotal] = useState(0);
  const [isCampaignsPageLoading, setIsCampaignsPageLoading] = useState(false);
  const [loadingContributions, setLoadingContributions] = useState(false);
  const [error, setError] = useState('');
  const [balance, setBalance] = useState(null);
  const [balanceLoading, setBalanceLoading] = useState(true);
  const [showDepositModal, setShowDepositModal] = useState(false);
  const [dashAnalytics, setDashAnalytics] = useState(null);
  const [analyticsLoading, setAnalyticsLoading] = useState(false);
  const [selectedCampaignId, setSelectedCampaignId] = useState(null);
  const [campaignAnalytics, setCampaignAnalytics] = useState(null);
  const [campaignContributors, setCampaignContributors] = useState(null);
  const [campaignBackers, setCampaignBackers] = useState(null);
  const [referralData, setReferralData] = useState({});
  const [referralLoading, setReferralLoading] = useState(false);
  const [exportingCampaignId, setExportingCampaignId] = useState(null);
  const [bulkThankYouCampaignId, setBulkThankYouCampaignId] = useState(null);
  const [individualThankYouContribution, setIndividualThankYouContribution] = useState(null);
  const [campaignContributions, setCampaignContributions] = useState([]);
  const [contributionsLoading, setContributionsLoading] = useState(false);
  const [thankYouSent, setThankYouSent] = useState('');
  const [togglingVisibility, setTogglingVisibility] = useState(null);

  const isCreator = user?.role === 'creator' || user?.role === 'admin';

  const visibleTabs = isCreator
    ? [...TABS, { id: 'referrals', labelKey: 'dashboard.tabs.referrals' }]
    : TABS.filter((t) => t.id !== 'analytics');

  const kycRequired =
    user?.kyc_required_for_campaigns ??
    String(import.meta.env.VITE_KYC_REQUIRED_FOR_CAMPAIGNS ?? 'true').toLowerCase() !== 'false';

  useEffect(() => {
    if (!user) return;
    setLoadingCampaigns(true);
    setLoadingContributions(true);
    setError('');

    api
      .getMyBalance()
      .then((d) => setBalance(d.balance))
      .catch(() => {})
      .finally(() => setBalanceLoading(false));

    if (isCreator) {
      Promise.all([api.getMe(), api.getMyStats()])
        .then(([me, s]) => {
          updateUser(me);
          setStats(s);
          // pre-fetch dashboard analytics for the analytics tab
          api
            .getUserDashboardAnalytics()
            .then(setDashAnalytics)
            .catch(() => {});
        })
        .catch((err) => setError(err.message || 'Could not load dashboard'))
        .finally(() => {
          setLoadingCampaigns(false);
          setLoadingContributions(false);
        });
    } else {
      setLoadingCampaigns(false);
      setLoadingContributions(false);
    }
  }, [isCreator, user, updateUser]);

  useEffect(() => {
    if (!user || !isCreator) return;
    setIsCampaignsPageLoading(true);
    api
      .getMyCampaigns({ page: campaignsPage, limit: 20 })
      .then((res) => {
        if (res.data && res.pagination) {
          setCampaigns(res.data);
          setCampaignsTotalPages(res.pagination.totalPages);
          setCampaignsTotal(res.pagination.total);
        } else {
          setCampaigns(res);
          setCampaignsTotalPages(1);
          setCampaignsTotal(res.length || 0);
        }
      })
      .catch((err) => setError(err.message || 'Could not load campaigns'))
      .finally(() => {
        setLoadingCampaigns(false);
        setIsCampaignsPageLoading(false);
      });
  }, [isCreator, user, campaignsPage]);

  const loadCampaignAnalytics = useCallback((id) => {
    setSelectedCampaignId(id);
    setCampaignAnalytics(null);
    setCampaignContributors(null);
    setCampaignContributions([]);
    setAnalyticsLoading(true);
    setContributionsLoading(true);
    Promise.all([
      api.getCampaignAnalytics(id),
      api.getCampaignAnalyticsContributors(id),
      api.getContributions(id, { limit: 100 }),
    ])
      .then(([a, c, ctr]) => {
        setCampaignAnalytics(a);
        setCampaignContributors(c);
        setCampaignContributions(ctr.contributions || []);
      })
      .catch(() => {})
      .finally(() => {
        setAnalyticsLoading(false);
        setContributionsLoading(false);
      });
  }, []);

  const handleExportContributions = useCallback(async (campaign) => {
    setError('');
    setExportingCampaignId(campaign.id);
    try {
      const { blob, filename } = await api.exportCampaignContributions(campaign.id);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    } catch (err) {
      setError(err.message || 'Could not export campaign contributors');
    } finally {
      setExportingCampaignId(null);
    }
  }, []);

  const handleToggleVisibility = useCallback(async (campaign) => {
    setError('');
    setTogglingVisibility(campaign.id);
    try {
      const newHidden = !campaign.is_hidden;
      await api.toggleCampaignVisibility(campaign.id, newHidden);
      setCampaigns((prev) =>
        prev.map((c) =>
          c.id === campaign.id ? { ...c, is_hidden: newHidden } : c
        )
      );
    } catch (err) {
      setError(err.message || 'Could not change campaign visibility');
    } finally {
      setTogglingVisibility(null);
    }
  }, []);

  useEffect(() => {
    if (!isCreator || activeTab !== 'referrals' || !campaigns.length) return;
    setReferralLoading(true);
    Promise.all(
      campaigns.map((c) =>
        api
          .getReferralLeaderboard(c.id)
          .then((rows) => [c.id, rows])
          .catch(() => [c.id, []])
      )
    )
      .then((results) => {
        const data = {};
        results.forEach(([id, rows]) => {
          data[id] = rows;
        });
        setReferralData(data);
      })
      .catch(() => {})
      .finally(() => setReferralLoading(false));
  }, [isCreator, activeTab, campaigns]);

  useEffect(() => {
    const kycParam = searchParams.get('kyc');
    if (!user || (kycParam !== 'returned' && kycParam !== 'started')) return undefined;

    let cancelled = false;
    let attempts = 0;
    const maxAttempts = 40;

    async function pollKycStatus() {
      while (!cancelled && attempts < maxAttempts) {
        attempts += 1;
        try {
          const status = await api.getKycStatus();
          if (status.status === 'verified' || status.status === 'rejected') {
            const me = await api.getMe();
            updateUser(me);
            setSearchParams(
              (params) => {
                params.delete('kyc');
                params.delete('reference');
                return params;
              },
              { replace: true }
            );
            break;
          }
        } catch {
          // keep polling until Persona webhook lands
        }
        await new Promise((resolve) => setTimeout(resolve, 3000));
      }
    }

    pollKycStatus();
    return () => {
      cancelled = true;
    };
  }, [user, searchParams, updateUser, setSearchParams]);

  function setTab(tabId) {
    if (tabId === 'contributions') {
      setSearchParams({ tab: 'contributions' });
    } else if (tabId === 'subscriptions') {
      setSearchParams({ tab: 'subscriptions' });
    } else if (tabId === 'following') {
      setSearchParams({ tab: 'following' });
    } else if (tabId === 'analytics') {
      setSearchParams({ tab: 'analytics' });
    } else if (tabId === 'referrals') {
      setSearchParams({ tab: 'referrals' });
    } else if (tabId === 'api-keys') {
      setSearchParams({ tab: 'api-keys' });
    } else {
      setSearchParams({});
    }
  }

  if (!ready) {
    return (
      <main className="container" style={{ paddingTop: '2rem', paddingBottom: '3rem' }}>
        <p style={{ color: 'var(--color-text-hint)' }}>{t('dashboard.restoringSession')}</p>
      </main>
    );
  }
  if (!user) return <Navigate to="/login" replace />;

  const loading = activeTab === 'campaigns' ? loadingCampaigns : loadingContributions;

  return (
    <main className="container" style={{ paddingTop: '2rem', paddingBottom: '3rem' }}>
      <h1 style={{ fontSize: '1.6rem', fontWeight: 800, marginBottom: '1rem' }}>
        {t('dashboard.title')}
      </h1>

      <div className="campaign-card" style={{ marginBottom: '1rem', minHeight: 'auto' }}>
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            gap: '0.75rem',
            flexWrap: 'wrap',
            alignItems: 'center',
          }}
        >
          <div>
            <strong>{t('dashboard.walletBalance')}</strong>
            <div
              style={{ color: 'var(--color-text-hint)', fontSize: '0.88rem', marginTop: '0.2rem' }}
            >
              {balanceLoading
                ? t('common.loading')
                : balance
                  ? Object.entries(balance)
                      .filter(([, v]) => Number(v) > 0)
                      .map(([code, val]) => `${Number(val).toLocaleString()} ${code}`)
                      .join(' · ') || t('dashboard.noFunds')
                  : t('dashboard.noFunds')}
              {user?.wallet_public_key && (
                <span style={{ marginLeft: '0.5rem' }}>
                  ·{' '}
                  <a
                    href={stellarExpertAccountUrl(user.wallet_public_key)}
                    target="_blank"
                    rel="noopener noreferrer"
                    style={{ color: 'var(--color-accent)' }}
                  >
                    {t('dashboard.viewOnStellarExpert')}
                  </a>
                </span>
              )}
            </div>
          </div>
          <button type="button" className="btn-primary" onClick={() => setShowDepositModal(true)}>
            {t('dashboard.addFunds')}
          </button>
        </div>
      </div>

      <div
        role="tablist"
        aria-label={t('dashboard.sectionsLabel')}
        style={{
          display: 'flex',
          gap: '0.5rem',
          marginBottom: '1.25rem',
          borderBottom: '1px solid var(--color-border)',
          paddingBottom: '0.5rem',
        }}
      >
        {visibleTabs.map((tab) => (
          <button
            key={tab.id}
            type="button"
            role="tab"
            aria-selected={activeTab === tab.id}
            onClick={() => setTab(tab.id)}
            style={{
              padding: '0.5rem 1rem',
              borderRadius: '8px',
              border: 'none',
              cursor: 'pointer',
              fontWeight: 600,
              fontSize: '0.9rem',
              background: activeTab === tab.id ? 'var(--color-accent)' : 'transparent',
              color: activeTab === tab.id ? 'var(--color-bg)' : 'var(--color-text-secondary)',
            }}
          >
            {tab.label ? tab.label : t(tab.labelKey)}
          </button>
        ))}
      </div>

      {error && <p className="alert alert--error">{error}</p>}

      {activeTab === 'campaigns' && (
        <section role="tabpanel" aria-labelledby="tab-campaigns">
          {loading ? (
            <p style={{ color: 'var(--color-text-hint)' }}>{t('dashboard.loadingCampaigns')}</p>
          ) : !isCreator ? (
            <p className="alert alert--info">
              {t('dashboard.noCreatedCampaigns')}{' '}
              <Link to="/campaigns/new" style={{ color: 'var(--color-accent)', fontWeight: 600 }}>
                {t('home.startCampaign')}
              </Link>{' '}
              {t('dashboard.noCreatedCampaignsHint')}
            </p>
          ) : (
            <>
              <div className="campaign-card" style={{ marginBottom: '1rem', minHeight: 'auto' }}>
                <div
                  style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    gap: '0.75rem',
                    flexWrap: 'wrap',
                    alignItems: 'center',
                  }}
                >
                  <div>
                    <strong>{t('dashboard.identityVerification')}</strong>
                    <div
                      style={{
                        color: 'var(--color-text-hint)',
                        fontSize: '0.88rem',
                        marginTop: '0.2rem',
                      }}
                    >
                      {t('dashboard.status')}: {user?.kyc_status || t('dashboard.unverified')}
                      {user?.kyc_completed_at
                        ? ` • ${t('dashboard.completedOn', { date: new Date(user.kyc_completed_at).toLocaleDateString() })}`
                        : ''}
                    </div>
                  </div>
                  <VerificationBadge status={user?.verification_status || user?.kyc_status} tier={user?.verification_tier} showTier />
                </div>
                {kycRequired && user?.kyc_status !== 'verified' && (
                  <div style={{ marginTop: '0.85rem' }}>
                    <KycPrompt onUserUpdate={updateUser} />
                  </div>
                )}
              </div>

              <div
                style={{
                  display: 'grid',
                  gridTemplateColumns: 'repeat(auto-fit,minmax(180px,1fr))',
                  gap: '0.75rem',
                  marginBottom: '1rem',
                }}
              >
                <div className="campaign-card">
                  <strong>{stats?.total_campaigns || 0}</strong>
                  <div>{t('dashboard.totalCampaigns')}</div>
                </div>
                <div className="campaign-card">
                  <strong>{Number(stats?.total_raised || 0).toLocaleString()}</strong>
                  <div>{t('dashboard.totalRaised')}</div>
                </div>
                <div className="campaign-card">
                  <strong>{stats?.active_campaigns || 0}</strong>
                  <div>{t('dashboard.active')}</div>
                </div>
                <div className="campaign-card">
                  <strong>{stats?.funded_campaigns || 0}</strong>
                  <div>{t('dashboard.funded')}</div>
                </div>
              </div>

              <div style={{ marginBottom: '1rem' }}>
                <Link to="/campaigns/new" style={{ color: 'var(--color-accent)', fontWeight: 600 }}>
                  {t('dashboard.createNewCampaign')}
                </Link>
              </div>

              {campaigns.length > 0 && <ActionCenter campaigns={campaigns} />}

              {campaigns.length === 0 ? (
                <p className="alert alert--info">{t('dashboard.noCampaigns')}</p>
              ) : (
                <>
                <div style={{ display: 'grid', gap: '0.75rem', opacity: isCampaignsPageLoading ? 0.5 : 1, transition: 'opacity 0.2s' }}>
                  {campaigns.map((campaign) => {
                    const pct = progressPct(campaign).toFixed(1);
                    return (
                      <div
                        key={campaign.id}
                        className="campaign-card"
                        style={campaign.is_hidden ? { opacity: 0.6 } : undefined}
                      >
                        <div
                          style={{
                            display: 'flex',
                            justifyContent: 'space-between',
                            gap: '0.5rem',
                            flexWrap: 'wrap',
                            alignItems: 'center',
                          }}
                        >
                          <strong>{campaign.title}</strong>
                          <div style={{ display: 'flex', gap: '0.35rem', alignItems: 'center' }}>
                            {campaign.is_hidden && (
                              <span
                                style={{
                                  fontSize: '0.72rem',
                                  fontWeight: 700,
                                  textTransform: 'uppercase',
                                  letterSpacing: '0.04em',
                                  padding: '0.15rem 0.5rem',
                                  borderRadius: '99px',
                                  background: 'var(--color-surface)',
                                  color: 'var(--color-text-hint)',
                                  opacity: 0.6,
                                }}
                              >
                                {t('dashboard.hidden')}
                              </span>
                            )}
                            <CampaignStatusBadge status={campaign.status} />
                          </div>
                        </div>
                        <div style={{ marginTop: '0.35rem', fontSize: '0.9rem' }}>
                          {Number(campaign.raised_amount).toLocaleString()} /{' '}
                          {Number(campaign.target_amount).toLocaleString()} {campaign.asset_type}
                        </div>
                        <div
                          style={{
                            background: 'var(--color-surface)',
                            borderRadius: '99px',
                            height: '6px',
                            marginTop: '0.35rem',
                          }}
                        >
                          <div
                            style={{
                              background: 'var(--color-accent)',
                              height: '6px',
                              borderRadius: '99px',
                              width: `${pct}%`,
                            }}
                          />
                        </div>
                        <div
                          style={{
                            marginTop: '0.35rem',
                            color: 'var(--color-text-hint)',
                            fontSize: '0.85rem',
                          }}
                        >
                          {t('dashboard.contributorsCount', { count: campaign.contributor_count })}
                          {campaign.deadline
                            ? ` • ${t('dashboard.deadline', { date: new Date(campaign.deadline).toLocaleDateString() })}`
                            : ''}
                        </div>
                        <div
                          style={{
                            marginTop: '0.6rem',
                            display: 'flex',
                            gap: '0.75rem',
                            flexWrap: 'wrap',
                          }}
                        >
                          <Link
                            to={`/campaigns/${campaign.id}`}
                            style={{ color: 'var(--color-accent)', fontWeight: 600 }}
                          >
                            {t('dashboard.viewCampaign')}
                          </Link>
                          <button
                            type="button"
                            className="btn-secondary"
                            disabled={exportingCampaignId !== null}
                            aria-busy={exportingCampaignId === campaign.id}
                            onClick={() => handleExportContributions(campaign)}
                            style={{ fontSize: '0.82rem', padding: '0.3rem 0.8rem' }}
                          >
                            {exportingCampaignId === campaign.id
                              ? t('common.loading')
                              : t('dashboard.exportCsv')}
                          </button>
                          <button
                            type="button"
                            className="btn-secondary"
                            onClick={() => setBulkThankYouCampaignId(campaign.id)}
                            style={{ fontSize: '0.82rem', padding: '0.3rem 0.8rem' }}
                          >
                            {t('dashboard.sendThankYou')}
                          </button>
                          <button
                            type="button"
                            className="btn-secondary"
                            disabled={togglingVisibility !== null}
                            aria-busy={togglingVisibility === campaign.id}
                            onClick={() => handleToggleVisibility(campaign)}
                            style={{ fontSize: '0.82rem', padding: '0.3rem 0.8rem' }}
                          >
                            {togglingVisibility === campaign.id
                              ? t('common.loading')
                              : campaign.is_hidden
                                ? t('dashboard.showCampaign')
                                : t('dashboard.hideCampaign')}
                          </button>
                          {campaign.status === 'funded' && (
                            <Link
                              to={`/campaigns/${campaign.id}#withdrawals`}
                              style={{ color: 'var(--color-accent)', fontWeight: 600 }}
                            >
                              {campaign.has_milestones
                                ? t('dashboard.manageMilestoneReleases')
                                : t('dashboard.requestWithdrawal')}
                            </Link>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
                {campaignsTotalPages > 1 && (
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '1.5rem', flexWrap: 'wrap', gap: '1rem' }}>
                    <span style={{ fontSize: '0.9rem', color: 'var(--color-text-hint)' }}>
                      {t('dashboard.showingCampaignsOf', { count: campaigns.length, total: campaignsTotal })}
                    </span>
                    <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
                      <button
                        type="button"
                        className="btn-secondary"
                        disabled={campaignsPage === 1 || isCampaignsPageLoading}
                        onClick={() => setCampaignsPage(p => Math.max(1, p - 1))}
                        style={{ padding: '0.3rem 0.8rem', fontSize: '0.85rem' }}
                      >
                        {t('dashboard.previous')}
                      </button>
                      <span style={{ fontSize: '0.9rem' }}>
                        {t('dashboard.pageOf', { page: campaignsPage, totalPages: campaignsTotalPages })}
                      </span>
                      <button
                        type="button"
                        className="btn-secondary"
                        disabled={campaignsPage === campaignsTotalPages || isCampaignsPageLoading}
                        onClick={() => setCampaignsPage(p => Math.min(campaignsTotalPages, p + 1))}
                        style={{ padding: '0.3rem 0.8rem', fontSize: '0.85rem' }}
                      >
                        {t('dashboard.next')}
                      </button>
                    </div>
                  </div>
                )}
                </>
              )}
            </>
          )}
        </section>
      )}

      {activeTab === 'contributions' && (
        <section role="tabpanel" aria-labelledby="tab-contributions">
          <ContributorDashboard />
        </section>
      )}

      {activeTab === 'subscriptions' && (
        <section role="tabpanel" aria-labelledby="tab-subscriptions">
          <SubscriptionsPanel />
        </section>
      )}

      {activeTab === 'following' && (
        <section role="tabpanel" aria-labelledby="tab-following">
          <FollowedCampaigns />
        </section>
      )}

      {activeTab === 'analytics' && isCreator && (
        <section role="tabpanel" aria-labelledby="tab-analytics">
          <div style={{ marginBottom: '1rem' }}>
            <Link
              to="/dashboard/analytics"
              style={{ color: 'var(--color-accent)', fontWeight: 600, fontSize: '0.9rem' }}
            >
              Open Full Analytics Dashboard →
            </Link>
          </div>
          {/* Dashboard-wide trend */}
          <div className="campaign-card" style={{ marginBottom: '1rem', minHeight: 'auto' }}>
            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                flexWrap: 'wrap',
                gap: '0.5rem',
                marginBottom: '0.75rem',
              }}
            >
              <strong>{t('dashboard.contributionsLast30Days')}</strong>
              {dashAnalytics?.recent_trend?.length > 0 && (
                <button
                  type="button"
                  className="btn-primary"
                  style={{ fontSize: '0.82rem', padding: '0.3rem 0.8rem' }}
                  onClick={() => exportCSV(dashAnalytics.recent_trend, 'contributions_trend.csv')}
                >
                  {t('dashboard.exportCsv')}
                </button>
              )}
            </div>
            <React.Suspense fallback={<p style={{ color: 'var(--color-text-hint)', fontSize: '0.9rem' }}>Loading chart…</p>}>
              <MiniLineChart
                data={dashAnalytics?.recent_trend}
                dataKey="total_amount"
                label={t('dashboard.amount')}
              />
            </React.Suspense>
            {dashAnalytics?.overview && (
              <div
                style={{
                  display: 'grid',
                  gridTemplateColumns: 'repeat(auto-fit,minmax(140px,1fr))',
                  gap: '0.5rem',
                  marginTop: '0.75rem',
                }}
              >
                {[
                  [
                    t('dashboard.analyticsOverview.totalRaised'),
                    Number(dashAnalytics.overview.total_raised).toLocaleString(),
                  ],
                  [
                    t('dashboard.analyticsOverview.contributions'),
                    dashAnalytics.overview.total_contributions,
                  ],
                  [
                    t('dashboard.analyticsOverview.uniqueContributors'),
                    dashAnalytics.overview.unique_contributors,
                  ],
                  [
                    t('dashboard.analyticsOverview.avgContribution'),
                    Number(dashAnalytics.overview.avg_contribution).toLocaleString(undefined, {
                      maximumFractionDigits: 2,
                    }),
                  ],
                ].map(([label, val]) => (
                  <div
                    key={label}
                    className="campaign-card"
                    style={{ minHeight: 'auto', padding: '0.6rem 0.75rem' }}
                  >
                    <strong style={{ fontSize: '1rem' }}>{val}</strong>
                    <div style={{ fontSize: '0.78rem', color: 'var(--color-text-hint)' }}>
                      {label}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Funding velocity curves — daily raised per campaign (#593) */}
          {dashAnalytics?.funding_velocity?.length > 0 && (
            <div className="campaign-card" style={{ marginBottom: '1rem', minHeight: 'auto' }}>
              <strong style={{ display: 'block', marginBottom: '0.6rem' }}>
                Funding Velocity (last 60 days)
              </strong>
              <React.Suspense fallback={<p style={{ color: 'var(--color-text-hint)', fontSize: '0.9rem' }}>Loading chart…</p>}>
                <MiniLineChart
                  data={dashAnalytics.funding_velocity}
                  dataKey="daily_amount"
                  label="Amount"
                />
              </React.Suspense>
            </div>
          )}

          {/* Contributor retention — new vs returning by month (#593) */}
          {dashAnalytics?.contributor_retention?.length > 0 && (
            <div className="campaign-card" style={{ marginBottom: '1rem', minHeight: 'auto' }}>
              <strong style={{ display: 'block', marginBottom: '0.6rem' }}>
                Contributor Retention (last 6 months)
              </strong>
              <div style={{ overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.82rem' }}>
                  <thead>
                    <tr style={{ borderBottom: '2px solid var(--color-border)', textAlign: 'left' }}>
                      <th style={{ padding: '0.3rem 0.5rem' }}>Month</th>
                      <th style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>New</th>
                      <th style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>Returning</th>
                      <th style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>Retention %</th>
                    </tr>
                  </thead>
                  <tbody>
                    {dashAnalytics.contributor_retention.map((r) => {
                      const total = (r.new_count || 0) + (r.returning_count || 0);
                      const pct = total > 0 ? Math.round((r.returning_count / total) * 100) : 0;
                      return (
                        <tr key={r.month} style={{ borderBottom: '1px solid var(--color-border-lighter)' }}>
                          <td style={{ padding: '0.3rem 0.5rem', fontWeight: 600 }}>{r.month}</td>
                          <td style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>{r.new_count}</td>
                          <td style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>{r.returning_count}</td>
                          <td style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>{pct}%</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* Referral conversion rate — clicks vs contributions (#593) */}
          {dashAnalytics?.referral_conversion?.length > 0 && (
            <div className="campaign-card" style={{ marginBottom: '1rem', minHeight: 'auto' }}>
              <strong style={{ display: 'block', marginBottom: '0.6rem' }}>
                Referral Conversion
              </strong>
              <div style={{ overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.82rem' }}>
                  <thead>
                    <tr style={{ borderBottom: '2px solid var(--color-border)', textAlign: 'left' }}>
                      <th style={{ padding: '0.3rem 0.5rem' }}>Referral Code</th>
                      <th style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>Clicks</th>
                      <th style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>Contributions</th>
                      <th style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>Conversion</th>
                    </tr>
                  </thead>
                  <tbody>
                    {dashAnalytics.referral_conversion.map((r) => (
                      <tr key={r.referral_code} style={{ borderBottom: '1px solid var(--color-border-lighter)' }}>
                        <td style={{ padding: '0.3rem 0.5rem', fontFamily: 'monospace', fontSize: '0.78rem' }}>
                          {r.referral_code}
                        </td>
                        <td style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>{r.click_count}</td>
                        <td style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>{r.contribution_count}</td>
                        <td style={{ padding: '0.3rem 0.5rem', textAlign: 'center' }}>{r.conversion_rate}%</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* Per-campaign drill-down */}
          <div className="campaign-card" style={{ minHeight: 'auto' }}>
            <strong style={{ display: 'block', marginBottom: '0.6rem' }}>
              {t('dashboard.perCampaignAnalytics')}
            </strong>
            {campaigns.length === 0 ? (
              <p style={{ color: 'var(--color-text-hint)', fontSize: '0.9rem' }}>
                {t('dashboard.noCampaigns')}
              </p>
            ) : (
              <div
                style={{
                  display: 'flex',
                  gap: '0.5rem',
                  flexWrap: 'wrap',
                  marginBottom: '0.75rem',
                }}
              >
                    {campaigns.map((c) => (
                  <div key={c.id} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                    <button
                      key={c.id}
                      type="button"
                      onClick={() => loadCampaignAnalytics(c.id)}
                      style={{
                        padding: '0.3rem 0.75rem',
                        borderRadius: 8,
                        border: '1px solid var(--color-border)',
                        cursor: 'pointer',
                        fontWeight: 600,
                        fontSize: '0.82rem',
                        background:
                          selectedCampaignId === c.id ? 'var(--color-accent)' : 'transparent',
                        color: selectedCampaignId === c.id ? '#fff' : 'var(--color-text-secondary)',
                      }}
                    >
                      {c.title}
                    </button>
                    <Link
                      to={`/dashboard/analytics/${c.id}`}
                      style={{ color: 'var(--color-accent)', fontSize: '0.78rem', fontWeight: 600, whiteSpace: 'nowrap' }}
                    >
                      Deep Dive →
                    </Link>
                  </div>
                ))}
              </div>
            )}

            {analyticsLoading && (
              <p style={{ color: 'var(--color-text-hint)', fontSize: '0.9rem' }}>
                {t('common.loading')}
              </p>
            )}

            {campaignAnalytics && !analyticsLoading && (
              <>
                {/* Summary row */}
                <div
                  style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fit,minmax(140px,1fr))',
                    gap: '0.5rem',
                    marginBottom: '0.75rem',
                  }}
                >
                  {[
                    [
                      t('dashboard.analyticsOverview.totalRaised'),
                      `${Number(campaignAnalytics.campaign.raised_amount).toLocaleString()} ${campaignAnalytics.campaign.asset_type}`,
                    ],
                    [
                      t('dashboard.analyticsOverview.contributions'),
                      campaignAnalytics.summary.total_contributions,
                    ],
                    [
                      t('dashboard.analyticsOverview.uniqueContributors'),
                      campaignAnalytics.summary.unique_contributors,
                    ],
                    [
                      t('dashboard.analyticsOverview.avgContribution'),
                      Number(campaignAnalytics.summary.avg_contribution).toLocaleString(undefined, {
                        maximumFractionDigits: 2,
                      }),
                    ],
                  ].map(([label, val]) => (
                    <div
                      key={label}
                      className="campaign-card"
                      style={{ minHeight: 'auto', padding: '0.6rem 0.75rem' }}
                    >
                      <strong style={{ fontSize: '1rem' }}>{val}</strong>
                      <div style={{ fontSize: '0.78rem', color: 'var(--color-text-hint)' }}>
                        {label}
                      </div>
                    </div>
                  ))}
                </div>

                {/* Contributor stats card */}
                {campaignContributors && (
                  <div
                    className="campaign-card"
                    style={{ minHeight: 'auto', marginBottom: '0.75rem', padding: '0.75rem' }}
                  >
                    <strong style={{ fontSize: '0.9rem' }}>
                      {t('dashboard.contributorStats')}
                    </strong>
                    <div
                      style={{
                        marginTop: '0.4rem',
                        display: 'flex',
                        gap: '1.5rem',
                        flexWrap: 'wrap',
                        fontSize: '0.88rem',
                      }}
                    >
                      <span>
                        {t('dashboard.firstTime')}:{' '}
                        <strong>{campaignContributors.first_time_contributors ?? 0}</strong>
                      </span>
                      <span>
                        {t('dashboard.returning')}:{' '}
                        <strong>{campaignContributors.repeat_contributors ?? 0}</strong>
                      </span>
                      {campaignContributors.repeat_contributors > 0 && (
                        <span>
                          {t('dashboard.returnRate')}:{' '}
                          <strong>
                            {(
                              (campaignContributors.repeat_contributors /
                                ((campaignContributors.repeat_contributors || 0) +
                                  (campaignContributors.first_time_contributors || 0))) *
                              100
                            ).toFixed(0)}
                            %
                          </strong>
                        </span>
                      )}
                    </div>
                    {campaignContributors.country_breakdown?.length > 0 && (
                      <div style={{ marginTop: '0.5rem', fontSize: '0.85rem' }}>
                        <span style={{ color: 'var(--color-text-hint)' }}>
                          {t('dashboard.topCountry')}:{' '}
                        </span>
                        <strong>{campaignContributors.country_breakdown[0].country}</strong>
                        <span style={{ color: 'var(--color-text-hint)' }}>
                          {' '}
                          (
                          {campaignContributors.country_breakdown
                            .map((c) => `${c.country} ${c.contributor_count}`)
                            .slice(0, 3)
                            .join(' · ')}
                          )
                        </span>
                      </div>
                    )}
                  </div>
                )}

                {campaignBackers && (
                  <React.Suspense fallback={<p style={{ color: 'var(--color-text-hint)', fontSize: '0.9rem' }}>Loading chart…</p>}>
                    <BackerInsightsCard
                      data={campaignBackers}
                      assetType={campaignAnalytics?.campaign?.asset_type || 'XLM'}
                    />
                  </React.Suspense>
                )}

                {/* Time-series chart */}
                <strong style={{ display: 'block', marginBottom: '0.4rem', fontSize: '0.9rem' }}>
                  {t('dashboard.contributionsOverTime')}
                </strong>
                <React.Suspense fallback={<p style={{ color: 'var(--color-text-hint)', fontSize: '0.9rem' }}>Loading chart…</p>}>
                  <MiniLineChart
                    data={campaignAnalytics.daily_buckets}
                    dataKey="total_amount"
                    label={t('dashboard.amount')}
                  />
                </React.Suspense>

                {/* Milestone funnel */}
                <MilestoneFunnel campaignId={selectedCampaignId} />

                {/* CSV export */}
                {campaignAnalytics.daily_buckets?.length > 0 && (
                  <button
                    type="button"
                    className="btn-primary"
                    style={{ marginTop: '0.75rem', fontSize: '0.82rem', padding: '0.3rem 0.8rem' }}
                    onClick={() =>
                      exportCSV(
                        campaignAnalytics.daily_buckets.map((r) => ({
                          date: r.day,
                          contributions: r.contribution_count,
                          amount: r.total_amount,
                        })),
                        `campaign_${selectedCampaignId}_analytics.csv`
                      )
                    }
                  >
                    {t('dashboard.exportCsv')}
                  </button>
                )}

                {/* Contributions list with individual thank-you */}
                {campaignContributions.length > 0 && !contributionsLoading && (
                  <div className="campaign-card" style={{ minHeight: 'auto', marginTop: '0.75rem' }}>
                    <strong style={{ display: 'block', marginBottom: '0.6rem', fontSize: '0.9rem' }}>
                      {t('dashboard.contributors')}
                    </strong>
                    <div style={{ maxHeight: '300px', overflowY: 'auto' }}>
                      {campaignContributions.map((ct) => (
                        <div
                          key={ct.id}
                          style={{
                            display: 'flex',
                            justifyContent: 'space-between',
                            alignItems: 'center',
                            padding: '0.4rem 0',
                            borderBottom: '1px solid var(--color-border-lighter)',
                            fontSize: '0.85rem',
                          }}
                        >
                          <span>
                            {ct.display_name || ct.sender_public_key?.slice(0, 8) + '…'}{' '}
                            <span style={{ color: 'var(--color-text-hint)' }}>
                              · {Number(ct.amount).toLocaleString()} {ct.asset} ·{' '}
                              {new Date(ct.created_at).toLocaleDateString()}
                            </span>
                          </span>
                          <button
                            type="button"
                            className="btn-secondary"
                            onClick={() =>
                              setIndividualThankYouContribution({
                                id: ct.id,
                                display_name: ct.display_name || 'contributor',
                              })
                            }
                            style={{ fontSize: '0.78rem', padding: '0.2rem 0.6rem' }}
                          >
                            {t('dashboard.sendThankYou')}
                          </button>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        </section>
      )}

      {activeTab === 'referrals' && isCreator && (
        <section role="tabpanel" aria-labelledby="tab-referrals">
          {referralLoading ? (
            <p style={{ color: 'var(--color-text-hint)' }}>{t('dashboard.loadingReferrals')}</p>
          ) : campaigns.length === 0 ? (
            <p className="alert alert--info">
              {t('dashboard.noReferralCampaigns')}{' '}
              <Link to="/campaigns/new" style={{ color: 'var(--color-accent)', fontWeight: 600 }}>
                {t('dashboard.createCampaign')}
              </Link>{' '}
              {t('dashboard.startTrackingReferrals')}
            </p>
          ) : (
            <div style={{ display: 'grid', gap: '0.75rem' }}>
              {campaigns.map((campaign) => {
                const refs = referralData[campaign.id] || [];
                const totalClicks = refs.reduce((s, r) => s + r.click_count, 0);
                const totalContributions = refs.reduce((s, r) => s + r.contribution_count, 0);
                return (
                  <div key={campaign.id} className="campaign-card">
                    <div
                      style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        gap: '0.5rem',
                        flexWrap: 'wrap',
                        alignItems: 'center',
                        marginBottom: '0.75rem',
                      }}
                    >
                      <Link
                        to={`/campaigns/${campaign.id}`}
                        style={{ color: 'var(--color-accent)', fontWeight: 700 }}
                      >
                        {campaign.title}
                      </Link>
                      <CampaignStatusBadge status={campaign.status} />
                    </div>
                    {refs.length === 0 ? (
                      <p style={{ color: 'var(--color-text-hint)', fontSize: '0.85rem' }}>
                        {t('dashboard.noReferralActivity')}
                      </p>
                    ) : (
                      <>
                        <div
                          style={{
                            display: 'flex',
                            gap: '1rem',
                            marginBottom: '0.75rem',
                            fontSize: '0.85rem',
                          }}
                        >
                          <span>
                            <strong>{totalClicks}</strong> {t('dashboard.totalClicks')}
                          </span>
                          <span>
                            <strong>{totalContributions}</strong> {t('dashboard.totalConversions')}
                          </span>
                        </div>
                        <table
                          style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.82rem' }}
                        >
                          <thead>
                            <tr
                              style={{
                                borderBottom: '2px solid var(--color-border)',
                                textAlign: 'left',
                              }}
                            >
                              <th style={{ padding: '0.35rem 0.5rem' }}>
                                {t('dashboard.referrer')}
                              </th>
                              <th style={{ padding: '0.35rem 0.5rem', textAlign: 'center' }}>
                                {t('dashboard.clicks')}
                              </th>
                              <th style={{ padding: '0.35rem 0.5rem', textAlign: 'center' }}>
                                {t('dashboard.conversions')}
                              </th>
                              <th style={{ padding: '0.35rem 0.5rem', textAlign: 'center' }}>
                                {t('dashboard.rate')}
                              </th>
                            </tr>
                          </thead>
                          <tbody>
                            {refs.map((r) => (
                              <tr
                                key={r.referral_code}
                                style={{ borderBottom: '1px solid var(--color-border-lighter)' }}
                              >
                                <td style={{ padding: '0.35rem 0.5rem', fontWeight: 600 }}>
                                  {r.referrer_name}
                                </td>
                                <td style={{ padding: '0.35rem 0.5rem', textAlign: 'center' }}>
                                  {r.click_count}
                                </td>
                                <td style={{ padding: '0.35rem 0.5rem', textAlign: 'center' }}>
                                  {r.contribution_count}
                                </td>
                                <td style={{ padding: '0.35rem 0.5rem', textAlign: 'center' }}>
                                  {r.click_count > 0
                                    ? `${((r.contribution_count / r.click_count) * 100).toFixed(0)}%`
                                    : '-'}
                                </td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </section>
      )}

      {activeTab === 'api-keys' && <ApiKeysPanel />}

      {showDepositModal && (
        <DepositModal
          onClose={() => setShowDepositModal(false)}
          onSuccess={() => {
            api
              .getMyBalance()
              .then((d) => setBalance(d.balance))
              .catch(() => {});
          }}
        />
      )}

      {thankYouSent && (
        <div
          style={{
            position: 'fixed',
            bottom: '1.5rem',
            right: '1.5rem',
            background: '#22c55e',
            color: '#fff',
            padding: '0.75rem 1.25rem',
            borderRadius: '8px',
            fontSize: '0.9rem',
            fontWeight: 600,
            boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
            zIndex: 1001,
          }}
        >
          {thankYouSent}
          <button
            onClick={() => setThankYouSent('')}
            style={{
              background: 'none',
              border: 'none',
              color: '#fff',
              marginLeft: '0.75rem',
              cursor: 'pointer',
              fontWeight: 700,
              fontSize: '1rem',
            }}
          >
            x
          </button>
        </div>
      )}

      {bulkThankYouCampaignId && (
        <ThankYouModal
          campaignId={bulkThankYouCampaignId}
          onClose={() => setBulkThankYouCampaignId(null)}
          onSent={() => setThankYouSent(t('thankYou.sent'))}
        />
      )}

      {individualThankYouContribution && (
        <ThankYouModal
          campaignId={selectedCampaignId}
          contribution={individualThankYouContribution}
          onClose={() => setIndividualThankYouContribution(null)}
          onSent={() => setThankYouSent(t('thankYou.sent'))}
        />
      )}
    </main>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import * as Sentry from '@sentry/react';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import { api } from '../services/api';

const EVENT_OPTIONS = [
  'campaign.funded',
  'contribution.received',
  'milestone.approved',
  'withdrawal.completed',
];

const SCOPE_OPTIONS = ['read', 'write', 'withdrawals', 'developer', 'full'];

const V1_API_BASE = `${(import.meta.env.VITE_API_BASE_URL || '').replace(/\/+$/, '')}/api/v1`;

export default function Developer() {
  const { user } = useAuth();
  const toast = useToast();
  const [keys, setKeys] = useState([]);
  const [hooks, setHooks] = useState([]);
  const [deliveries, setDeliveries] = useState([]);
  const [error, setError] = useState('');
  const [newKeyLabel, setNewKeyLabel] = useState('Integration');
  const [newKeyScopes, setNewKeyScopes] = useState(['read', 'write', 'withdrawals']);
  const [revealedKey, setRevealedKey] = useState('');
  const [hookUrl, setHookUrl] = useState('');
  const [hookEvents, setHookEvents] = useState(['contribution.received']);
  const [revealedSecret, setRevealedSecret] = useState('');
  const [loading, setLoading] = useState(true);
  const [v1Endpoints, setV1Endpoints] = useState([]);
  const [explorerEndpoint, setExplorerEndpoint] = useState('');
  const [explorerApiKey, setExplorerApiKey] = useState('');
  const [explorerPathParams, setExplorerPathParams] = useState({});
  const [explorerQuery, setExplorerQuery] = useState({});
  const [explorerBody, setExplorerBody] = useState('');
  const [explorerResponse, setExplorerResponse] = useState('');
  const [explorerBusy, setExplorerBusy] = useState(false);
  const [explorerError, setExplorerError] = useState('');

  async function refresh() {
    setError('');
    try {
      const [k, h, d] = await Promise.all([
        api.listApiKeys(),
        api.listWebhooks(),
        api.listWebhookDeliveries({ limit: 80 }),
      ]);
      setKeys(k);
      setHooks(h);
      setDeliveries(d);
    } catch (e) {
      setError(e.message || 'Failed to load');
    } finally {
      setLoading(false);
    }
  }

  async function loadOpenApi() {
    try {
      // Cache hit: the spec is unlikely to change during a session (Issue #580).
      const cacheKey = `cp_openapi_spec_${V1_API_BASE}`;
      const cachedRaw = sessionStorage.getItem(cacheKey);
      if (cachedRaw) {
        try {
          const cached = JSON.parse(cachedRaw);
          if (Array.isArray(cached) && cached.length > 0) {
            setV1Endpoints(cached);
            const saved = localStorage.getItem('cp_explorer_endpoint');
            if (saved && cached.find((e) => e.id === saved)) {
              setExplorerEndpoint(saved);
            } else if (cached.length > 0) {
              setExplorerEndpoint(cached[0].id);
            }
            return;
          }
        } catch {
          // Corrupted cache — silently re-fetch.
          sessionStorage.removeItem(cacheKey);
        }
      }

      const res = await fetch(`${V1_API_BASE}/docs/openapi.json`);
      if (!res.ok) throw new Error('Failed to fetch OpenAPI spec');
      const spec = await res.json();
      
      const endpoints = [];
      for (const [path, methods] of Object.entries(spec.paths || {})) {
        for (const [method, operation] of Object.entries(methods)) {
          const pathFields = [];
          const queryFields = [];
          let bodyTemplate = null;

          (operation.parameters || []).forEach((p) => {
            if (p.in === 'path') pathFields.push(p.name);
            if (p.in === 'query') queryFields.push(p.name);
          });

          const normalizedPath = path.replace(/{([^}]+)}/g, ':$1');

          if (operation.requestBody?.content?.['application/json']?.schema?.properties) {
            bodyTemplate = Object.keys(
              operation.requestBody.content['application/json'].schema.properties
            ).reduce((acc, k) => ({ ...acc, [k]: '' }), {});
          } else if (method.toUpperCase() !== 'GET') {
            bodyTemplate = {};
          }

          endpoints.push({
            id: `${method.toUpperCase()}-${path}`,
            label: `${method.toUpperCase()} ${normalizedPath} — ${operation.summary || ''}`,
            method: method.toUpperCase(),
            path: normalizedPath,
            auth: !!(operation.security && operation.security.length),
            pathFields,
            queryFields,
            bodyTemplate,
          });
        }
      }
      setV1Endpoints(endpoints);

      // Cache the parsed endpoints in sessionStorage so subsequent mounts
      // skip the network roundtrip (Issue #580).
      try {
        sessionStorage.setItem(cacheKey, JSON.stringify(endpoints));
      } catch {
        // Storage full or unavailable — non-critical, the endpoints are already
        // in component state.
      }

      const saved = localStorage.getItem('cp_explorer_endpoint');
      if (saved && endpoints.find((e) => e.id === saved)) {
        setExplorerEndpoint(saved);
      } else if (endpoints.length > 0) {
        setExplorerEndpoint(endpoints[0].id);
      }
    } catch (err) {
      toast?.('Failed to load API spec. Please try again.', 'error');
      Sentry.captureException(err);
    }
  }

  useEffect(() => {
    refresh();
    loadOpenApi();
  }, []);

  useEffect(() => {
    if (!explorerEndpoint) return;
    localStorage.setItem('cp_explorer_endpoint', explorerEndpoint);
    
    const savedParamsStr = localStorage.getItem(`cp_explorer_params_${explorerEndpoint}`);
    if (savedParamsStr) {
      try {
        const parsed = JSON.parse(savedParamsStr);
        setExplorerPathParams(parsed.pathParams || {});
        setExplorerQuery(parsed.query || {});
        setExplorerBody(parsed.body || '');
      } catch (err) {
        // ignore JSON parse error
      }
    } else {
      const ep = v1Endpoints.find((e) => e.id === explorerEndpoint);
      setExplorerPathParams({});
      setExplorerQuery({});
      setExplorerBody(ep?.bodyTemplate ? JSON.stringify(ep.bodyTemplate, null, 2) : '');
    }
    setExplorerResponse('');
    setExplorerError('');
  }, [explorerEndpoint, v1Endpoints]);

  // Debounce localStorage writes so typing in the body/params does not
  // stringify + setItem on every keystroke (see #575).
  useEffect(() => {
    if (!explorerEndpoint) return;
    const timer = setTimeout(() => {
      localStorage.setItem(
        `cp_explorer_params_${explorerEndpoint}`,
        JSON.stringify({
          pathParams: explorerPathParams,
          query: explorerQuery,
          body: explorerBody,
        })
      );
    }, 400);
    return () => clearTimeout(timer);
  }, [explorerPathParams, explorerQuery, explorerBody, explorerEndpoint]);

  if (!user) {
    return (
      <main className="container" style={{ paddingTop: '4rem', maxWidth: '720px' }}>
        <p>
          <Link to="/login">Log in</Link> to manage API keys and webhooks.
        </p>
      </main>
    );
  }

  async function createKey(e) {
    e.preventDefault();
    setRevealedKey('');
    setError('');
    try {
      const res = await api.createApiKey({ name: newKeyLabel, scopes: newKeyScopes });
      setRevealedKey(res.api_key);
      await refresh();
    } catch (err) {
      setError(err.message);
    }
  }

  async function revokeKey(id) {
    if (!window.confirm('Revoke this API key?')) return;
    setError('');
    try {
      await api.deleteApiKey(id);
      await refresh();
    } catch (err) {
      setError(err.message);
    }
  }

  async function createHook(e) {
    e.preventDefault();
    setRevealedSecret('');
    setError('');
    try {
      const res = await api.createWebhook({ url: hookUrl, events: hookEvents });
      setRevealedSecret(res.secret);
      setHookUrl('');
      await refresh();
    } catch (err) {
      setError(err.message);
    }
  }

  async function revokeHook(id) {
    if (!window.confirm('Remove this webhook endpoint?')) return;
    setError('');
    try {
      await api.deleteWebhook(id);
      await refresh();
    } catch (err) {
      setError(err.message);
    }
  }

  function toggleEvent(ev) {
    setHookEvents((cur) => (cur.includes(ev) ? cur.filter((x) => x !== ev) : [...cur, ev]));
  }

  function toggleScope(sc) {
    setNewKeyScopes((cur) => (cur.includes(sc) ? cur.filter((x) => x !== sc) : [...cur, sc]));
  }

  const selectedEndpoint =
    v1Endpoints.find((e) => e.id === explorerEndpoint) ||
    v1Endpoints[0] ||
    {
      id: '',
      auth: false,
      method: 'GET',
      path: '',
      pathFields: [],
      queryFields: [],
      bodyTemplate: null,
      label: '',
    };

  function buildExplorerUrl() {
    if (!selectedEndpoint) return '';
    let path = selectedEndpoint.path;
    (selectedEndpoint.pathFields || []).forEach((field) => {
      path = path.replace(`:${field}`, encodeURIComponent(explorerPathParams[field] || ''));
    });
    const params = new URLSearchParams();
    (selectedEndpoint.queryFields || []).forEach((field) => {
      const value = explorerQuery[field];
      if (value !== undefined && value !== '') params.set(field, String(value));
    });
    const qs = params.toString();
    return `${V1_API_BASE}${path}${qs ? `?${qs}` : ''}`;
  }

  function getCurlCommand() {
    if (!selectedEndpoint) return '';
    const url = buildExplorerUrl();
    let cmd = `curl -X ${selectedEndpoint.method} "${url}"`;
    
    if (selectedEndpoint.auth && explorerApiKey) {
      cmd += ` \\\n  -H "Authorization: Bearer ${explorerApiKey}"`;
    }
    
    if (selectedEndpoint.method !== 'GET' && selectedEndpoint.bodyTemplate !== null) {
      cmd += ` \\\n  -H "Content-Type: application/json"`;
      if (explorerBody) {
        const safeBody = explorerBody.replace(/'/g, "'\\''");
        cmd += ` \\\n  -d '${safeBody}'`;
      }
    }
    return cmd;
  }

  async function runExplorerRequest(e) {
    e.preventDefault();
    if (!selectedEndpoint) return;
    setExplorerBusy(true);
    setExplorerError('');
    setExplorerResponse('');
    try {
      const headers = { 'Content-Type': 'application/json' };
      if (selectedEndpoint.auth) {
        if (!explorerApiKey) {
          throw new Error('API key required for this endpoint');
        }
        headers.Authorization = `Bearer ${explorerApiKey}`;
      }
      const options = {
        method: selectedEndpoint.method,
        headers:
          selectedEndpoint.method === 'GET'
            ? explorerApiKey && selectedEndpoint.auth
              ? { Authorization: headers.Authorization }
              : undefined
            : headers,
      };
      if (selectedEndpoint.method !== 'GET' && selectedEndpoint.bodyTemplate !== null) {
        options.body = explorerBody;
      }
      const res = await fetch(buildExplorerUrl(), options);
      const text = await res.text();
      let parsed;
      try {
        parsed = JSON.parse(text);
      } catch {
        parsed = text;
      }
      setExplorerResponse(JSON.stringify({ status: res.status, headers: Object.fromEntries(res.headers.entries()), body: parsed }, null, 2));
    } catch (err) {
      setExplorerError(err.message || 'Request failed');
    } finally {
      setExplorerBusy(false);
    }
  }

  return (
    <main
      className="container"
      style={{ paddingTop: '3rem', paddingBottom: '4rem', maxWidth: '900px' }}
    >
      <h1 style={{ fontSize: '1.75rem', fontWeight: 800, marginBottom: '0.35rem' }}>Developer</h1>
      <p style={{ color: 'var(--color-text-hint)', marginBottom: '2rem', fontSize: '0.95rem' }}>
        API keys and webhooks for integrating CrowdPay as a funding backend. Public API
        documentation:{' '}
        <a
          href="/v1/docs"
          target="_blank"
          rel="noopener noreferrer"
          style={{ color: 'var(--color-accent)', fontWeight: 600 }}
        >
          OpenAPI /v1/docs
        </a>
        . See <code style={{ fontSize: '0.85rem' }}>backend/docs/webhooks-integration.md</code> for
        HMAC verification.
      </p>
      {error && <p style={{ color: 'var(--color-status-error)', marginBottom: '1rem' }}>{error}</p>}
      {loading && <p style={{ color: 'var(--color-text-hint)' }}>Loading…</p>}

      <section style={{ marginBottom: '2.5rem' }}>
        <h2 style={{ fontSize: '1.15rem', fontWeight: 700, marginBottom: '0.75rem' }}>
          API explorer
        </h2>
        <p style={{ fontSize: '0.9rem', color: 'var(--color-text-hint)', marginBottom: '1rem' }}>
          Try public API v1 endpoints with your API key. Rate limit: 100 requests/minute per key.
        </p>
        <form
          onSubmit={runExplorerRequest}
          style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem', maxWidth: '640px' }}
        >
          <label style={{ fontSize: '0.85rem' }}>
            Endpoint
            <select
              value={explorerEndpoint}
              onChange={(e) => setExplorerEndpoint(e.target.value)}
              style={{ display: 'block', width: '100%', marginTop: '0.35rem' }}
            >
              {v1Endpoints.map((ep) => (
                <option key={ep.id} value={ep.id}>
                  {ep.label}
                </option>
              ))}
            </select>
          </label>
          <label style={{ fontSize: '0.85rem' }}>
            API key {selectedEndpoint.auth ? '(required)' : '(optional)'}
            <input
              type="password"
              value={explorerApiKey}
              onChange={(e) => setExplorerApiKey(e.target.value)}
              placeholder="cp_live_…"
              style={{ display: 'block', width: '100%', marginTop: '0.35rem' }}
            />
          </label>
          {(selectedEndpoint.pathFields || []).map((field) => (
            <label key={field} style={{ fontSize: '0.85rem' }}>
              {field}
              <input
                value={explorerPathParams[field] || ''}
                onChange={(e) =>
                  setExplorerPathParams((cur) => ({ ...cur, [field]: e.target.value }))
                }
                style={{ display: 'block', width: '100%', marginTop: '0.35rem' }}
              />
            </label>
          ))}
          {(selectedEndpoint.queryFields || []).map((field) => (
            <label key={field} style={{ fontSize: '0.85rem' }}>
              Query: {field}
              <input
                value={explorerQuery[field] || ''}
                onChange={(e) => setExplorerQuery((cur) => ({ ...cur, [field]: e.target.value }))}
                style={{ display: 'block', width: '100%', marginTop: '0.35rem' }}
              />
            </label>
          ))}
          {selectedEndpoint.bodyTemplate && (
            <label style={{ fontSize: '0.85rem' }}>
              Request body (JSON)
              <textarea
                rows={5}
                value={explorerBody}
                onChange={(e) => setExplorerBody(e.target.value)}
                style={{
                  display: 'block',
                  width: '100%',
                  marginTop: '0.35rem',
                  fontFamily: 'monospace',
                  fontSize: '0.85rem',
                }}
              />
            </label>
          )}
          <button
            type="submit"
            className="btn-primary"
            disabled={explorerBusy}
            style={{ alignSelf: 'flex-start', padding: '0.5rem 1rem' }}
          >
            {explorerBusy ? 'Sending…' : 'Send request'}
          </button>
        </form>
        {explorerError && (
          <p style={{ color: 'var(--color-status-error)', marginTop: '0.75rem' }}>
            {explorerError}
          </p>
        )}
        {explorerResponse && (
          <pre
            style={{
              marginTop: '1rem',
              padding: '0.85rem',
              background: 'var(--color-border-lightest)',
              borderRadius: 8,
              overflow: 'auto',
              fontSize: '0.8rem',
            }}
          >
            {explorerResponse}
          </pre>
        )}
      </section>

      <section style={{ marginBottom: '2.5rem' }}>
        <h2 style={{ fontSize: '1.15rem', fontWeight: 700, marginBottom: '0.75rem' }}>API keys</h2>
        {revealedKey && (
          <div
            style={{
              background: 'var(--color-warning-bg)',
              border: '1px solid var(--color-warning-border)',
              padding: '0.85rem',
              borderRadius: 8,
              marginBottom: '1rem',
            }}
          >
            <strong>Copy now:</strong>
            <pre style={{ margin: '0.5rem 0 0', wordBreak: 'break-all', fontSize: '0.8rem' }}>
              {revealedKey}
            </pre>
          </div>
        )}
        <form
          onSubmit={createKey}
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: '0.5rem',
            alignItems: 'center',
            marginBottom: '1rem',
          }}
        >
          <label htmlFor="new-key-label" className="sr-only">API key label</label>
          <input
            id="new-key-label"
            value={newKeyLabel}
            onChange={(e) => setNewKeyLabel(e.target.value)}
            placeholder="Label"
            style={{ minWidth: '160px' }}
          />
          <span style={{ fontSize: '0.85rem', color: 'var(--color-text-secondary)' }}>Scopes:</span>
          {SCOPE_OPTIONS.map((sc) => (
            <label
              key={sc}
              style={{ fontSize: '0.85rem', display: 'flex', alignItems: 'center', gap: '0.25rem' }}
            >
              <input
                type="checkbox"
                checked={newKeyScopes.includes(sc)}
                onChange={() => toggleScope(sc)}
              />
              {sc}
            </label>
          ))}
          <button type="submit" className="btn-primary" style={{ padding: '0.45rem 0.9rem' }}>
            Create key
          </button>
        </form>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.9rem' }}>
          <thead>
            <tr style={{ textAlign: 'left', borderBottom: '1px solid var(--color-border-light)' }}>
              <th style={{ padding: '0.4rem' }}>Name</th>
              <th>Prefix</th>
              <th>Scopes</th>
              <th>Last used</th>
              <th />
            </tr>
          </thead>
          <tbody>
            {keys
              .filter((k) => !k.revoked_at)
              .map((k) => (
                <tr key={k.id} style={{ borderBottom: '1px solid var(--color-border-lighter)' }}>
                  <td style={{ padding: '0.45rem' }}>{k.label}</td>
                  <td>
                    <code>{k.key_prefix}</code>
                  </td>
                  <td>{(k.scopes || []).join(', ')}</td>
                  <td style={{ color: 'var(--color-text-hint)' }}>
                    {k.last_used_at ? new Date(k.last_used_at).toLocaleString() : '—'}
                  </td>
                  <td>
                    <button
                      type="button"
                      className="btn-secondary"
                      style={{ padding: '0.25rem 0.5rem', fontSize: '0.8rem' }}
                      onClick={() => revokeKey(k.id)}
                    >
                      Revoke
                    </button>
                  </td>
                </tr>
              ))}
          </tbody>
        </table>
      </section>

      <section style={{ marginBottom: '2.5rem' }}>
        <h2 style={{ fontSize: '1.15rem', fontWeight: 700, marginBottom: '0.75rem' }}>Webhooks</h2>
        {revealedSecret && (
          <div
            style={{
              background: 'var(--color-warning-bg)',
              border: '1px solid var(--color-warning-border)',
              padding: '0.85rem',
              borderRadius: 8,
              marginBottom: '1rem',
            }}
          >
            <strong>Signing secret (copy once):</strong>
            <pre style={{ margin: '0.5rem 0 0', wordBreak: 'break-all', fontSize: '0.8rem' }}>
              {revealedSecret}
            </pre>
          </div>
        )}
        <form
          onSubmit={createHook}
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: '0.65rem',
            maxWidth: '520px',
            marginBottom: '1rem',
          }}
        >
          <label htmlFor="webhook-url" className="sr-only">Webhook URL</label>
          <input
            id="webhook-url"
            value={hookUrl}
            onChange={(e) => setHookUrl(e.target.value)}
            placeholder="https://example.com/crowdpay-webhook"
            required
          />
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
            {EVENT_OPTIONS.map((ev) => (
              <label
                key={ev}
                style={{
                  fontSize: '0.85rem',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.25rem',
                }}
              >
                <input
                  type="checkbox"
                  checked={hookEvents.includes(ev)}
                  onChange={() => toggleEvent(ev)}
                />
                {ev}
              </label>
            ))}
          </div>
          <button
            type="submit"
            className="btn-primary"
            style={{ padding: '0.5rem 1rem', alignSelf: 'flex-start' }}
          >
            Add endpoint
          </button>
        </form>
        <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
          {hooks
            .filter((h) => !h.revoked_at)
            .map((h) => (
              <li
                key={h.id}
                style={{
                  padding: '0.5rem 0',
                  borderBottom: '1px solid var(--color-border-lighter)',
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: '1rem',
                  flexWrap: 'wrap',
                }}
              >
                <div>
                  <div style={{ fontWeight: 600 }}>{h.url}</div>
                  <div style={{ fontSize: '0.8rem', color: 'var(--color-text-hint)' }}>
                    {(h.events || []).join(', ')} · {h.secret_hint}
                  </div>
                </div>
                <button
                  type="button"
                  className="btn-secondary"
                  style={{ padding: '0.25rem 0.5rem', fontSize: '0.8rem' }}
                  onClick={() => revokeHook(h.id)}
                >
                  Remove
                </button>
              </li>
            ))}
        </ul>
      </section>

      <section>
        <h2 style={{ fontSize: '1.15rem', fontWeight: 700, marginBottom: '0.75rem' }}>
          Webhook delivery log
        </h2>
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.82rem' }}>
            <thead>
              <tr
                style={{ textAlign: 'left', borderBottom: '1px solid var(--color-border-light)' }}
              >
                <th style={{ padding: '0.35rem' }}>Time</th>
                <th>Event</th>
                <th>Status</th>
                <th>HTTP</th>
                <th>Attempts</th>
                <th>Error</th>
              </tr>
            </thead>
            <tbody>
              {deliveries.map((d) => (
                <tr key={d.id} style={{ borderBottom: '1px solid var(--color-border-lightest)' }}>
                  <td style={{ padding: '0.35rem', whiteSpace: 'nowrap' }}>
                    {new Date(d.created_at).toLocaleString()}
                  </td>
                  <td>{d.event_type}</td>
                  <td>{d.status}</td>
                  <td>{d.response_status ?? '—'}</td>
                  <td>{d.attempt_count}</td>
                  <td
                    style={{ maxWidth: '220px', overflow: 'hidden', textOverflow: 'ellipsis' }}
                    title={d.last_error || ''}
                  >
                    {d.last_error || '—'}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </main>
  );
}

import { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import Navbar from '../components/Navbar';

export default function Governance() {
  const { user } = useAuth();
  const { showToast } = useToast();
  const [feeInfo, setFeeInfo] = useState(null);
  const [proposals, setProposals] = useState([]);
  const [activeProposal, setActiveProposal] = useState(null);
  const [userTokenBalance, setUserTokenBalance] = useState(null);
  const [loading, setLoading] = useState(true);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [voting, setVoting] = useState(false);
  
  const [newProposal, setNewProposal] = useState({
    new_fee_bps: '',
    new_creator_share_bps: '',
    rationale_text: '',
    signer_secret: '',
  });

  useEffect(() => {
    loadGovernanceData();
  }, []);

  const loadGovernanceData = async () => {
    try {
      setLoading(true);
      
      // Load fee info
      const feeResponse = await fetch('/api/governance/fee');
      const feeData = await feeResponse.json();
      setFeeInfo(feeData);

      // Load proposals
      const proposalsResponse = await fetch('/api/governance/proposals');
      const proposalsData = await proposalsResponse.json();
      setProposals(proposalsData.proposals || []);

      // Load active proposal
      if (user) {
        const balanceResponse = await fetch('/api/governance/user/token-balance', {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`,
          },
        });
        const balanceData = await balanceResponse.json();
        setUserTokenBalance(balanceData);
      }

      // Check for active proposal
      const active = proposalsData.proposals?.find(p => p.status === 'active');
      if (active) {
        const detailResponse = await fetch(`/api/governance/proposals/${active.id}`);
        const detailData = await detailResponse.json();
        setActiveProposal(detailData.proposal);
      }
    } catch (error) {
      console.error('Failed to load governance data:', error);
      showToast('Failed to load governance data', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateProposal = async (e) => {
    e.preventDefault();
    
    try {
      const response = await fetch('/api/governance/proposals', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
        },
        body: JSON.stringify(newProposal),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Failed to create proposal');
      }

      const data = await response.json();
      showToast('Proposal created successfully', 'success');
      setShowCreateForm(false);
      setNewProposal({
        new_fee_bps: '',
        new_creator_share_bps: '',
        rationale_text: '',
        signer_secret: '',
      });
      loadGovernanceData();
    } catch (error) {
      showToast(error.message, 'error');
    }
  };

  const handleVote = async (inFavor) => {
    if (!activeProposal || !user) return;

    try {
      setVoting(true);
      
      // In production, this would use Freighter to sign the transaction
      // For now, we'll use the signer secret (this should be replaced with proper wallet signing)
      const response = await fetch(`/api/governance/proposals/${activeProposal.id}/vote`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
        },
        body: JSON.stringify({
          in_favor: inFavor,
          signer_secret: newProposal.signer_secret, // This should come from wallet signing
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Failed to vote');
      }

      showToast('Vote recorded successfully', 'success');
      loadGovernanceData();
    } catch (error) {
      showToast(error.message, 'error');
    } finally {
      setVoting(false);
    }
  };

  const handleExecuteProposal = async () => {
    if (!activeProposal) return;

    try {
      const response = await fetch(`/api/governance/proposals/${activeProposal.id}/execute`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
        },
        body: JSON.stringify({
          signer_secret: newProposal.signer_secret, // This should come from wallet signing
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Failed to execute proposal');
      }

      showToast('Proposal executed successfully', 'success');
      loadGovernanceData();
    } catch (error) {
      showToast(error.message, 'error');
    }
  };

  const getTimeRemaining = (deadline) => {
    if (!deadline) return null;
    const now = new Date();
    const end = new Date(deadline);
    const diff = end - now;
    
    if (diff <= 0) return 'Voting ended';
    
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    
    if (days > 0) return `${days}d ${hours}h remaining`;
    return `${hours}h remaining`;
  };

  const getStellarExpertUrl = (contractId) => {
    if (!contractId) return '#';
    const isTestnet = import.meta.env.VITE_STELLAR_NETWORK === 'testnet';
    return isTestnet 
      ? `https://stellar.expert/testnet/contract/${contractId}`
      : `https://stellar.expert/mainnet/contract/${contractId}`;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50">
        <Navbar />
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
          <div className="text-center">Loading governance data...</div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <Navbar />
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900">Governance</h1>
          <p className="mt-2 text-gray-600">
            Participate in CrowdPay&apos;s decentralized governance by voting on fee changes.
          </p>
        </div>

        {/* Fee Information */}
        {feeInfo && (
          <div className="bg-white rounded-lg shadow p-6 mb-6">
            <h2 className="text-xl font-semibold text-gray-900 mb-4">Current Platform Fee</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <p className="text-sm text-gray-500">Platform Fee</p>
                <p className="text-2xl font-bold text-gray-900">
                  {feeInfo.platform_fee_bps} bps ({feeInfo.platform_fee_percent}%)
                </p>
              </div>
              <div>
                <p className="text-sm text-gray-500">Creator Revenue Share</p>
                <p className="text-2xl font-bold text-gray-900">
                  {feeInfo.creator_share_bps} bps ({feeInfo.creator_share_percent}%)
                </p>
              </div>
            </div>
            {feeInfo.contract_id && (
              <div className="mt-4">
                <a
                  href={getStellarExpertUrl(feeInfo.contract_id)}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-blue-600 hover:text-blue-800 text-sm"
                >
                  View contract on Stellar Expert →
                </a>
              </div>
            )}
          </div>
        )}

        {/* User Token Balance */}
        {user && userTokenBalance && (
          <div className="bg-white rounded-lg shadow p-6 mb-6">
            <h2 className="text-xl font-semibold text-gray-900 mb-4">Your Governance Tokens</h2>
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-500">Balance</p>
                <p className="text-2xl font-bold text-gray-900">{userTokenBalance.balance} CROWD</p>
              </div>
              <div className="text-right">
                <p className="text-sm text-gray-500">Can Propose</p>
                <p className={`text-lg font-semibold ${userTokenBalance.can_propose ? 'text-green-600' : 'text-red-600'}`}>
                  {userTokenBalance.can_propose ? 'Yes' : 'No'}
                </p>
                <p className="text-xs text-gray-400">Minimum: {userTokenBalance.min_required} CROWD</p>
              </div>
            </div>
          </div>
        )}

        {/* Active Proposal */}
        {activeProposal && (
          <div className="bg-white rounded-lg shadow p-6 mb-6">
            <h2 className="text-xl font-semibold text-gray-900 mb-4">Active Proposal</h2>
            <div className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <p className="text-sm text-gray-500">Proposed Platform Fee</p>
                  <p className="text-lg font-semibold">
                    {activeProposal.proposed_fee_bps} bps ({(activeProposal.proposed_fee_bps / 100).toFixed(2)}%)
                  </p>
                </div>
                <div>
                  <p className="text-sm text-gray-500">Proposed Creator Share</p>
                  <p className="text-lg font-semibold">
                    {activeProposal.proposed_creator_share_bps} bps ({(activeProposal.proposed_creator_share_bps / 100).toFixed(2)}%)
                  </p>
                </div>
              </div>

              {activeProposal.rationale_text && (
                <div>
                  <p className="text-sm text-gray-500">Rationale</p>
                  <p className="text-gray-700">{activeProposal.rationale_text}</p>
                </div>
              )}

              {activeProposal.vote_stats && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div>
                    <p className="text-sm text-gray-500">Votes For</p>
                    <p className="text-lg font-semibold text-green-600">{activeProposal.vote_stats.votes_for}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">Votes Against</p>
                    <p className="text-lg font-semibold text-red-600">{activeProposal.vote_stats.votes_against}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">Participation</p>
                    <p className="text-lg font-semibold text-blue-600">{activeProposal.vote_stats.participation_rate}%</p>
                  </div>
                </div>
              )}

              <div>
                <p className="text-sm text-gray-500">Time Remaining</p>
                <p className="text-lg font-semibold">{getTimeRemaining(activeProposal.deadline)}</p>
              </div>

              {activeProposal.outcome_projection && (
                <div>
                  <p className="text-sm text-gray-500">Current Outcome</p>
                  <p className={`text-lg font-semibold ${
                    activeProposal.outcome_projection === 'likely_pass' ? 'text-green-600' :
                    activeProposal.outcome_projection === 'likely_fail' ? 'text-red-600' :
                    'text-yellow-600'
                  }`}>
                    {activeProposal.outcome_projection.replace('_', ' ').toUpperCase()}
                  </p>
                </div>
              )}

              {user && activeProposal.status === 'active' && (
                <div className="flex space-x-4 pt-4 border-t">
                  <button
                    onClick={() => handleVote(true)}
                    disabled={voting}
                    className="flex-1 bg-green-600 text-white py-2 px-4 rounded-lg hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {voting ? 'Voting...' : 'Vote For'}
                  </button>
                  <button
                    onClick={() => handleVote(false)}
                    disabled={voting}
                    className="flex-1 bg-red-600 text-white py-2 px-4 rounded-lg hover:bg-red-700 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {voting ? 'Voting...' : 'Vote Against'}
                  </button>
                </div>
              )}

              {activeProposal.status === 'active' && getTimeRemaining(activeProposal.deadline) === 'Voting ended' && (
                <button
                  onClick={handleExecuteProposal}
                  className="w-full bg-blue-600 text-white py-2 px-4 rounded-lg hover:bg-blue-700"
                >
                  Execute Proposal
                </button>
              )}
            </div>
          </div>
        )}

        {/* Create Proposal Form */}
        {user && userTokenBalance?.can_propose && (
          <div className="mb-6">
            {!showCreateForm ? (
              <button
                onClick={() => setShowCreateForm(true)}
                className="w-full bg-blue-600 text-white py-3 px-4 rounded-lg hover:bg-blue-700 font-semibold"
              >
                Create New Proposal
              </button>
            ) : (
              <div className="bg-white rounded-lg shadow p-6">
                <h2 className="text-xl font-semibold text-gray-900 mb-4">Create Proposal</h2>
                <form onSubmit={handleCreateProposal} className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Proposed Platform Fee (basis points)
                    </label>
                    <input
                      type="number"
                      min="0"
                      max="10000"
                      required
                      value={newProposal.new_fee_bps}
                      onChange={(e) => setNewProposal({ ...newProposal, new_fee_bps: e.target.value })}
                      className="w-full border border-gray-300 rounded-lg px-3 py-2"
                      placeholder="250 (2.5%)"
                    />
                    <p className="text-xs text-gray-500 mt-1">Enter basis points (0-10000). 100 bps = 1%</p>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Proposed Creator Share (basis points)
                    </label>
                    <input
                      type="number"
                      min="0"
                      max="10000"
                      required
                      value={newProposal.new_creator_share_bps}
                      onChange={(e) => setNewProposal({ ...newProposal, new_creator_share_bps: e.target.value })}
                      className="w-full border border-gray-300 rounded-lg px-3 py-2"
                      placeholder="500 (5%)"
                    />
                    <p className="text-xs text-gray-500 mt-1">Enter basis points (0-10000). 100 bps = 1%</p>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Rationale
                    </label>
                    <textarea
                      required
                      minLength="10"
                      maxLength="1000"
                      value={newProposal.rationale_text}
                      onChange={(e) => setNewProposal({ ...newProposal, rationale_text: e.target.value })}
                      className="w-full border border-gray-300 rounded-lg px-3 py-2"
                      rows="3"
                      placeholder="Explain why this change is needed..."
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Signer Secret (for transaction signing)
                    </label>
                    <input
                      type="password"
                      required
                      value={newProposal.signer_secret}
                      onChange={(e) => setNewProposal({ ...newProposal, signer_secret: e.target.value })}
                      className="w-full border border-gray-300 rounded-lg px-3 py-2"
                      placeholder="Your Stellar secret key"
                    />
                    <p className="text-xs text-gray-500 mt-1">
                      In production, this would use Freighter wallet signing
                    </p>
                  </div>

                  <div className="flex space-x-4">
                    <button
                      type="submit"
                      className="flex-1 bg-blue-600 text-white py-2 px-4 rounded-lg hover:bg-blue-700"
                    >
                      Submit Proposal
                    </button>
                    <button
                      type="button"
                      onClick={() => setShowCreateForm(false)}
                      className="flex-1 bg-gray-300 text-gray-700 py-2 px-4 rounded-lg hover:bg-gray-400"
                    >
                      Cancel
                    </button>
                  </div>
                </form>
              </div>
            )}
          </div>
        )}

        {/* Proposal History */}
        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4">Proposal History</h2>
          {proposals.length === 0 ? (
            <p className="text-gray-500">No proposals yet.</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      ID
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Proposed Fee
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Creator Share
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Status
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Created
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {proposals.map((proposal) => (
                    <tr key={proposal.id}>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        #{proposal.stellar_proposal_id}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {proposal.proposed_fee_bps} bps
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {proposal.proposed_creator_share_bps} bps
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                          proposal.status === 'executed' ? 'bg-green-100 text-green-800' :
                          proposal.status === 'failed' ? 'bg-red-100 text-red-800' :
                          proposal.status === 'active' ? 'bg-blue-100 text-blue-800' :
                          'bg-gray-100 text-gray-800'
                        }`}>
                          {proposal.status}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {new Date(proposal.created_at).toLocaleDateString()}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { api } from '../services/api';
import CampaignCard from '../components/CampaignCard';
import CampaignCardSkeleton from '../components/skeletons/CampaignCardSkeleton';
import { useAuth } from '../context/AuthContext';
import OnboardingCallout from '../components/OnboardingCallout';
import {
  isContributorOnboardingVisible,
  dismissContributorOnboarding,
  consumeJustRegistered,
} from '../lib/onboarding';
import { getRecentlyViewedIds } from '../lib/recentlyViewed';

const STATUS_OPTIONS = ['', 'active', 'funded', 'closed', 'failed'];
const ASSET_OPTIONS = ['', 'USDC', 'XLM'];
const SORT_OPTIONS = [
  { value: 'newest', key: 'home.newest', labelKey: 'home.newest' },
  { value: 'trending', labelKey: 'home.sortTrending' },
  { value: 'most_funded', key: 'home.mostFunded', labelKey: 'home.mostFunded' },
  { value: 'closest_to_goal', key: 'home.closestToGoal', labelKey: 'home.closestToGoal' },
];
const QUICK_SORT_OPTIONS = [
  { value: 'newest', labelKey: 'home.newest' },
  { value: 'trending', labelKey: 'home.sortTrending' },
  { value: 'funded', labelKey: 'home.sortMostFunded' },
];
const SEARCH_DEBOUNCE_MS = 450;

export default function Home() {
  const { t } = useTranslation();
  const [page, setPage] = useState(0);
  const [campaigns, setCampaigns] = useState([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const paginationRequestRef = useRef(false);
  const [listError, setListError] = useState('');
  const { user } = useAuth();
  const [showContributorTips, setShowContributorTips] = useState(isContributorOnboardingVisible);
  const [welcomeNewUser, setWelcomeNewUser] = useState(false);
  const [searchParams, setSearchParams] = useSearchParams();
  const [searchInput, setSearchInput] = useState(() => searchParams.get('search') || '');
  const [sort, setSort] = useState(() => searchParams.get('sort') || 'newest');
  const [categoryCounts, setCategoryCounts] = useState([]);
  const [facets, setFacets] = useState(null);
  const [featured, setFeatured] = useState([]);
  const [recentlyViewed, setRecentlyViewed] = useState([]);
  const [recommended, setRecommended] = useState([]);

  const search = searchParams.get('search') || '';
  const status = searchParams.get('status') || '';
  const asset = searchParams.get('asset') || '';
  const category = searchParams.get('category') || '';
  const minProgress = searchParams.get('min_progress') || '';
  const minFunding = searchParams.get('min_funding') || '';
  const maxFunding = searchParams.get('max_funding') || '';
  const deadlineWithin = searchParams.get('deadline_within') || '';
  const creatorVerified = searchParams.get('creator_verified') || '';
  const country = searchParams.get('country') || '';

  const limit = Number(searchParams.get('limit') || 20);
  const offset = Number(searchParams.get('offset') || 0);

  useEffect(() => {
    const urlSort = searchParams.get('sort') || 'newest';
    if (urlSort !== sort) {
      setSort(urlSort);
    }
  }, [searchParams]);

  const handleSortChange = (newSort) => {
    setSort(newSort);
    setFilters({ sort: newSort });
  };


  const hasActiveFilters =
    Boolean(search.trim()) ||
    Boolean(asset) ||
    Boolean(status) ||
    Boolean(category) ||
    Boolean(minFunding) ||
    Boolean(maxFunding) ||
    Boolean(deadlineWithin) ||
    Boolean(creatorVerified) ||
    Boolean(country) ||
    sort !== 'newest';

  useEffect(() => {
    if (consumeJustRegistered()) {
      setWelcomeNewUser(true);
    }
    api
      .getCampaignCategories()
      .then(setCategoryCounts)
      .catch(() => {});
    api
      .getCampaignFacets()
      .then(setFacets)
      .catch(() => {});
    api
      .getFeaturedCampaigns()
      .then(setFeatured)
      .catch(() => {});

    const viewedIds = getRecentlyViewedIds(6);
    if (viewedIds.length === 0) return;
    Promise.all(viewedIds.map((id) => api.getCampaign(id).catch(() => null))).then((results) => {
      const viewedCampaigns = results.filter(Boolean);
      setRecentlyViewed(viewedCampaigns);

      if (user) {
        api
          .getRecommendedCampaigns({ limit: 6 })
          .then((data) => {
            const viewedIdSet = new Set(viewedIds);
            setRecommended((Array.isArray(data) ? data : []).filter((c) => !viewedIdSet.has(c.id)).slice(0, 6));
          })
          .catch(() => {});
        return;
      }

      const categoryTally = {};
      viewedCampaigns.forEach((c) => {
        if (!c.category) return;
        categoryTally[c.category] = (categoryTally[c.category] || 0) + 1;
      });
      const topCategory = Object.entries(categoryTally).sort((a, b) => b[1] - a[1])[0]?.[0];
      if (!topCategory) return;

      api
        .getCampaigns({ category: topCategory, sort: 'trending', limit: 8 })
        .then((data) => {
          const viewedIdSet = new Set(viewedIds);
          setRecommended((data.campaigns || []).filter((c) => !viewedIdSet.has(c.id)).slice(0, 6));
        })
        .catch(() => {});
    });
  }, [user]);

  useEffect(() => {
    setSearchInput(search);
  }, [search]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (searchInput.trim() === search.trim()) return;
      setFilters({ search: searchInput.trim() });
    }, SEARCH_DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [searchInput, search]);

  useEffect(() => {
    setListError('');
    setLoading(true);
    api
      .getCampaigns({
        search,
        status,
        asset,
        category,
        min_progress: minProgress,
        min_funding: minFunding,
        max_funding: maxFunding,
        deadline_within: deadlineWithin,
        creator_verified: creatorVerified,
        country,
        sort,
        limit,
        offset,
      })
      .then((data) => {
        const nextCampaigns = data.campaigns || [];
        const nextTotal = data.total || 0;
        setCampaigns(nextCampaigns);
        setTotal(nextTotal);
        setHasMore(nextCampaigns.length < nextTotal);
        setPage(1);
      })
      .catch((err) => setListError(err.message || t('home.loadingCampaigns')))
      .finally(() => setLoading(false));
  }, [search, status, asset, category, minProgress, minFunding, maxFunding, deadlineWithin, creatorVerified, country, sort]);

  async function loadMore() {
    if (loadingMore || !hasMore || paginationRequestRef.current) return;

    paginationRequestRef.current = true;
    const scrollPosition = window.scrollY;
    setLoadingMore(true);
    setListError('');

    try {
      const { campaigns: next, total: nextTotal } = await api.getCampaigns({
        search,
        status,
        asset,
        category,
        min_progress: minProgress,
        min_funding: minFunding,
        max_funding: maxFunding,
        deadline_within: deadlineWithin,
        creator_verified: creatorVerified,
        country,
        sort,
        limit: 20,
        offset: page * 20,
      });

      setCampaigns((prev) => {
        const updated = [...prev, ...next];
        setHasMore(updated.length < nextTotal);
        return updated;
      });
      setTotal(nextTotal);
      setPage((p) => p + 1);

      window.requestAnimationFrame(() => {
        window.scrollTo({ top: scrollPosition });
      });
    } catch (err) {
      setListError(err.message || t('home.loadingCampaigns'));
    } finally {
      paginationRequestRef.current = false;
      setLoadingMore(false);
    }
  }

  const setFilters = (next) => {
    const params = new URLSearchParams(searchParams);
    Object.entries(next).forEach(([key, value]) => {
      if (value === '' || value === null) {
        params.delete(key);
      } else {
        params.set(key, String(value));
      }
    });
    params.delete('offset');
    setSearchParams(params, { replace: true });
  };

  function dismissContributorTips() {
    dismissContributorOnboarding();
    setShowContributorTips(false);
  }

  return (
    <main className="container" style={{ paddingTop: '1.5rem', paddingBottom: '4rem' }}>
      {welcomeNewUser && (
        <div className="alert alert--success" style={{ marginBottom: '1rem' }} role="status">
          <strong>{t('home.welcomeTitle')}</strong> {t('home.welcomeBody')}
          <button
            type="button"
            onClick={() => setWelcomeNewUser(false)}
            style={{
              marginLeft: '0.5rem',
              background: 'transparent',
              color: 'var(--color-success-text)',
              fontWeight: 600,
              textDecoration: 'underline',
              padding: 0,
              minHeight: 'auto',
            }}
          >
            {t('common.dismiss')}
          </button>
        </div>
      )}

      {user && showContributorTips && (
        <OnboardingCallout title={t('home.onboardingTitle')} onDismiss={dismissContributorTips}>
          <ul>
            <li>{t('home.onboardingItem1')}</li>
            <li>{t('home.onboardingItem2')}</li>
            <li>{t('home.onboardingItem3')}</li>
          </ul>
        </OnboardingCallout>
      )}

      <div style={styles.hero}>
        <h1 style={styles.h1}>{t('home.hero_title')}</h1>
        <p style={styles.sub}>{t('home.hero_subtitle')}</p>
        {user ? (
          <div className="hero-actions">
            {(user.role === 'creator' || user.role === 'admin') && (
              <Link to="/campaigns/new" style={{ width: '100%' }}>
                <button
                  type="button"
                  className="btn-primary"
                  style={{ fontSize: '1rem', padding: '0.75rem 1.5rem', width: '100%' }}
                >
                  {t('home.startCampaign')}
                </button>
              </Link>
            )}
            <span style={styles.muted}>{t('home.browseHint')}</span>
          </div>
        ) : (
          <div className="hero-actions hero-actions--row-sm">
            <Link to="/register" style={{ flex: '1 1 140px', minWidth: '140px' }}>
              <button
                type="button"
                className="btn-primary"
                style={{ fontSize: '1rem', padding: '0.75rem 1.5rem', width: '100%' }}
              >
                {t('home.createAccount')}
              </button>
            </Link>
            <Link to="/login" style={{ flex: '1 1 140px', minWidth: '140px' }}>
              <button
                type="button"
                className="btn-secondary"
                style={{ fontSize: '1rem', padding: '0.75rem 1.5rem', width: '100%' }}
              >
                {t('login.title')}
              </button>
            </Link>
          </div>
        )}
      </div>

      {featured.length > 0 && (
        <section style={{ marginBottom: '2.5rem' }}>
          <h2 style={styles.sectionTitle}>{t('home.featuredCampaigns')}</h2>
          <div
            style={{
              ...styles.grid,
              gridTemplateColumns: 'repeat(auto-fill, minmax(min(100%, 340px), 1fr))',
            }}
          >
            {featured.map((c) => (
              <CampaignCard key={c.id} campaign={c} featured />
            ))}
          </div>
        </section>
      )}

      {recommended.length > 0 && (
        <section style={{ marginBottom: '2.5rem' }}>
          <h2 style={styles.sectionTitle}>Recommended for you</h2>
          <div
            style={{
              ...styles.grid,
              gridTemplateColumns: 'repeat(auto-fill, minmax(min(100%, 300px), 1fr))',
            }}
          >
            {recommended.map((c) => (
              <CampaignCard key={c.id} campaign={c} />
            ))}
          </div>
        </section>
      )}

      {recentlyViewed.length > 0 && (
        <section style={{ marginBottom: '2.5rem' }}>
          <h2 style={styles.sectionTitle}>Recently viewed</h2>
          <div
            style={{
              ...styles.grid,
              gridTemplateColumns: 'repeat(auto-fill, minmax(min(100%, 300px), 1fr))',
            }}
          >
            {recentlyViewed.map((c) => (
              <CampaignCard key={c.id} campaign={c} />
            ))}
          </div>
        </section>
      )}

      <div style={styles.filterBar}>
        <label style={styles.filterItem}>
          {t('home.searchLabel')}
          <input
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            placeholder={t('home.searchPlaceholder')}
            style={styles.filterInput}
            aria-label={t('home.searchLabel')}
          />
        </label>
        <label style={styles.filterItem}>
          {t('home.statusLabel')}
          <select
            value={status}
            onChange={(e) => setFilters({ status: e.target.value })}
            style={styles.filterInput}
          >
            {STATUS_OPTIONS.map((option) => (
              <option key={option} value={option}>
                {option === ''
                  ? t('home.anyStatus')
                  : t(`home.status${option[0].toUpperCase()}${option.slice(1)}`)}
              </option>
            ))}
          </select>
        </label>
        <label style={styles.filterItem}>
          {t('home.assetLabel')}
          <select
            value={asset}
            onChange={(e) => setFilters({ asset: e.target.value })}
            style={styles.filterInput}
          >
            {ASSET_OPTIONS.map((option) => (
              <option key={option} value={option}>
                {option === '' ? t('home.anyAsset') : option}
              </option>
            ))}
          </select>
        </label>
        <label style={styles.filterItem}>
          Category
          <input
            value={category}
            onChange={(e) => setFilters({ category: e.target.value })}
            placeholder="e.g. tech, art"
            style={styles.filterInput}
          />
        </label>
        <label style={styles.filterItem}>
          Min Progress (%)
          <input
            type="number"
            min="0"
            max="100"
            value={minProgress}
            onChange={(e) => setFilters({ min_progress: e.target.value })}
            placeholder="e.g. 50"
            style={styles.filterInput}
          />
        </label>
        <label style={styles.filterItem}>
          Min Raised
          <input
            type="number"
            min="0"
            value={minFunding}
            onChange={(e) => setFilters({ min_funding: e.target.value })}
            placeholder={facets ? `${facets.funding?.min ?? 0}` : 'e.g. 100'}
            style={styles.filterInput}
            aria-label="Minimum amount raised"
          />
        </label>
        <label style={styles.filterItem}>
          Max Raised
          <input
            type="number"
            min="0"
            value={maxFunding}
            onChange={(e) => setFilters({ max_funding: e.target.value })}
            placeholder={facets ? `${facets.funding?.max ?? 0}` : 'e.g. 5000'}
            style={styles.filterInput}
            aria-label="Maximum amount raised"
          />
        </label>
        <label style={styles.filterItem}>
          Ending Within
          <select
            value={deadlineWithin}
            onChange={(e) => setFilters({ deadline_within: e.target.value })}
            style={styles.filterInput}
            aria-label="Deadline proximity"
          >
            <option value="">Any time</option>
            <option value="3">3 days</option>
            <option value="7">7 days</option>
            <option value="14">14 days</option>
            <option value="30">30 days</option>
          </select>
        </label>
        {facets?.countries?.length > 0 && (
          <label style={styles.filterItem}>
            Location
            <select
              value={country}
              onChange={(e) => setFilters({ country: e.target.value })}
              style={styles.filterInput}
              aria-label="Geographic location"
            >
              <option value="">Anywhere</option>
              {facets.countries.map((c) => (
                <option key={c.country} value={c.country}>
                  {c.country} ({c.count})
                </option>
              ))}
            </select>
          </label>
        )}
        <label style={{ ...styles.filterItem, flexDirection: 'row', alignItems: 'center', gap: '0.4rem' }}>
          <input
            type="checkbox"
            checked={creatorVerified === 'true'}
            onChange={(e) => setFilters({ creator_verified: e.target.checked ? 'true' : '' })}
            aria-label="Only verified creators"
          />
          Verified creators only
          {typeof facets?.verified_creators === 'number' && ` (${facets.verified_creators})`}
        </label>
        <label style={styles.filterItem}>
          Sort by
          {t('home.sortLabel')}
          <select
            value={sort}
            onChange={(e) => handleSortChange(e.target.value)}
            style={styles.filterInput}
          >
            {SORT_OPTIONS.map((option) => (
              <option key={option.value} value={option.value}>
                {option.key ? t(option.key) : t(option.labelKey)}
              </option>
            ))}
          </select>
        </label>
      </div>

      {(search || status || asset || category || minProgress || minFunding || maxFunding || deadlineWithin || creatorVerified || country) && (
        <div style={styles.activeFilters}>
          {search && (
            <button className="filter-chip" onClick={() => setFilters({ search: '' })}>
              Search: {search} ✕
            </button>
          )}
          {status && (
            <button className="filter-chip" onClick={() => setFilters({ status: '' })}>
              Status: {status} ✕
            </button>
          )}
          {asset && (
            <button className="filter-chip" onClick={() => setFilters({ asset: '' })}>
              Asset: {asset} ✕
            </button>
          )}
          {category && (
            <button className="filter-chip" onClick={() => setFilters({ category: '' })}>
              Category: {category} ✕
            </button>
          )}
          {minProgress && (
            <button className="filter-chip" onClick={() => setFilters({ min_progress: '' })}>
              Min Progress: {minProgress}% ✕
            </button>
          )}
          {minFunding && (
            <button className="filter-chip" onClick={() => setFilters({ min_funding: '' })}>
              Min Raised: {minFunding} ✕
            </button>
          )}
          {maxFunding && (
            <button className="filter-chip" onClick={() => setFilters({ max_funding: '' })}>
              Max Raised: {maxFunding} ✕
            </button>
          )}
          {deadlineWithin && (
            <button className="filter-chip" onClick={() => setFilters({ deadline_within: '' })}>
              Ending within: {deadlineWithin}d ✕
            </button>
          )}
          {creatorVerified === 'true' && (
            <button className="filter-chip" onClick={() => setFilters({ creator_verified: '' })}>
              Verified creators ✕
            </button>
          )}
          {country && (
            <button className="filter-chip" onClick={() => setFilters({ country: '' })}>
              Location: {country} ✕
            </button>
          )}
        </div>
      )}

      <h2 style={styles.sectionTitle}>{t('home.activeCampaigns')}</h2>
      <div style={styles.sortBar}>
        <button
          type="button"
          className={category === '' ? 'pill-active' : 'pill'}
          onClick={() => setFilters({ category: '' })}
        >
          {t('home.allCategories')}
        </button>
        {categoryCounts.map((cat) => (
          <button
            key={cat.category}
            type="button"
            className={category === cat.category ? 'pill-active' : 'pill'}
            onClick={() => setFilters({ category: cat.category })}
          >
            {t(`home.categories.${cat.category}`, { defaultValue: cat.category })} ({cat.count})
          </button>
        ))}
      </div>

      <div style={styles.sortBar}>
        {QUICK_SORT_OPTIONS.map((opt) => (
          <button
            key={opt.value}
            type="button"
            className={sort === opt.value ? 'pill-active' : 'pill'}
            onClick={() => handleSortChange(opt.value)}
          >
            {t(opt.labelKey)}
          </button>
        ))}
      </div>

      {loading ? (
        <div style={styles.grid}>
          {Array.from({ length: 6 }, (_, i) => (
            <CampaignCardSkeleton key={i} />
          ))}
        </div>
      ) : listError ? (
        <p className="alert alert--error" role="alert">
          {listError}
        </p>
      ) : campaigns.length === 0 ? (
        <div className="alert alert--info">
          {hasActiveFilters ? (
            <>
              {t('home.noMatches')}{' '}
              <button
                type="button"
                onClick={() => {
                  setSearchInput('');
                  setSearchParams({}, { replace: true });
                }}
                style={{
                  background: 'transparent',
                  color: 'var(--color-info-text)',
                  fontWeight: 700,
                  textDecoration: 'underline',
                  padding: 0,
                  minHeight: 'auto',
                }}
              >
                {t('common.clearFilters')}
              </button>
            </>
          ) : user && (user.role === 'creator' || user.role === 'admin') ? (
            <>
              {t('home.noCampaigns')}{' '}
              <Link
                to="/campaigns/new"
                style={{ color: 'var(--color-info-text)', fontWeight: 700 }}
              >
                {t('home.startCampaign')}
              </Link>
              .
            </>
          ) : (
            <>{t('home.noPublicCampaigns')}</>
          )}
        </div>
      ) : (
        <>
          <div style={styles.grid}>
            {campaigns.map((c) => (
              <CampaignCard key={c.id} campaign={c} />
            ))}
          </div>
          {loadingMore && (
            <div aria-busy="true" aria-live="polite" style={{ ...styles.grid, marginTop: '1.25rem' }}>
              {Array.from({ length: 4 }, (_, i) => (
                <CampaignCardSkeleton key={`pagination-skeleton-${i}`} />
              ))}
            </div>
          )}
          <div style={styles.pagination}>
            <span style={styles.paginationInfo}>
              {t('home.showingCampaigns', { count: campaigns.length, total })}
            </span>
            {hasMore && (
              <div style={styles.loadMoreContainer}>
                <button
                  type="button"
                  className="btn-secondary"
                  onClick={loadMore}
                  disabled={loadingMore}
                  style={styles.loadMoreButton}
                >
                  {loadingMore ? t('home.loadingMore') : t('home.loadMore')}
                </button>
              </div>
            )}
          </div>
        </>
      )}
    </main>
  );
}

const styles = {
  hero: { textAlign: 'center', padding: '2rem 0 2.5rem' },
  h1: {
    fontSize: 'clamp(1.85rem, 5vw, 2.85rem)',
    fontWeight: 800,
    marginBottom: '1rem',
    color: 'var(--color-text-primary)',
  },
  sub: {
    fontSize: 'clamp(0.95rem, 2.5vw, 1.1rem)',
    color: 'var(--color-text-secondary)',
    marginBottom: '1.5rem',
    maxWidth: '560px',
    margin: '0 auto 1.5rem',
    lineHeight: 1.55,
  },
  muted: {
    fontSize: '0.85rem',
    color: 'var(--color-text-hint)',
