  loadMoreButton: {
    padding: '0.75rem 2rem',
    fontSize: '1.05rem',
    cursor: 'pointer',
    borderRadius: '8px',
    border: '1px solid var(--color-border)',
  },
};

import { useEffect, useState } from 'react';
