import React, { useEffect, useState } from 'react';
import { Link, Navigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { api } from '../services/api';

const STATUS_LABELS = {
  no_referrals: 'No referrals yet',
  pending: 'Pending payout',
  paid: 'Paid out',
};

export default function ReferralDashboard() {
  const { user, ready } = useAuth();
  const [links, setLinks] = useState(null);
  const [error, setError] = useState('');
  const [copied, setCopied] = useState('');

  useEffect(() => {
    if (!user) return;
    api
      .getMyReferralLinks()
      .then((data) => setLinks(data.links || []))
      .catch((err) => setError(err.message || 'Could not load your referrals'));
  }, [user]);

  if (!ready) return null;
  if (!user) return <Navigate to="/login" replace />;

  const totalEarned = (links || []).reduce((sum, link) => sum + Number(link.commission_earned), 0);
  const totalPending = (links || []).reduce((sum, link) => sum + Number(link.commission_owed), 0);

  async function copyUrl(link) {
    try {
      await navigator.clipboard.writeText(link.share_url);
      setCopied(link.code);
      setTimeout(() => setCopied(''), 2000);
    } catch {
      setError('Could not copy to clipboard');
    }
  }

  return (
    <div style={{ maxWidth: '960px', margin: '0 auto', padding: '1.5rem 1rem' }}>
      <h1 style={{ marginBottom: '0.25rem' }}>My referrals</h1>
      <p style={{ color: 'var(--color-text-muted)', marginTop: 0 }}>
        Commission is paid to your wallet when the creator withdraws from the campaign.
      </p>

      {error && <p style={{ color: 'var(--color-danger)' }}>{error}</p>}

      <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap', margin: '1rem 0 1.5rem' }}>
        <div className="campaign-card" style={{ minHeight: 'auto', padding: '0.6rem 0.9rem' }}>
          <strong style={{ fontSize: '1.1rem' }}>{totalEarned.toFixed(7)}</strong>
          <div style={{ fontSize: '0.78rem', color: 'var(--color-text-hint)' }}>Commission earned</div>
        </div>
        <div className="campaign-card" style={{ minHeight: 'auto', padding: '0.6rem 0.9rem' }}>
          <strong style={{ fontSize: '1.1rem' }}>{totalPending.toFixed(7)}</strong>
          <div style={{ fontSize: '0.78rem', color: 'var(--color-text-hint)' }}>Awaiting payout</div>
        </div>
      </div>

      {links === null ? (
        <p>Loading…</p>
      ) : links.length === 0 ? (
        <p style={{ color: 'var(--color-text-muted)' }}>
          You have no referral links yet. Open a campaign that offers referrals and claim your link
          from its <strong>Share</strong> page.
        </p>
      ) : (
        <div className="campaign-card" style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.85rem' }}>
            <thead>
              <tr style={{ borderBottom: '2px solid var(--color-border)', textAlign: 'left' }}>
                <th style={{ padding: '0.5rem 0.75rem' }}>Campaign</th>
                <th style={{ padding: '0.5rem 0.75rem', textAlign: 'center' }}>Rate</th>
                <th style={{ padding: '0.5rem 0.75rem', textAlign: 'center' }}>Contributions</th>
                <th style={{ padding: '0.5rem 0.75rem', textAlign: 'right' }}>Referred</th>
                <th style={{ padding: '0.5rem 0.75rem', textAlign: 'right' }}>Commission</th>
                <th style={{ padding: '0.5rem 0.75rem' }}>Status</th>
                <th style={{ padding: '0.5rem 0.75rem' }}>Link</th>
              </tr>
            </thead>
            <tbody>
              {links.map((link) => (
                <tr key={link.referral_link_id} style={{ borderBottom: '1px solid var(--color-border-lighter)' }}>
                  <td style={{ padding: '0.5rem 0.75rem', fontWeight: 600 }}>
                    <Link to={`/campaigns/${link.campaign_id}`}>{link.campaign_title}</Link>
                  </td>
                  <td style={{ padding: '0.5rem 0.75rem', textAlign: 'center' }}>
                    {link.commission_percentage}%
                  </td>
                  <td style={{ padding: '0.5rem 0.75rem', textAlign: 'center' }}>
                    {link.contribution_count}
                  </td>
                  <td style={{ padding: '0.5rem 0.75rem', textAlign: 'right' }}>
                    {link.referred_amount} {link.asset_type}
                  </td>
                  <td style={{ padding: '0.5rem 0.75rem', textAlign: 'right', fontWeight: 600 }}>
                    {link.commission_earned} {link.asset_type}
                  </td>
                  <td style={{ padding: '0.5rem 0.75rem' }}>{STATUS_LABELS[link.status]}</td>
                  <td style={{ padding: '0.5rem 0.75rem' }}>
                    <button type="button" className="btn-secondary" onClick={() => copyUrl(link)}>
                      {copied === link.code ? 'Copied!' : 'Copy'}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { api } from '../services/api';
import { stellarExpertTxUrl } from '../config/stellar';

function downloadBlob({ blob, filename }) {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  URL.revokeObjectURL(url);
}

export default function TaxReceipts() {
  const [receipts, setReceipts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [downloading, setDownloading] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    let active = true;
    api
      .getTaxReceipts()
      .then((data) => {
        if (active) setReceipts(data.receipts || []);
      })
      .catch((err) => {
        if (active) setError(err.message || 'Could not load tax receipts');
      })
      .finally(() => {
        if (active) setLoading(false);
      });

    return () => {
      active = false;
    };
  }, []);

  async function downloadAll() {
    setDownloading('all');
    setError('');
    try {
      downloadBlob(await api.downloadTaxReceiptsPdf());
    } catch (err) {
      setError(err.message || 'Could not download receipts');
    } finally {
      setDownloading('');
    }
  }

  async function downloadOne(id) {
    setDownloading(id);
    setError('');
    try {
      downloadBlob(await api.downloadTaxReceiptPdf(id));
    } catch (err) {
      setError(err.message || 'Could not download receipt');
    } finally {
      setDownloading('');
    }
  }

  return (
    <main className="container" style={{ paddingTop: '2rem', paddingBottom: '3rem' }}>
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          gap: '0.75rem',
          flexWrap: 'wrap',
          marginBottom: '1rem',
        }}
      >
        <div>
          <h1 style={{ fontSize: '1.6rem', fontWeight: 800, margin: 0 }}>Tax receipts</h1>
          <p style={{ color: 'var(--color-text-secondary)', margin: '0.35rem 0 0' }}>
            Download contribution receipts for your records.
          </p>
        </div>
        {receipts.length > 0 && (
          <button
            type="button"
            className="btn-primary"
            disabled={downloading === 'all'}
            onClick={downloadAll}
          >
            {downloading === 'all' ? 'Preparing...' : 'Download all PDFs'}
          </button>
        )}
      </div>

      {error && <p className="alert alert--error">{error}</p>}

      {loading ? (
        <p style={{ color: 'var(--color-text-hint)' }}>Loading receipts...</p>
      ) : receipts.length === 0 ? (
        <p className="alert alert--info">
          No contribution receipts are available yet.{' '}
          <Link to="/discover" style={{ color: 'var(--color-accent)', fontWeight: 600 }}>
            Browse campaigns
          </Link>
          .
        </p>
      ) : (
        <div style={{ display: 'grid', gap: '0.75rem' }}>
          {receipts.map((receipt) => (
            <article key={receipt.id} className="campaign-card" style={{ minHeight: 'auto' }}>
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: '0.75rem',
                  flexWrap: 'wrap',
                }}
              >
                <div>
                  <Link
                    to={`/campaigns/${receipt.campaign_id}`}
                    style={{ color: 'var(--color-accent)', fontWeight: 700 }}
                  >
                    {receipt.campaign_title}
                  </Link>
                  <div style={{ marginTop: '0.35rem', color: 'var(--color-text-primary)' }}>
                    {Number(receipt.amount).toLocaleString()} {receipt.asset}
                  </div>
                  <div style={{ fontSize: '0.84rem', color: 'var(--color-text-secondary)' }}>
                    {new Date(receipt.created_at).toLocaleString()} | {receipt.campaign_status}
                  </div>
                  {receipt.tx_hash && (
                    <a
                      href={stellarExpertTxUrl(receipt.tx_hash)}
                      target="_blank"
                      rel="noopener noreferrer"
                      style={{
                        color: 'var(--color-accent)',
                        display: 'inline-block',
                        fontSize: '0.84rem',
                        marginTop: '0.35rem',
                      }}
                    >
                      View transaction
                    </a>
                  )}
                </div>
                <button
                  type="button"
                  disabled={downloading === receipt.id}
                  onClick={() => downloadOne(receipt.id)}
                  style={{ alignSelf: 'flex-start' }}
                >
                  {downloading === receipt.id ? 'Preparing...' : 'Download PDF'}
                </button>
              </div>
            </article>
          ))}
        </div>
      )}
    </main>
  );
}

import React from 'react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, act } from '@testing-library/react';
import { useRelativeTime } from '../hooks/useRelativeTime';
import RelativeTime from '../components/RelativeTime';

// Helper component to test useRelativeTime hook
// eslint-disable-next-line no-unused-vars
function HookTestComponent({ date }) {
  const label = useRelativeTime(date);
  return <span data-testid="hook-label">{label}</span>;
}

describe('useRelativeTime Hook & RelativeTime Component', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it('renders relative time for recent events', () => {
    const now = Date.now();
    vi.setSystemTime(now);

    // 10 seconds ago
    const tenSecsAgo = new Date(now - 10000).toISOString();
    render(<RelativeTime date={tenSecsAgo} />);

    const el = screen.getByRole('time');
    expect(el).toBeInTheDocument();

    const expected = new Intl.RelativeTimeFormat('en', { numeric: 'auto' }).format(-10, 'second');
    expect(el.textContent).toBe(expected);
    expect(el.getAttribute('title')).toBe(new Date(tenSecsAgo).toLocaleString());
  });

  it('renders relative time in minutes/hours/days', () => {
    const now = Date.now();
    vi.setSystemTime(now);

    // 5 minutes ago
    const fiveMinAgo = new Date(now - 5 * 60 * 1000).toISOString();
    const { rerender } = render(<RelativeTime date={fiveMinAgo} />);

    const expectedMin = new Intl.RelativeTimeFormat('en', { numeric: 'auto' }).format(-5, 'minute');
    expect(screen.getByRole('time').textContent).toBe(expectedMin);

    // 3 hours ago
    const threeHoursAgo = new Date(now - 3 * 3600 * 1000).toISOString();
    rerender(<RelativeTime date={threeHoursAgo} />);

    const expectedHour = new Intl.RelativeTimeFormat('en', { numeric: 'auto' }).format(-3, 'hour');
    expect(screen.getByRole('time').textContent).toBe(expectedHour);

    // 2 days ago
    const twoDaysAgo = new Date(now - 2 * 24 * 3600 * 1000).toISOString();
    rerender(<RelativeTime date={twoDaysAgo} />);

    const expectedDay = new Intl.RelativeTimeFormat('en', { numeric: 'auto' }).format(-2, 'day');
    expect(screen.getByRole('time').textContent).toBe(expectedDay);
  });

  it('falls back to absolute short date for events older than 7 days', () => {
    const now = Date.now();
    vi.setSystemTime(now);

    // 8 days ago
    const eightDaysAgo = new Date(now - 8 * 24 * 3600 * 1000).toISOString();
    render(<RelativeTime date={eightDaysAgo} />);
    const el = screen.getByRole('time');
    expect(el.textContent).toBe(
      new Date(eightDaysAgo).toLocaleDateString(undefined, {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
      })
    );
  });

  it('updates the time label automatically every 30 seconds', () => {
    const now = Date.now();
    vi.setSystemTime(now);

    const date = new Date(now).toISOString();
    render(<RelativeTime date={date} />);
    const el = screen.getByRole('time');

    const expectedNow = new Intl.RelativeTimeFormat('en', { numeric: 'auto' }).format(0, 'second');
    expect(el.textContent).toBe(expectedNow);

    // Advance time by 30 seconds
    act(() => {
      vi.advanceTimersByTime(30000);
    });

    const expected30sAgo = new Intl.RelativeTimeFormat('en', { numeric: 'auto' }).format(
      -30,
      'second'
    );
    expect(el.textContent).toBe(expected30sAgo);
  });

  it('handles invalid or empty dates gracefully', () => {
    const { container: container1 } = render(<RelativeTime date="" />);
    expect(container1.firstChild).toBeNull();

    const { container: container2 } = render(<RelativeTime date="invalid-date" />);
    expect(container2.firstChild).toBeNull();
  });
});

import { describe, it, expect, vi, afterEach } from 'vitest';
import { screen, waitFor } from '@testing-library/react';
import Dashboard from '../../pages/Dashboard';
import { renderWithProviders } from '../renderWithProviders';

const mockUser = { id: 'user1', role: 'creator' };
const mockUpdateUser = vi.fn();

vi.mock('../../context/AuthContext', () => ({
  useAuth: () => ({
    user: mockUser,
    ready: true,
    updateUser: mockUpdateUser,
  }),
}));

const apiMocks = vi.hoisted(() => ({
  getMyBalance: vi.fn().mockResolvedValue({ balance: { USDC: '100' } }),
  getMe: vi.fn().mockResolvedValue({ id: 'user1', role: 'creator' }),
  getMyStats: vi.fn().mockResolvedValue({ total_campaigns: 1 }),
  getUserDashboardAnalytics: vi.fn().mockResolvedValue([]),
  getMyCampaigns: vi.fn().mockResolvedValue({ data: [], pagination: { totalPages: 1, total: 0 } }),
}));

vi.mock('../../services/api', () => ({ api: apiMocks }));

describe('Dashboard page', () => {
  afterEach(() => {
    vi.clearAllMocks();
  });

  it('renders the dashboard heading and balance section', async () => {
    renderWithProviders(<Dashboard />);

    expect(await screen.findByRole('heading', { name: /Dashboard/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Add Funds/i })).toBeInTheDocument();
  });

  it('shows an error message when the dashboard APIs fail', async () => {
    apiMocks.getMyStats.mockRejectedValueOnce(new Error('Dashboard failed'));

    renderWithProviders(<Dashboard />);

    expect(await screen.findByText('Dashboard failed')).toBeInTheDocument();
  });
});

import React from 'react';
import { render } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { ThemeProvider } from '../context/ThemeContext';
import { ToastProvider } from '../context/ToastContext';
import { NetworkStatusProvider } from '../context/NetworkStatusContext';

export function renderWithProviders(ui, { route = '/', ...options } = {}) {
  const Wrapper = ({ children }) => (
    <ThemeProvider>
      <ToastProvider>
        <NetworkStatusProvider>
          <MemoryRouter initialEntries={[route]}>{children}</MemoryRouter>
        </NetworkStatusProvider>
      </ToastProvider>
    </ThemeProvider>
  );

  return render(ui, { wrapper: Wrapper, ...options });
}
